(window.GIM_TS=window.GIM_TS||{})["Bava Metzia.0"]={"from":0,"a":[["\u0003שנים\u0004 שבאו לבית הדין והם \u0003אוחזין בטלית, זה אומר: \"אני מצאתיה\", וזה אומר: \"אני מצאתיה\". זה אומר \"כולה שלי\", וזה אומר: \"כולה שלי\".\u0004 מה יעשו? — \u0003זה,\u0004 אחד מהם, \u0003ישבע שאין לו בה פחות מחציה, וזה ישבע שאין לו בה פחות מחציה\u0004 — \u0003ויחלוקו\u0004 בה.","וכן אם היה \u0003זה אומר: \"כולה שלי\", וזה אומר: \"חציה שלי\",\u0004 כיון שלדברי שניהם חצי מהטלית ודאי שייכת לאחד, והוויכוח ביניהם אינו אלא על החצי האחר, יעשו בדומה לכך: \u0003האומר \"כולה שלי\"\u0004 — \u0003ישבע שאין לו בה פחות משלשה חלקים\u0004 (שלושה רבעים) \u0003והאומר \"חציה שלי\" ישבע שאין לו בה פחות מרביע\u0004 (רבע), \u0003זה נוטל שלשה חלקים, וזה נוטל רביע.\u0004","וכן אם \u0003היו שנים רוכבין על גבי בהמה, או שהיה אחד רוכב\u0004 על גבי בהמה \u0003ואחד מנהיג,\u0004 מחזיק באפסר, \u0003זה אומר: \"כולה שלי\", וזה אומר: \"כולה שלי\"\u0004 — \u0003זה ישבע שאין לו בה פחות מחציה, וזה ישבע שאין לו בה פחות מחציה, ויחלוקו.\u0004","\u0003בזמן שהם מודים\u0004 זה לזה בטענה \u0003או שיש להן עדים\u0004 כל אחד לטענתו — \u0003חולקין בלא שבועה,\u0004 שאין שבועה אלא במקום שאין ביד הטוענים להוכיח את טענותיהם בדרך אחרת.","שואלים: \u0003למה לי למתנא\u0004 \u0005[לשנות]\u0006 סגנון כפול זה \u0003\"זה אומר אני מצאתיה וזה אומר אני מצאתיה, זה אומר כולה שלי וזה אומר כולה שלי\",\u0004 והלא לכאורה היא חזרה מיותרת, \u0003ליתני חדא\u0004 \u0005[שישנה\u0006 דיבור \u0005אחד]\u0006 וטענה אחת, ולא יאמר פעמיים \"זה אומר\" \"זה אומר\"! ומשיבים: אכן כך צריך להבין, \u0003חדא קתני\u0004 \u0005[אחת\u0006 היא ש\u0005שנינו],\u0006 וכך יש לשנות: \u0003זה אומר \"אני מצאתיה וכולה שלי\", זה אומר \"אני מצאתיה וכולה שלי\".\u0004","ושואלים עוד: \u0003וליתני\u0004 \u0005[ושישנה]\u0006 \u0003\"אני מצאתיה\"\u0004 ודי בכך, \u0003ואנא ידענא\u0004 \u0005[ואני יודע]\u0006 שכוונתו לומר ש\u0003כולה שלי!\u0004 ומשיבים: \u0003אי תנא\u0004 \u0005[אם היה שונה]\u0006 \u0003\"אני מצאתיה\"\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מצאתיה\"\u0004 שהוא אומר, כוונתו — \u0003ראיתיה,\u0004 כלומר, אני ראיתי תחילה מציאה זו. \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא אתאי לידיה\u0004 \u0005[הגיעה לידו]\u0006 ולא החזיק בה — \u0003בראיה בעלמא קני\u0004 \u0005[בלבד קנה]\u0006 בה זכות, ואפשר היה לחשוב שיש ממש בטענה כזו, על כן \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003\"כולה שלי\"\u0004 ללמדנו ש\u0003בראיה\u0004 בלבד \u0003לא קני\u0004 \u0005[אינו קונה].\u0006","ומקשים: \u0003ומי מצית אמרת מאי\u0004 \u0005[והאם יכול אתה לומר\u0006 כי \u0005מה\u0006 הפירוש\u0005]\u0006 \u0003\"מצאתיה\"\u0004 — \u0003ראיתיה, והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבנאי\u0004 בפירוש הכתוב \"וכן תעשה לכל אבדת אחיך אשר תאבד ממנו ומצאתה\" (דברים כב, ג), \u0003\"ומצאתה\"\u0004 — \u0003דאתאי לידיה\u0004 \u0005[שבאה לידו]\u0006 \u0003משמע,\u0004 שאין לשון מציאה בתורה אלא כאשר מחזיק המוצא את החפץ בידו, ולא די בראיה בלבד.","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 לשון \u0003\"ומצאתה\" דקרא\u0004 \u0005[שבכתוב]\u0006 — אכן \u0003דאתא לידיה\u0004 \u0005[שבא לידו]\u0006 \u0003משמע,\u0004 \u0003ומיהו\u0004 \u0005[ואולם]\u0006 ה\u0003תנא\u0004 — \u0003לישנא דעלמא נקט\u0004 \u0005[לשון העולם,\u0006 הבריות, \u0005תפס],\u0006 \u0003ומדחזי ליה אמר\u0004 \u0005[ומ\u0006כיון \u0005ש\u0006אדם \u0005רואה אותה\u0006 הריהו \u0005אומר]:\u0006 \u0003אנא אשכחית\u0004 \u0005[אני מצאתי],\u0006 \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא אתאי לידיה\u0004 \u0005[בא לידו\u0006 החפץ\u0005]\u0006 לפי ש\u0003בראיה בעלמא קני\u0004 \u0005[בלבד קנה],\u0006 על כן \u0003תני\u0004 \u0005[שנה]:\u0006 \u0003\"כולה שלי\"\u0004 כדי להשמיענו ש\u0003בראיה בעלמא\u0004 \u0005[בלבד]\u0006 \u0003לא קני לה\u0004 \u0005[אינו קונה אותה].\u0006","ומקשים: אם לשם כך נאמרו הדברים, \u0003וליתני\u0004 \u0005[ושישנה]\u0006 \u0003\"כולה שלי\" ולא בעי\u0004 \u0005[יצטרך]\u0006 לומר עוד \u0003\"אני מצאתיה\"!\u0004 ומשיבים: \u0003אי תני\u0004 \u0005[אם היה שונה]\u0006 \u0003\"כולה שלי\" הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003בעלמא דקתני\u0004 \u0005[בכלל\u0006 \u0005ש\u0006כאשר הוא \u0005שונה]\u0006 \u0003\"מצאתיה\"\u0004 כוונתו ש\u0003בראיה בעלמא קני\u0004 \u0005[בלבד\u0006 הוא \u0005קונה]\u0006 על כן \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003\"אני מצאתיה\" והדר תנא\u0004 \u0005[וחזר ושנה]\u0006 \u0003\"כולה שלי\"\u0004 ש\u0003ממשנה יתירה\u0004 (מייתור הלשון של המשנה) \u0003אשמעינן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003ראיה\u0004 בלבד \u0003לא קני\u0004 \u0005[אינה קונה].\u0006","לאחר שהגענו לסיכום זה של הפירוש מקשים על עיקרו: \u0003ומי מצית אמרת חדא קתני\u0004 \u0005[והאם יכול אתה לומר\u0006 כי דבר \u0005אחד\u0006 וטענה אחת \u0005שנינו]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 בלשון \u0003\"זה\" ו\"זה\"\u0004 \u0003קתני\u0004 \u0005[שנינו],\u0006 \u0003\"זה אומר אני מצאתיה וזה אומר אני מצאתיה, זה אומר כולה שלי\" וכו',\u0004 משמע שיש פה שתי טענות נפרדות, ולא אותה טענה עצמה.","\u0003אמר רב פפא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב שימי בר אשי ואמרי לה כדי\u0004 \u0005[ויש אומרים אף אחד\u0006 לא\u0005],\u0006 שנמסר בלא שם אדם: ב\u0003רישא\u0004 \u0005[ראשה]\u0006 ששנינו \"זה אומר אני מצאתיה וזה אומר אני מצאתיה\" מדובר \u0003במציאה\u0004 שמצאו שנים חפץ אחד, \u0003וסיפא\u0004 \u0005[ו\u0006ב\u0005סופה]\u0006 ששנינו \"זה אומר כולה שלי וזה אומר כולה שלי\" מדובר \u0003ב\u0004ענין \u0003מקח וממכר,\u0004 שכל אחד טוען כי הוא שקנה את החפץ מיד המוכר, וכי החפץ שייך לו,","\u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו שני המקרים;"],["\u0003דאי תנא\u0004 \u0005[שאם\u0006 היה \u0005שונה]\u0006 \u0003מציאה\u0004 בלבד \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003מציאה הוא דרמו רבנן\u0004 \u0005[שהטילו חכמים]\u0006 \u0003שבועה עליה\u0004 \u0005[עליו]\u0006 \u0003משום דמורי ואמר\u0004 \u0005[ש\u0006הוא \u0005מורה\u0006 היתר לעצמו \u0005ואומר]:\u0006 \u0003חבראי לאו מידי חסר בה, איזל אתפיס ואתפליג בהדיה\u0004 \u0005[חברי אינו חסר דבר\u0006 אם אקח ממנו, שהרי גם הוא רק מצאה, \u0005אלך\u0006 איפוא \u0005ו\u0006\u0005אתפוס ממנו ואחלוק עמו],\u0006 \u0003אבל מקח וממכר, דליכא למימר הכי\u0004 \u0005[שאין לומר כך],\u0006 שהרי שילם כסף — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ולא נחייבו שבועה.","\u0003ואי תנא\u0004 \u0005[ואם היה שונה]\u0006 \u0003מקח וממכר\u0004 היינו אומרים: במקח וממכר \u0003הוא דרמו רבנן\u0004 \u0005[שהטילו חכמים]\u0006 \u0003שבועה עליה\u0004 \u0005[עליו]\u0006 \u0003משום דמורי ואמר\u0004 \u0005[ש\u0006הוא \u0005מורה\u0006 היתר לעצמו \u0005ואומר]:\u0006 \u0003חבראי דמי קא יהיב ואנא דמי קא יהיבנא\u0004 \u0005[חברי דמים,\u0006 כסף, \u0005נתן\u0006 למוכר \u0005ואני דמים נתתי],\u0006 \u0003השתא דצריכא לדידי אשקליה אנא, וחבראי ליזיל לטרח ליזבן\u0004 \u0005[עכשיו ש\u0006החפץ \u0005נחוץ לי, אקחנו אני, וחברי ילך יטרח ויקנה],\u0006 \u0003אבל מציאה, דליכא למימר הכי\u0004 \u0005[שאין לומר כך]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נחשוד שחטף מה שאינו שלו. על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הדברים.","ושואלים: אם מדובר ב\u0003מקח וממכר, ולחזי זוזי ממאן נקט\u0004 \u0005[ושיראו\u0006 את ה\u0005כספים ממי לקח\u0006 אותם המוכר\u0005]?\u0006 שזה שנתן לו את הכסף ודאי הוא הקונה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 לומר אלא במקרה \u0003דנקט מתרוייהו\u0004 \u0005[שלקח משניהם\u0006 כסף\u0005]\u0006 אלא שהיה זה \u0003מחד מדעתיה ומחד בעל כרחיה\u0004 \u0005[מאחד\u0006 נטל \u0005מדעתו,\u0006 מרצונו, שרצה למכור לו, \u0005ומאחד\u0006 נטל \u0005בעל כורחו],\u0006 שהכריחו לקבל את הכסף מידו, \u0003ו\u0004אולם \u0003לא ידענא\u0004 \u0005[אין אנו יודעים]\u0006 \u0003מי הוא\u0004 זה שנתן לו \u0003מדעתיה\u0004 \u0005[מדעתו,\u0006 מרצונו\u0005],\u0006 \u0003ומי הוא\u0004 זה שנתן לו \u0003בעל כרחיה\u0004 \u0005[כורחו],\u0006 ולכן אין לברר אלא בשבועה.","לגוף הסברות במשנה מציעים: \u0003לימא מתניתין\u0004 \u0005[\u0006האם \u0005נאמר\u0006 כי \u0005משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003בן ננס, דאי\u0004 \u0005[שאם]\u0006 נאמר שהיא \u0003כ\u0004שיטת \u0003בן ננס, האמר\u0004 \u0005[הרי אמר]\u0006 לגבי מקרה שכאשר אמר אדם לפועלו: \"לך לחנווני והוא יתן לך מזונות כדי משכורתך\", ולאחר זמן בא הפועל וטען שלא נתן לו החנווני מאומה, והחנווני טוען שנתן. אמרו חכמים שגם החנווני וגם הפועל ישבעו על טענתם, ובעל הבית ישלם לשניהם.","ובן ננס אמר: \u0003כיצד אלו ואלו באין לידי שבועת שוא?\u0004 שהלא ודאי שאחד מהם משקר, וכיון שאין בידינו להוכיח זאת, מוטב שיקבלו שניהם בלא שבועה. ואף כאן, כיון שבסופו של דבר יקבל כל אחד את החלק שהוא מחזיק בו, מוטב שיקבלו בלא להשבע. ואם אין אומרים כן, משמע שסוברים שלא כדברי בן ננס!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת \u0003בן ננס, התם\u0004 \u0005[שם]\u0006 \u0003ודאי איכא\u0004 \u0005[יש]\u0006 \u0003שבועת שוא,\u0004 שהלא ברור שאחד מהם משקר, ואולם \u0003הכא איכא למימר דליכא\u0004 \u0005[כאן יש\u0006 מקום \u0005לומר שאין]\u0006 \u0003שבועת שוא,\u0004 \u0003אימור דתרוייהו בהדי הדדי אגבהוה\u0004 \u0005[אמור ששניהם יחד הגביהו אותה,\u0006 את המציאה\u0005],\u0006 ובזה יודה בן ננס שישבעו שניהם.","ומציעים עוד: \u0003לימא מתניתין\u0004 \u0005[האם נאמר\u0006 כי \u0005משנתנו]\u0006 היא ש\u0003לא\u0004 \u0003כ\u0004שיטת \u0003סומכוס? דאי\u0004 \u0005[שאם]\u0006 היא \u0003כ\u0004שיטת \u0003סומכוס הא\u0004 \u0005[הרי]\u0006 הוא קבע כלל יסודי: \u0003ממון המוטל בספק,\u0004 שאין יכולים לברר למי הוא שייך — \u0003חולקין\u0004 בין הטוענים לו \u0003בלא שבועה.\u0004","ומקשים: \u0003ואלא מאי\u0004 \u0005[מה\u0006 תאמר\u0005]\u0006 — שמשנתנו כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על סומכוס, \u0003הא אמרי\u0004 \u0005[הרי\u0006 הם \u0005אמרו]\u0006 שממון המוטל בספק \u0003המוציא מחברו עליו הראיה,\u0004 וכאן הלא אין הצדדים מביאים ראיה!","את הקושיה הזו דוחים: \u0003האי מאי\u0004 \u0005[זה מהו],\u0006 כלומר, מה טיבה של קושיה זו, \u0003אי אמרת בשלמא רבנן\u0004 \u0005[נניח אם אומר אתה\u0006 שמשנתנו כשיטת \u0005חכמים],\u0006 יש לחלק: \u0003התם\u0004 \u0005[שם],\u0006 במקרה של ממון בספק ש\u0003לא תפסי תרוייהו\u0004 \u0005[תפסו שניהם]\u0006 את הממון \u0003אמרו\u0004 חכמים: \u0003המוציא מחבירו עליו הראיה,\u0004 שהמחזיק בממון או בחפץ יש לו לכאורה זכות ראשונה, ואולם \u0003הכא דתרוייהו תפסי\u0004 \u0005[כאן ששניהם תפסו],\u0006 ואין כאן אחד המחזיק בבעלות, \u0003פלגי לה\u0004 \u0005[חולקים אותה]\u0006 \u0003בשבועה.\u0004","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי שיטת \u0003סומכוס\u0004 היא, \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ומה התם\u0004 \u0005[שם]\u0006 ש\u0003לא תפסי תרוייהו\u0004 \u0005[תפסו שניהם],\u0006 בכל זאת \u0003חולקין\u0004 הם \u0003בלא שבועה, הכא דתרוייהו תפסי לה\u0004 \u0005[כאן ששניהם תופסים אותה]\u0006 \u0003לא כל שכן\u0004 שחולקים בלא שבועה!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת \u0003סומכוס\u0004 אלא שיש לחלק בין המקרים; \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר סומכוס\u0004 את הכלל ביחס לממון המוטל בספק, הרי זה ב\u0003שמא ושמא,\u0004 כלומר, כאשר כל אחד מן הצדדים אינו טוען בוודאות לבעלותו אלא אף הוא אומר שאין לאחר הוכחות טובות יותר ושמא הוא הזכאי, \u0003אבל\u0004 טענות \u0003ברי וברי\u0004 \u0005[ודאי וודאי],\u0006 ששניהם טוענים בוודאות שהממון הוא שלהם — \u0003לא אמר\u0004 סומכוס שיחלקו בלא שבועה.","ושואלים: \u0003ול\u0004שיטת \u0003רבה בר רב הונא,\u0004 ש\u0003אמר: אמר סומכוס\u0004 שחולקים בלא שבועה \u0003אפילו\u0004 בטענת \u0003ברי וברי, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומתרצים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003סומכוס\u0004 ולשיטה זו אפשר לומר \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר סומכוס\u0004 את הכלל האמור, הרי זה דווקא \u0003היכא דאיכא דררא דממונא\u0004 \u0005[במקום שיש גרר,\u0006 זיקה \u0005של ממון],\u0006 כלומר, שהספק בדבר הבעלות על הממון קיים מעצמו גם בלא שיפרשו הצדדים את טענותיהם, \u0003אבל היכא דליכא דררא דממונא\u0004 \u0005[במקום שאין גרר,\u0006 זיקה \u0005של ממון]\u0006 — \u0003לא\u0004 יחלוקו.","ותוהים: \u0003ולאו\u0004 \u0005[והאם לא]\u0006 \u0003קל וחומר הוא? ומה התם דאיכא דררא דממונא למר, ואיכא דררא דממונא למר\u0004 \u0005[ומה שם שיש גרר,\u0006 זיקה \u0005של ממון לזה, ויש גרר של ממון לזה],\u0006 כלומר, שיש מקום לומר שהכסף שייך כולו לאחד מהם,"],["\u0003ואיכא למימר\u0004 \u0005[ויש לומר]\u0006 ש\u0003כולה למר\u0004 \u0005[לזה],\u0006 \u0003ואיכא למימר\u0004 \u0005[ויש לומר]\u0006 ש\u0003כולה למר\u0004 \u0005[לזה],\u0006 \u0003אמר סומכוס: ממון המוטל בספק\u0004 — \u0003חולקין בלא שבועה, הכא, דליכא דררא דממונא\u0004 \u0005[כאן שאין גרר,\u0006 זיקה, \u0005של ממון]\u0006 השייך בודאי לאחד מהם, \u0003דאיכא למימר דתרוייהו\u0004 \u0005[ש\u0006הרי \u0005יש לומר שלשניהם]\u0006 \u0003היא\u0004 שייכת, \u0003לא כל שכן\u0004 שיחלקו!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת \u0003סומכוס,\u0004 ואולם \u0003שבועה זו\u0004 כולה \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003היא\u0004 \u0003כ\u0004דברי \u0003ר' יוחנן.\u0004 ש\u0003אמר ר' יוחנן: שבועה זו\u0004 של שנים האוחזים בטלית \u0003תקנת חכמים היא, שלא יהא כל אחד ואחד הולך ותוקף\u0004 (מחזיק) \u0003בטליתו של חבירו ואומר: שלי היא.\u0004","ומציעים: \u0003לימא מתניתין\u0004 \u0005[האם נאמר\u0006 ש\u0005משנתנו]\u0006 ש\u0003לא\u0004 \u0003כ\u0004שיטת \u0003ר' יוסי\u0004 היא? שנחלקו תנאים במקרה שהפקידו שני אנשים כסף, אחד מהם הפקיד מנה (מאה דינרים) והאחד מאתיים, ושכח מחזיק הפקדון מי מהם נתן לו את הסכום הגדול, ועתה שניהם באים וכל אחד מהם טוען שהוא שלו, ומוכן להישבע על כך, ואמרו חכמים שיתנו לכל אחד מהם רק את הסכום הקטן והשאר יהא מונח עד שיבוא אליהו הנביא ויודיע בנבואתו מי הוא הצודק, \u0003דאי\u0004 \u0005[שאם\u0006 תאמר\u0005]\u0006 שהיא \u0003כ\u0004שיטת \u0003ר' יוסי\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 הוא \u0003אמר:\u0004 \u0003אם כן מה הפסיד\u0004 ה\u0003רמאי? אלא, הכל יהא מונח עד שיבא אליהו.\u0004","כנגד טענה זו מקשים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 רצונך לומר — שמשנתנו כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא החולקים על ר' יוסי \u0003כיון דאמרי רבנן\u0004 \u0005[שאמרו חכמים]\u0006 שם: \u0003השאר יהא מונח עד שיבא אליהו, הא נמי\u0004 \u0005[זה גם כן]\u0006 \u0003כשאר דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 \u0003דספיקא היא\u0004 \u0005[ש\u0006הרי \u0005ספק הוא],\u0006 ואף לשיטתם אינם צריכים לחלק אלא להשאיר את הטלית ברשות בית דין!","קושיה זו דוחים: \u0003האי מאי\u0004 \u0005[זה מהו],\u0006 מה תירוץ ומה הגיון הוא זה? \u0003אי אמרת בשלמא רבנן\u0004 \u0005[נניח אם אומר אתה\u0006 שכשיטת \u0005חכמים\u0006 היא\u0005],\u0006 \u0003התם\u0004 \u0005[שם]\u0006 ש\u0003ודאי האי מנה דחד מינייהו\u0004 \u0005[מנה זה של אחד מהם]\u0006 \u0003הוא\u0004 ומכל מקום \u0003אמרי רבנן\u0004 \u0005[אמרו חכמים]:\u0006 \u0003יהא מונח עד שיבא אליהו, הכא דאיכא למימר דתרוייהו\u0004 \u0005[\u0006\u0005כאן שיש\u0006 מקום \u0005לומר שלשניהם\u0006 הוא\u0005]\u0006 \u0003אמרי רבנן פלגי\u0004 \u0005[אומרים חכמים\u0006 ש\u0005יחלקו]\u0006 \u0003בשבועה.\u0004","\u0003אלא, אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי שיטת \u0003ר' יוסי היא,\u0004 \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ומה התם דבודאי איכא\u0004 \u0005[שם שוודאי\u0006 ש\u0005יש]\u0006 \u0003מנה למר\u0004 \u0005[לזה]\u0006 \u0003ואיכא\u0004 \u0005[ויש]\u0006 \u0003מנה למר\u0004 \u0005[לזה]\u0006 ובכל זאת \u0003אמר ר' יוסי\u0004 שהכל \u0003יהא מונח עד שיבא אליהו, הכא דאיכא למימר דחד מינייהו\u0004 \u0005[כאן שיש\u0006 מקום \u0005לומר של אחד\u0006 מהם\u0005]\u0006 \u0003הוא\u0004 — \u0003לא כל שכן\u0004 שראוי להניח הכל, שהרי יתכן שתהא פה רמאות גמורה מתחילתה!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת \u0003ר' יוסי,\u0004 \u0003התם\u0004 \u0005[שם]\u0006 — \u0003ודאי איכא\u0004 \u0005[יש]\u0006 \u0003רמאי\u0004 שהוא אחד מן השניים, ואולם \u0003הכא מי יימר דאיכא\u0004 \u0005[כאן, מי יאמר שיש]\u0006 \u0003רמאי? אימא תרוייהו בהדי הדדי אגבהוה\u0004 \u0005[אמור\u0006 ש\u0005שניהם ביחד הגביהו אותה]\u0006 ומשום כך אין לקונסם.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר: \u0003התם קניס ליה\u0004 \u0005[שם קונס אותו]\u0006 \u0003ר' יוסי\u0004 את ה\u0003רמאי\u0004 במנה שלו \u0003כי היכי דלודי\u0004 \u0005[כדי שיודה]\u0006 ששיקר, כדי שיוכל לפחות לקבל את המנה שלו, ואולם \u0003הכא מאי פסידא אית ליה דלודי\u0004 \u0005[כאן מה הפסד יש לו שיודה],\u0006 ויכול הוא להשאיר את החפץ ברשות בית דין, שהרי אינו מפסיד כלום.","ודוחים: \u0003תינח\u0004 \u0005[נניח]\u0006 דבר זה במקרה של \u0003מציאה\u0004 שלא הוציא על כך מאומה, ולכן אין לו סיבה להודות, ואולם \u0003מקח וממכר מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי מסתבר ששניהם שילמו ולא ירצו להפסיד! \u0003אלא מחוורתא כדשנין מעיקרא\u0004 \u0005[מחוור כפי שתרצנו מתחילה]\u0006 שההבדל בין המקרים הוא שבמשנתנו אין ודאות שאחד מהם רמאי.","ומעירים: \u0003בין ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003ובין ל\u0004שיטת \u0003ר' יוסי, התם גבי\u0004 \u0005[שם אצל]\u0006 \u0003חנוני על פנקסו דקתני\u0004 \u0005[ששנינו]\u0006 ש\u0003זה,\u0004 החנווני, \u0003נשבע\u0004 שנתן \u0003ונוטל\u0004 מבעל הבית, \u0003וזה,\u0004 הפועל, \u0003נשבע ונוטל,\u0004","\u0003מאי שנא דלא אמרינן נפקיה לממונא\u0004 \u0005[מה שונה שאין אנו אומרים\u0006 שם ש\u0005נוציא את הממון]\u0006 \u0003מבעל הבית,\u0004 \u0003ויהא מונח עד שיבא אליהו,\u0004 לשיטת ר' יוסי, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003בודאי איכא\u0004 \u0005[יש]\u0006 \u0003רמאי\u0004 שם, ולא יתכן שגם החנווני וגם הפועל יהיו צודקים!","על כך משיבים: \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003התם היינו טעמא\u0004 \u0005[שם זהו הטעם]\u0006 — משום \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 ה\u0003חנוני לבעל הבית: אנא שליחותא דידך קא עבדינא\u0004 \u0005[אני\u0006 את ה\u0005שליחות שלך עשיתי]\u0006 לתת לפועל את המזונות, ואין לי עסק אלא עמך, \u0003מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לי גבי\u0004 \u0005[אצל,\u0006 עם\u0005]\u0006 ה\u0003שכיר,\u0004 הלא אין לי כל משא ומתן אתו, ו\u0003אף על גב דקא משתבע\u0004 \u0005[אף על פי שיישבע]\u0006 \u0003לי,\u0004 שלא קיבל דבר ממנו, \u0003לא מהימן לי\u0004 \u0005[אינו נאמן עלי]\u0006 \u0003בשבועה,\u0004 ורק \u0003את האמנתיה\u0004 \u0005[אתה האמנת לו]\u0006 ש\u0003לא אמרת לי בסהדי הב ליה\u0004 \u0005[בעדים תן לו]\u0006 על כן חייב אתה לשלם לי מכל מקום. ואם יש לך טענות — פנה אל השכיר.","\u0003ו\u0004כן \u0003שכיר נמי אמר ליה\u0004 \u0005[\u0006יכול הוא \u0005לומר לו],\u0006 \u0003לבעל הבית: אנא עבדי עבידתא גבך, מאי אית\u0004 \u0005[אני עבדתי עבודה אצלך, מה יש]\u0006 \u0003לי גבי\u0004 \u0005[אצל,\u0006 עם\u0005]\u0006 ה\u0003חנוני,\u0004 ו\u0003אף על גב דמשתבע\u0004 \u0005[אף על פי שיישבע]\u0006 \u0003לי\u0004 שקיבלתי ממנו \u0003לא מהימן לי\u0004 \u0005[אינו נאמן עלי].\u0006 \u0003הלכך, תרוייהו משתבעי ושקלי\u0004 \u0005[על כן שניהם נשבעים ולוקחים]\u0006 \u0003מבעל הבית.\u0004","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 בברייתא: הטוען לחבירו \u0003\"מנה\u0004 (מאה דינרים) \u0003לי בידך\",\u0004 שלווית ממני ולא פרעת, \u0003והלה,\u0004 הנתבע, \u0003אומר: אין לך בידי כלום, והעדים מעידים אותו שיש לו חמשים זוז\u0004 (דינרים) — \u0003נותן לו חמשים זוז,\u0004 כפי שהעידו העדים \u0003וישבע על השאר\u0004 שאכן לא לוה ממנו את חמישים הזוז הנותרים.","והסברה לביסוס דין זה — \u0003שלא תהא הודאת פיו גדולה מהעדאת עדים, מקל וחומר.\u0004 שהרי הלכה היא שאדם המודה במקצת הטענה שטוענים כנגדו — חייב להשבע על מה שלא הודה בו ונפטר. וכאן שעדים מעידים שהוא חייב במקצת הטענה קל וחומר הוא שצריך הוא להשבע.","\u0003ו\u0004מעירים: \u0003תנא תונא\u0004 \u0005[\u0006ו\u0005שנה התנא\u0006 שלנו\u0005]\u0006 במשנה כעין זה: \u0003שנים אוחזין בטלית זה אומר אני מצאתיה\u0004 וכו', \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 במציאה, \u0003כיון דתפיס\u0004 \u0005[שתפס]\u0006 אותו אדם חלק מן הטלית \u0003אנן סהדי\u0004 \u0005[אנו עדים],\u0006 כלומר, הדבר ברור והכל עדים בו \u0003דמאי דתפיס האי דידיה\u0004 \u0005[שמה שתפס זה, שלו]\u0006 \u0003הוא, ומאי דתפיס האי דידיה\u0004 \u0005[ומה שתפס זה, שלו]\u0006 \u0003הוא,\u0004 והרי זה כעדים המעידים על כל אחד שהוא צודק בחלק מן התביעה, \u0003וקתני\u0004 \u0005[ושנינו]:\u0006 \u0003ישבע!\u0004 הרי שאדם נשבע על מקצת הטענה שעדים מעידים על חלקה האחר. שהרי אף כאן הכל מעידים בעובדה שהאחר מחזיק חלק מן החפץ. עד כאן לעיקר דברי ר' חייא.","ומעתה באים לברר \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שלא תהא הודאת פיו גדולה מהעדאת עדים מקל וחומר\",\u0004 כלומר, מדוע הוצרך לקל וחומר כדי לומר דבר שלכאורה הוא מובן מאליו? ומסבירים: \u0003שלא תאמר\u0004 שב\u0003הודאת פיו הוא דרמיא רחמנא\u0004 \u0005[שהטילה התורה]\u0006 \u0003שבועה עליה\u0004 \u0005[עליו]\u0006 \u0003כ\u0004פי הסברו של \u0003רבה.\u0004","ש\u0003אמר רבה: מפני מה אמרה תורה\u0004 ש\u0003מודה מקצת הטענה ישבע?\u0004 — הדבר מבוסס על הנחה בדבר מניעיו של המכחיש. \u0003חזקה\u0004 \u0005[מוחזק\u0006 בידנו, ברור לנו\u0005]\u0006 ש\u0003אין אדם מעיז פניו בפני בעל חובו\u0004 להיות כפוי טובה לגמרי ולשקר בפניו, \u0003והאי בכוליה בעי דנכפריה\u0004 \u0005[ו\u0006אדם \u0005זה ב\u0006חוב \u0005כולו היה רוצה לכפור]\u0006 \u0003והא\u0004 \u0005[וזה]\u0006 ש\u0003לא כפריה\u0004 \u0005[כפר בו]\u0006 — \u0003משום\u0004 ש\u0003אין אדם מעיז פניו\u0004"],["\u0003והאי בכוליה בעי דלודי ליה\u0004 \u0005[ו\u0006אדם \u0005זה בכל רצה להודות לו]\u0006 מפני הכרת הטובה. \u0003והאי\u0004 \u0005[וזה]\u0006 ש\u0003לא אודי\u0004 \u0005[הודה]\u0006 לו — \u0003אשתמוטי הוא דקא מישתמט מיניה\u0004 \u0005[\u0006משום \u0005ש\u0006הוא \u0005משתמט ממנו]\u0006 \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005],\u0006 שאומר הוא לעצמו: אשתמט ממנו \u0003עד דהוו\u0004 \u0005[שיהיו]\u0006 \u0003לי זוזי ופרענא ליה\u0004 \u0005[מעות ואפרע לו],\u0006 ולכן \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]:\u0006 \u0003רמי\u0004 \u0005[הטל]\u0006 \u0003שבועה עליה\u0004 \u0005[עליו]\u0006 \u0003כי היכי דלודי ליה בכוליה\u0004 \u0005[כדי שיודה לו בכל],\u0006","\u0003אבל העדאת עדים, דליכא למימר הכי\u0004 \u0005[שאין לומר כך]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 מתכוון אותו האיש להודות כלל, והוא רמאי גמור, ולכן אין גם ערך לשבועתו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003קל וחומר\u0004 שיש בדבר.","ומבארים: \u0003ומאי\u0004 \u0005[ומהו]\u0006 \u0003קל וחומר\u0004 זה? — כך יש לפרשו: \u0003ומה פיו\u0004 (הודאתו) \u0003שאין מחייבו ממון,\u0004 מכל מקום \u0003מחייבו שבועה, עדים שמחייבין אותו ממון\u0004 בכל מקום — \u0003אינו דין שמחייבין אותו שבועה?\u0004","ותוהים: \u0003ו\u0004כי \u0003פיו אין מחייבו ממון?!\u0004 כיצד אפשר לומר דבר זה, \u0003והא\u0004 \u0005[והרי]\u0006 כלל הוא בידינו: ש\u0003הודאת בעל דין\u0004 בממון \u0003כמאה עדים דמי\u0004 \u0005[\u0006היא \u0005נחשבת]\u0006 ושוב אין מבררים כלל, אלא סומכים על דבריו, ואם כן הודאת פיו ודאי מחייבתו ממון!","ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ממון\"\u0004 — הכוונה היא ל\u0003קנס,\u0004 שבכל המקרים שהטילה התורה קנס על אדם (כגון האונס) אם הוא עצמו מודה — אינו חייב בקנס. ומכאן קל וחומר: \u0003ומה פיו שאין מחייבו קנס\u0004 בכל זאת \u0003מחייבו שבועה, עדים שמחייבין אותו קנס\u0004 — \u0003אינו דין שמחייבין אותו שבועה!\u0004","ומנסים לדחות: \u0003מה לפיו\u0004 — \u0003שכן מחייבו קרבן,\u0004 שאם אומר אדם שהוא עבר עבירה בשוגג — חייב הוא להביא קרבן כפרה, \u0003תאמר בעדים ש\u0004אף אם העידו בו שעשה את המעשה \u0003אין מחייבין אותו קרבן,\u0004 הרי שיש צדדים שהודאת פיו חמורה יותר מעדותם של עדים!","ודוחים: \u0003הא לא קשיא\u0004 \u0005[זה לא קשה],\u0006 \u0003ר' חייא כ\u0004שיטת \u0003ר' מאיר סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ש\u0003אמר: עדים מחייבין אותו קרבן מקל וחומר.\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אמרו לו שנים,\u0004 שני עדים: \u0003\"אכלת חלב\"\u0004 וחייב אתה להביא קרבן, \u0003והוא אומר \"לא אכלתי\", ר' מאיר מחייב\u0004 בקרבן, \u0003וחכמים פוטרים.\u0004","\u0003אמר ר' מאיר: אם הביאוהו שנים לידי מיתה חמורה,\u0004 האם \u0003לא יביאוהו לידי קרבן הקל?\u0004 ולכן יש להאמין לעדים ולחייבו בהבאת קרבן. \u0003אמרו לו\u0004 חכמים: \u0003מה אם ירצה\u0004 האיש \u0003לומר \"מזיד הייתי\"\u0004 — הלא \u0003יפטר,\u0004 שהרי ברוב המקרים אין אדם מביא קרבן על עבירה במזיד, וכיון שכך אין תוקף לעדות עדים בענין זה, וגם אם אמר \"לא חטאתי\" אינו חייב בקרבן.","\u0003אלא\u0004 נחזור בנו מקושיה זו, ונקשה באופן אחר: \u0003מה לפיו\u0004 — \u0003שכן מחייבו אשם,\u0004 שאדם המודה שגזל עליו להביא לכפרתו קרבן אשם גזילות, אבל אם יבואו עדים ויעידוהו על כך, אינו חייב באשם! ודוחים: \u0003אשם היינו קרבן,\u0004 והוא הוא הנושא שנחלקו בו ר' מאיר וחכמים.","\u0003אלא\u0004 יש להקשות בדרך אחרת: \u0003מה לפיו שכן מחייבו חומש,\u0004 שאם אכל זר תרומה (או קודש) והודה בכך, חייב הוא להחזיר מה שאכל, ולהוסיף חומש, אבל אם עשה זאת על פי עדים — אינו חייב להוסיף חומש! ודוחים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 \u0003ר' חייא כ\u0004שיטת \u0003ר' מאיר סבירא ליה\u0004 \u0005[סבור הוא],\u0006 \u0003כי היכי\u0004 \u0005[כפי]\u0006 ש\u0003מחייב ליה\u0004 \u0005[אותו]\u0006 \u0003קרבן מקל וחומר\u0004 — \u0003מחייב ליה\u0004 \u0005[אותו]\u0006 גם \u0003חומש מקל וחומר.\u0004","\u0003אלא\u0004 כך יש להקשות: \u0003מה לפיו\u0004 — \u0003שכן אינו בהכחשה ובהזמה,\u0004 שאין עדים יכולים לבטל את הודאתו של בעל הדין בממונו, \u0003תאמר בעדים ש\u0004הרי \u0003ישנן בהכחשה ובהזמה\u0004 ויכולה עדותם להתבטל על ידי עדים אחרים. ולכן יש מקום לומר להיפך, שעדות פיו חזקה יותר מאשר עדות העדים.","אלא כך יש להבין את הקל וחומר של ר' חייא: \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 הלכה זו \u0003מעד אחד: ומה עד אחד שאין מחייבו ממון,\u0004 שהרי אם עד אחד מעיד עליו שחייב — אינו חייב לשלם, ובכל זאת \u0003מחייבו שבועה,\u0004 שהנתבע צריך להשבע שאין עדות העד נכונה, אם כן עדות שני \u0003עדים\u0004 ש\u0003מחייבין אותו ממון\u0004 — \u0003אינו דין שמחייבין אותו שבועה!\u0004","ודוחים קל וחומר זה: \u0003מה לעד אחד שכן על מה שהוא מעיד הוא נשבע,\u0004 שהרי כשעד אחד מעיד כנגדו חייב הוא להשבע רק על אותם הדברים שהעד העיד עליהם, ולא על טענות אחרות שיש בפי התובע,"],["\u0003תאמר בעדים, שעל מה שכפר הוא נשבע.\u0004","\u0003אלא אמר רב פפא:\u0004 קל וחומר של ר' חייא \u0003אתי\u0004 \u0005[בא, נלמד]\u0006 \u0003מגלגול שבועה\u0004 שעל פי \u0003עד אחד.\u0004 כי אם נתחייב אדם על ידי עד אחד להשבע, יכול התובע לומר לו: אגב שבועה זו, השבע גם על טענות אחרות שיש לי עליך.","ודוחים: \u0003מה לגלגול שבועה\u0004 של \u0003עד אחד, שכן שבועה גוררת שבועה\u0004 בכלל, ואין הדבר נובע מעדותו של העד אלא מהלכות השבועה עצמן, \u0003תאמר בעדים\u0004 ש\u0003ממון קא מחייבי\u0004 \u0005[הם מחייבים]\u0006 בסכום מסויים, ואין ממון גורר ממון!","וכנגד זה יש לטעון: \u0003פיו יוכיח,\u0004 שהודאת פיו במקצת מחייבתו להשבע גם על השאר. ואם תטען כנגד זה: \u0003מה לפיו שכן אינו בהכחשה,\u0004 נחזור ונאמר: \u0003עד אחד יוכיח\u0004 — \u0003שישנו בהכחשה\u0004 על ידי עדים אחרים \u0003ומחייבו שבועה,\u0004 ואולם אז אפשר לחזור ולטעון:","\u0003מה לעד אחד\u0004 — \u0003שכן על מה שמעיד הוא נשבע, תאמר ב\u0004שני \u0003עדים שעל מה שכפר הוא נשבע!\u0004 וכנגד זה: \u0003פיו יוכיח\u0004 שהוא נשבע על מה שכפר.","\u0003ו\u0004אם כן \u0003חזר הדין,\u0004 כלומר, קל וחומר זה חוזר = סובב במעגל של סברות הפוכות. ואולם יכולים אנו להגיע לידי מסקנה אם נסכם: \u0003לא ראי זה כראי זה, ולא ראי זה כראי זה\u0004 כלומר, אינו דומה דבר זה לדבר זה, ומכל מקום \u0003הצד השוה שבהן\u0004 בכל הדוגמאות שהבאנו \u0003שעל ידי טענה וכפירה הם באין, ונשבע\u0004 על כך, \u0003אף אני אביא\u0004 עדות של \u0003עדים, שעל ידי טענה וכפירה הם באין\u0004 — \u0003ונשבע.\u0004 והוא שאמר ר' חייא.","ודוחים: \u0003מה להצד השוה שבהן\u0004 כולן, בפיו ובגלגול שבועה ובעד אחד, \u0003שכן לא הוחזק כפרן,\u0004 שבכל אלה אין הנתבע מוחזק ככפרן ושקרן, ואנו עדיין מוכנים להאמין לו, שמא הוא דובר אמת, \u0003תאמר בעדים שכן הוחזק כפרן\u0004 על ידי העדות שכנגד טענתו, ושוב אינו נאמן בשבועה להכחישם.","ושואלים לגוף הדבר: \u0003ובעדים מי הוחזק\u0004 \u0005[האם מוחזק]\u0006 כ\u0003כפרן\u0004 מי שעדים מעידים כנגדו! \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב אידי בר אבין אמר רב חסדא: הכופר במלוה,\u0004 שעדים מעידים שלוה והוא כופר בכך — כשר לעדות אחרת ואין אומרים עליו שהוכח שהוא שקרן וגזלן, ואינו נפסל מלהעיד בענין אחר. שאנו אומרים: שמא נתכוון הלווה להחזיר את הכסף אחר כך, ולא רצה אלא להשתמט מלפרוע את חובו כעת. ואולם כפר \u0003בפיקדון,\u0004 שטען שלא הופקד בידו כלל, ועדים מעידים ששיקר — \u0003פסול לעדות,\u0004 שהרי כאן אין לו סיבה להשתמט, ואם השתמש בפקדון — גזלן הוא. ואם כך שוב קיים הקל וחומר של ר' חייא, שיפה כוחם של עדים מכוח הודאת עצמו.","\u0003אלא פריך הכי\u0004 \u0005[פרוך,\u0006 הקשה, \u0005כך]:\u0006 \u0003מה להצד השוה שבהן\u0004 — \u0003שכן אינן בתורת הזמה,\u0004 שהרי אין דבר היכול להזים לא את פיו ולא עד אחד, שאף אם העידו עדים בעד אחד ששיקר, אינו נעשה עד זומם לשלם מה שהעיד שקר, \u0003תאמר בעדים שישנן בתורת הזמה!\u0004","ודוחים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה]\u0006 שכן \u0003ר' חייא\u0004 מ\u0003תורת הזמה לא פריך\u0004 \u0005[אינו מקשה],\u0006 כלומר, אינו מקבל סוג כזה של הבדל, שהוא כולל כל כך ואינו חד משמעי.","ושואלים עוד: \u0003אלא\u0004 מה \u0003דקאמר ותנא תונא\u0004 \u0005[שאמר והתנא\u0006 שלנו \u0005שנה\u0006 במשנתנו\u0005]\u0006 כמו דברי ר' חייא \u0003מי דמי\u0004 \u0005[האם דומה\u0006 הדבר\u0005]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 במקרה שאנו מדברים בו בעדים על הלואה, \u0003למלוה אית ליה סהדי\u0004 \u0005[יש לו עדים],\u0006 ואילו \u0003ללוה לית ליה סהדי דלא מסיק ליה ולא מידי\u0004 \u0005[אין לו עדים שאינו חייב לו דבר],\u0006 \u0003דאי הוו ליה סהדי\u0004 \u0005[שאם היו לו עדים]\u0006 \u0003ללוה דלא מסיק ליה ולא מידי\u0004 \u0005[שאינו חייב לו דבר]\u0006 — \u0003לא בעי\u0004 \u0005[היה מצריכו]\u0006 \u0003ר' חייא לאשתבועי\u0004 \u0005[להשבע],\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003כי היכי דאנן סהדי בהאי\u0004 \u0005[כשם שאנו עדים בזה]\u0006 — כך \u0003אנן סהדי בהאי\u0004 \u0005[אנו עדים בזה],\u0006 ואם כן אין להשוות את הדברים, \u0003ואפילו הכי משתבעי\u0004 \u0005[כך נשבע]!\u0006","\u0003אלא,\u0004 עלינו לשנות את הגרסה, ולומר \u0003כי איתמר\u0004 \u0005[כאשר נאמר]\u0006 אותו ביטוי \u0003\"ותנא תונא\"\u0004 \u0005[\"והתנא\u0006 שלנו \u0005שנה\"]\u0006 — \u0003אאידך\u0004 \u0005[על\u0006 הלכה \u0005אחרת]\u0006 של \u0003ר' חייא איתמר\u0004 \u0005[נאמר],\u0006 ש\u0003אמר ר' חייא:\u0004 אדם הטוען לחבירו \u0003\"מנה לי בידך\" והלה אומר: אין לך בידי אלא חמישים זוז, והילך\u0004 (הא לך) עכשיו חמישים זוז אלה — \u0003חייב\u0004 להשבע על השאר, אף שעתה, אחר שנתן לו את החמישים שהודה לו בהם, שוב אינו תובע ממנו אלא את חמישים הזוז הנותרים ועליהם הוא כופר בכל.","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003הילך נמי\u0004 \u0005[גם כן]\u0006 \u0003כמודה\u0004 ב\u0003מקצת הטענה דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 ואין לומר שכיון שנותן לו את הדבר שהודה בו, שוב אינו נחשב כמודה במקצת הטענה.","\u0003ותנא תונא\u0004 \u0005[ושנה התנא\u0006 שלנו\u0005]\u0006 כעין זה: \u0003שנים אוחזין בטלית.\u0004","וכיצד הוא הדמיון — \u0003והא הכא\u0004 \u0005[והרי כאן],\u0006 \u0003כיון דתפיס\u0004 \u0005[שתפס]\u0006 — הלא \u0003אנן סהדי דמאי דתפיס\u0004 \u0005[אנו עדים שמה שתפס]\u0006 האחר \u0003הילך הוא, וקתני\u0004 \u0005[ושנינו]:\u0006 \u0003ישבע,\u0004 משמע שגם אם אמר \"הילך\" הרי הוא חייב עדיין בשבועה.","\u0003רב ששת אמר\u0004 להלכה: האומר \u0003הילך\u0004 מקצת הטענה שאני מודה בו \u0003פטור\u0004 מלהשבע על השאר. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003כיון\u0004 ש\u0003אמר ליה הילך\u0004 אם כן \u0003הני זוזי דקא\u0004 \u0005[אותם זוזים שהוא]\u0006 \u0003מודי בגוייהו\u0004 \u0005[בהם]\u0006 — \u0003כמאן דנקיט להו\u0004 \u0005[כמי שמחזיק אותם]\u0006 ה\u0003מלוה דמי\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 ואם כן \u0003באינך חמשים\u0004 \u0005[בחמישים האחרים]\u0006 — \u0003הא\u0004 \u0005[הרי]\u0006 הוא \u0003לא מודי\u0004 \u0005[מודה]\u0006 כלל, \u0003הלכך ליכא\u0004 \u0005[\u0006ו\u0005על כן אין]\u0006 עוד \u0003הודאה\u0004 ב\u0003מקצת הטענה.\u0004","ואומרים: \u0003ול\u0004שיטת \u0003רב ששת קשיא מתניתין\u0004 \u0005[קשה משנתנו]!\u0006 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003רב ששת:\u0004 השבועה של \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003תקנת חכמים\u0004 מיוחדת \u0003היא.\u0004 ובדרך כלל הילך פטור.","\u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' חייא\u0005]\u0006 כיצד משיב הוא לטענה זו? — \u0003אין\u0004 \u0005[כן]\u0006 גם הוא אומר ש\u0003תקנת חכמים היא. ומיהו\u0004 \u0005[ואולם],\u0006 מכל מקום \u0003אי אמרת בשלמא מדאורייתא\u0004 \u0005[נניח אם אומר אתה\u0006 ש\u0005מדין תורה]\u0006 \u0003הילך חייב\u0004 על כן \u0003מתקני רבנן\u0004 \u0005[תיקנו חכמים]\u0006 \u0003שבועה כעין דאורייתא\u0004 \u0005[דין התורה],\u0006 \u0003אלא אי אמרת מדאורייתא\u0004 \u0005[אם אומר אתה\u0006 ש\u0005מדין תורה]\u0006 \u0003הילך פטור\u0004 — האם \u0003מתקני רבנן\u0004 \u0005[מתקנים חכמים]\u0006 \u0003שבועה דליתא דכוותה בדאורייתא\u0004 \u0005[שאין כדומה לה בתורה]?\u0006 אלא ודאי יש בסיס בדין תורה לכלל זה, ולכן תקנו חכמים אף כאן שבועה.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]:\u0006"],["שטר שהיה כתוב בו שפלוני לוה \u0003סלעים,\u0004 אבל לא נתפרש בו כמה סלעים, או שהיה כתוב בו \u0003דינרין\u0004 בלא לפרש כמה דינרים, והמלוה והלווה אינם מסכימים בדבר, ה\u0003מלוה אומר: חמש\u0004 סלעים הלויתי, \u0003ולוה אומר: שלש. ר' שמעון בן אלעזר אומר: הואיל והודה מקצת הטענה\u0004 — \u0003ישבע\u0004 ככל מודה במקצת. ואילו \u0003ר' עקיבא אומר: אינו אלא כמשיב אבידה, ופטור\u0004 מלהשבע ולשלם. שהרי מלשון השטר אפשר להוכיח שהוא חייב לו שני דינרים בלבד (שמיעוט רבים — שנים) ויתר מכאן היה צריך לפרש. ואם הודה בשלושה הרי הוא כמשיב אבידה למלוה, שהרי נותן לו יותר מכפי שהיה המלוה יכול לקבל בשטר ומשום כך פטור.","ונדייק: \u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 ש\u0003ר' שמעון בן אלעזר אומר: הואיל והודה\u0004 ב\u0003מקצת הטענה\u0004 — \u0003ישבע.\u0004 ונדקדק בדברים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אמר שלש, הא\u0004 \u0005[הרי]\u0006 אילו היה מודה רק ב\u0003שתים\u0004 — \u0003פטור\u0004 היה מלהשבע, והרי \u0003האי שטר דקמודי ביה\u0004 \u0005[שטר זה שהוא מודה בו]\u0006 \u0003הילך הוא,\u0004 שהרי הוא מסכים לשלם ככל הכתוב בו, \u0003ו\u0004אם כן לכאורה \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003הילך פטור\u0004 משבועה!","ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי אף אם הודה ב\u0003שתים חייב\u0004 בשבועה, \u0003והאי דקתני\u0004 \u0005[וזה ששנה]\u0006 \u0003שלש,\u0004 לא לשם הוראה בדין הילך נאמר, אלא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' עקיבא,\u0004 ש\u0003אמר: משיב אבידה הוי\u0004 \u0005[הוא]\u0006 \u0003ופטור,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ר' שמעון בן אלעזר שאינו כן, אלא \u0003מודה\u0004 ב\u0003מקצת הטענה הוי\u0004 \u0005[הוא],\u0006 \u0003וחייב.\u0004","על כך מקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 היא הכוונה, לשון זו: \u0003\"ר' שמעון בן אלעזר אומר הואיל והודה מקצת הטענה ישבע\"\u0004 אינה מדוייקת, אלא \u0003\"אף זה ישבע\" מבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר, שהרי לפי ההסבר שאמרנו בשתיים ודאי חייב, והיה צריך לומר שאף בשלוש צריך להשבע!","\u0003אלא\u0004 יש לדחות מה שאמרנו ולהסביר בדרך אחרת: \u0003לעולם\u0004 אם הודה ב\u0003שתים\u0004 — הריהו \u0003פטור, והילך\u0004 בכלל \u0003חייב, ושאני הכא\u0004 \u0005[ושונה\u0006 הדבר \u0005כאן]\u0006 שאינו חייב שבועה, הואיל \u0003דקא מסייע ליה שטרא\u0004 \u0005[שמסייע לו,\u0006 ללווה, \u0005השטר]\u0006 ומשום כך פטור משבועה אם הודה בשניים.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 פטור משבועה אם הודה בשניים בלבד מטעם אחר: \u0003משום דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003שטר שעבוד קרקעות,\u0004 כי סתם שטר יש בו ערבות הלווה על ידי שיעבוד קרקעותיו למלוה, וכלל בידינו ש\u0003אין נשבעין על כפירת שעבוד קרקעות,\u0004 אלא על כפירת כספים או מטלטלים. כל זה היה בלשון אחת של דיוק מן הברייתא.","אכן, \u0003איכא דמותיב מסיפא\u0004 \u0005[יש שמקשה מסופה\u0006 של ברייתא זו\u0005],\u0006 ששנינו בה, \u0003ר' עקיבא אומר: אינו אלא כמשיב אבידה ופטור\u0004 משבועה. ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אמר\u0004 הלוה \u0003שלש, הא\u0004 \u0005[הרי]\u0006 אם הודה רק ב\u0003שתים\u0004 — \u0003חייב. והא\u0004 \u0005[והרי]\u0006 \u0003שטר\u0004 זה \u0003כיון דקא מודי ביה\u0004 \u0005[שהוא מודה בו]\u0006 אם כן \u0003כהילך דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 שהרי עליו לשלם ככתוב בשטר, ו\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003הילך חייב!\u0004","ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי כאשר הודה ב\u0003שתים נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור\u0004 משבועה, \u0003והאי דקתני\u0004 \u0005[וזה ששנה]\u0006 \u0003שלש\u0004 דווקא, הרי זה \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' שמעון בן אלעזר\u0004 ש\u0003אמר\u0004 ש\u0003מקצת הטענה\u0004 \u0003הוי\u0004 \u0005[הוא]\u0006 \u0003וחייב,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ר' עקיבא שלדעתו \u0003משיב אבידה הוי\u0004 \u0005[הוא]\u0006 \u0003ופטור.\u0004","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר מתוך הדברים. \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לפרש כי מי שהודה ב\u0003שתים חייב\u0004 בשבועה, אם כן \u0003בשלש היכי\u0004 \u0005[איך]\u0006 \u0003פטר ליה\u0004 \u0005[אותו]\u0006 \u0003ר' עקיבא,\u0004 שכן יש מקום לומר כי \u0003האי אערומי קא מערים\u0004 \u0005[זה,\u0006 הלווה, \u0005מערים הוא]\u0006 \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003אי אמינא\u0004 \u0005[אם אומר]\u0006 \u0003שתים\u0004 \u0003בעינא אשתבועי\u0004 \u0005[אצטרך להשבע\u0006 על כך\u0005]\u0006 וכיון שכך \u0003אימא\u0004 \u0005[אומר]\u0006 \u0003שלש\u0004 \u0003דאהוי\u0004 \u0005[שאהיה]\u0006 \u0003כמשיב אבידה ואיפטר\u0004 \u0005[ואפטר].\u0006 \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי אם הודה ב\u0003שתים נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור.\u0004","ושואלים: \u0003אלא\u0004 לפירוש זה הרי \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003ל\u0004דברי \u0003ר' חייא,\u0004 שהרי המודה בשניים הילך הוא, ובכל זאת חייב! ומשיבים: \u0003שאני התם דקא מסייע ליה שטרא\u0004 \u0005[שונה שם שמסייע לו השטר]\u0006 ולא משום הילך, אלא משום שחייב לשלם על פי השטר. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003משום דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003שטר שעבוד קרקעות, ו\u0004כאמור \u0003אין נשבעים על כפירת שעבוד קרקעות.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן,\u0004 ממה ששנינו: אדם ש\u0003טענו\u0004 לחבירו שמגיע לו ממנו \u0003כלים וקרקעות, הודה\u0004 הנתבע שחייב לו \u0003כלים וכפר בקרקעות,\u0004 או להיפך ש\u0003הודה בקרקעות וכפר בכלים\u0004 — הרי זה \u0003פטור\u0004 מלהשבע על השאר. אם \u0003הודה\u0004 על \u0003מקצת קרקעות\u0004 — \u0003פטור\u0004 מלהשבע, הודה על \u0003מקצת כלים\u0004 — \u0003חייב\u0004 להשבע על השאר.","ומעתה נדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 מפני שמדובר כאן ב\u0003כלים וקרקעות,\u0004 שה\u0003קרקע לאו\u0004 \u0005[לא]\u0006 \u0003בת שבועה היא,\u0004 שהרי אין נשבעים על טענות הקשורות בקרקעות, \u0003הא\u0004 \u0005[הרי]\u0006 אילו היה כאן ענין של \u0003כלים וכלים דומיא\u0004 \u0005[בדומה]\u0006 לטענה זו של \u0003כלים וקרקעות,\u0004 היינו אומרים, ש\u0003חייב\u0004 להשבע. ו\u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003לאו דאמר ליה\u0004 \u0005[האם לא\u0006 שהמקרה הדומה הוא \u0005שאומר לו]\u0006 \u0003הילך, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003הילך חייב\u0004 בשבועה!","ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 שאף אם היה מדובר ב\u0003כלים וכלים נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור, והא דקתני\u0004 \u0005[וזו ששנה]\u0006 \u0003כלים וקרקעות, הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 שחידש לנו בכך דבר אחר: כי אם \u0003הודה במקצת\u0004 ה\u0003כלים\u0004 ונתחייב בשבועה — \u0003חייב\u0004 להשבע \u0003אף על הקרקעות\u0004 שכפר בהם, אף שעל קרקעות עצמם אינו נשבע.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 על ידי כך — ש\u0003זוקקין?\u0004 כלומר, שאף שאין נשבעים ישירות על תביעות קרקעות, מכל מקום מי שהתחייב שבועה לחבירו, יכול התובע להזקיק (להכריח) אותו שישבע על דברים שאין עליהם כרגיל חיוב שבועה. ואולם דבר זה אין צריך ללמדנו מברייתא זו, שכן הלא \u0003תנינא\u0004 \u0005[שנינו\u0006 כבר\u0005]\u0006 במסכת קדושין כי \u0003זוקקין הנכסים שאין להן אחריות,\u0004 כלומר, כספים ומטלטלים (שלא היו משתמשים כאחריות להלואה), \u0003את הנכסים שיש להן אחריות\u0004 (קרקעות) \u0003לישבע עליהם.\u0004 ואם כן, הלכה זו כבר ידועה לנו, ולשם מה ללמוד אותה מן הברייתא כאן?","ומשיבים: \u0003הכא\u0004 \u0005[כאן],\u0006 בהלכה של כלים וקרקעות הוא \u0003עיקר\u0004 ההלכה, שזוקקים הנכסים שאין להם אחריות להשבע גם על האחרים. ואילו \u0003התם\u0004 \u0005[שם]\u0006 \u0003אגב גררא נסבה\u0004 \u0005[גרר\u0006 הדברים \u0005הביאה],\u0006 שתוך שעסק בכלל בהשוואה של נכסים שונים זה לזה הביא גם דבר זה. ועיקר הלימוד הוא איפוא מן הקטע שלנו, ואם כן יש בו חידוש לעצמו, ואין ללמוד ממנו כלל לענין הילך."],["ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 ש\u0003הילך\u0004 בכלל \u0003פטור\u0004 משבועה, \u0003אמאי איצטריך קרא\u0004 \u0005[מדוע הוצרך כתוב]\u0006 מיוחד \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003קרקע מ\u0004חיוב \u0003שבועה\u0004 אם הודה במקצת? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כל קרקע הילך הוא,\u0004 שהרי הקרקע עומדת במקומה כפי שהיתה, ואין הילך גדול מזה, ואם כן לשם מה פסוק מיוחד?","\u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 \u0003איצטריך קרא\u0004 \u0005[הוצרך הכתוב]\u0006 למקרה מסויים, \u0003היכא\u0004 \u0005[היכן]\u0006 ש\u0003חפר בה,\u0004 בקרקע שהוא מחזיר \u0003בורות, שיחין\u0004 (בריכות), \u0003ומערות,\u0004 ושוב אין זה הילך, שהרי כבר נתקלקל השדה על ידי כך.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש צורך בכתוב \u0003היכא\u0004 ש\u0003טענו\u0004 את חבירו שחייב לו \u0003כלים וקרקעות, והודה בכלים וכפר בקרקעות,\u0004 ללמדנו שאינו חייב שבועה על הקרקעות.","ומנסים להביא ראיה אחרת, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רמי בר חמא\u0004 ברייתא זו: \u0003ארבעה שומרין,\u0004 כלומר, ארבעה סוגי שומרים שמנתה התורה ושיש בכל אחד מהם חובה להשבע במקרים מסויימים אם לא החזירו את מה שנמסר לידם, \u0003צריכין\u0004 כדי לחייבם להשבע שתהא \u0003כפירה במקצת והודאה במקצת.\u0004 ואלו הם ארבעת השומרים: \u0003שומר חנם\u0004 שאינו מקבל כל שכר עבור שמירתו, \u0003והשואל\u0004 מחבירו חפץ כדי להשתמש בו ואינו משלם עבור זכות השימוש בו, \u0003נושא שכר\u0004 המקבל תשלום עבור השמירה, \u0003והשוכר\u0004 חפץ מחבירו ומשלם לו עבור זכות השימוש בו.","ומעתה נברר, \u0003היכי דמי\u0004 \u0005[כיצד מדובר],\u0006 כיצד יכולה להיות בשומרים כפירה והודאה במקצת? \u0003לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן כגון ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 השומר: \u0003הילך,\u0004 הרי לך מה שבאמת קבלתי ממך, והשאר מעולם לא התחייבתי בהם! וראיה היא לר' חייא שהילך חייב!","ודוחים: \u0003לא,\u0004 יכול שתהא הודאה במקצת באופן אחר, כגון ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 בעל הפרות לשומר החינם: \u0003שלש פרות מסרתי לך ומתו כולהו\u0004 \u0005[כולן]\u0006 \u0003בפשיעה\u0004 (רשלנות) ואתה חייב לשלם עבורן. \u0003ואמר ליה איהו\u0004 \u0005[לו הוא,\u0006 השומר\u0005]:\u0006 לגבי פרה \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003לא היו דברים מעולם,\u0004 כלומר, לא שלוש אלא שתיים לקחתי. \u0003וחדא\u0004 \u0005[ואחת\u0006 מהפרות\u0005]\u0006 \u0003מתה באונס\u0004 ואני פטור עליה, \u0003וחדא\u0004 \u0005[ואחת\u0006 מהן\u0005]\u0006 אכן \u0003מתה בפשיעה דבעינא שלומי\u0004 \u0005[שאני\u0006 אכן \u0005צריך לשלם]\u0006 \u0003לך\u0004 עבורה. ובמקרה זה אף שהוא מודה במקצת הטענה, \u0003לאו\u0004 \u0005[לא]\u0006 \u0003הילך הוא,\u0004 שהרי בפועל אינו מחזיר דבר ואם כן אין להוכיח מכאן לענייננו.","ושוב מציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה \u0003דתני אבוה\u0004 \u0005[ששנה אביו]\u0006 של \u0003ר' אפטוריקי\u0004 ברייתא בדומה לזו \u0003לדר' חייא קמייתא\u0004 \u0005[ל\u0006הלכתו \u0005הראשונה של ר' חייא]:\u0006 אמר לחבירו \u0003\"מנה לי בידך\", והלה,\u0004 הנתבע \u0003אומר: אין לך בידי כלום, והעדים מעידים אותו שיש בידו\u0004 מאותם מעות \u0003חמשים זוז, יכול ישבע על השאר\u0004 —","\u0003תלמוד לומר\u0004 בענין שומרים: \"על כל דבר פשע, על שור על חמור על שה על שלמה \u0003על כל אבידה אשר יאמר כי הוא זה\u0004 עד האלהים יבא דבר שניהם\" (שמות כב, ח), ומכאן למדים: \u0003על הודאת פיו\u0004 (\"אשר יאמר כי הוא זה\") \u0003אתה מחייבו\u0004 שבועה (\"עד האלהים\"), \u0003ואי\u0004 \u0005[ואין]\u0006 \u0003אתה מחייבו\u0004 שבועה \u0003על העדאת עדים,\u0004 והרי זה היפך דברי ר' חייא!","את הקושיה הזו דוחים: \u0003מתניתא קא רמית עליה\u0004 \u0005[מברייתא אתה משליך,\u0006 מראה סתירה, \u0005עליו],\u0006 על דברי \u0003ר' חייא?!\u0004 והלא \u0003ר' חייא\u0004 עצמו \u0003תנא\u0004 של ברייתא \u0003הוא ופליג\u0004 \u0005[וחולק]\u0006 על הברייתא שהביא אביו של ר' אפטוריקי.","ומקשים: \u0003והא קרא קאמר\u0004 \u0005[והרי מקרא אמר]!\u0006 שהרי אינו אומר רק סברה סתם, אלא לפנינו מקרא כתוב, ומן המקרא יש להקשות על ר' חייא! ומשיבים: הפסוק \u0003ההוא\u0004 שהבאנו שנאמר בו ''כי הוא זה\" לענין אחר הוא בא, ללמדנו, \u0003למודה מקצת הטענה,\u0004 שרק הוא חייב להשבע.","ומעירים: \u0003ואבוה\u0004 \u0005[ואביו]\u0006 של \u0003ר' אפטוריקי\u0004 \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 כהסבר לדבר: לשון הכתוב \"כי הוא זה\" מורה על מיעוט כפול, \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"הוא\"\u0004 \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"זה\", חד\u0004 \u0005[אחד\u0006 מהם, מלה אחת\u0005]\u0006 בא \u0003ל\u0004למד ש\u0003מודה מקצת הטענה\u0004 הוא שחייב להשבע, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003להעדאת עדים\u0004 ש\u0003פטור\u0004 משבועה.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' חייא\u0005],\u0006 כיצד מסביר הוא את הכפילות בפסוק? ואומרים: לדעתו \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 בא למעט ולומר כי רק \u0003מודה מקצת הטענה\u0004 חייב להשבע, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 לומר שאין נשבעים אלא כש\u0003מודה ממין הטענה,\u0004 שאם היתה התביעה בסוג אחד של דברים, והודה לו בסוג אחר, שאינו חייב להשבע.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 אבי ר' אפטוריקי\u0005]\u0006 מדוע אינו מפרש גם הוא כך? ומשיבים: זה שאיננו \u0003מודה ממין הטענה לית ליה\u0004 \u0005[אין לו],\u0006 איננו סבור שהוא פטור משבועה. \u0003וסבר ליה\u0004 \u0005[והוא סבור]\u0006 \u0003כ\u0004דעת \u0003רבן גמליאל\u0004 בענין זה, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003טענו\u0004 את חבירו שהוא חייב לו \u0003חטין, והודה לו\u0004 החבר \u0003בשעורים,\u0004 אף על פי שהשעורים זולות מן החיטים, והריהו לכאורה כמודה במקצת, מכל מקום \u0003פטור\u0004 שלא הודה לו כלל באותו דבר שטען נגדו. \u0003ו\u0004אילו \u0003רבן גמליאל מחייב,\u0004 ואבי ר' אפטוריקי הולך בשיטתו של רבן גמליאל. ובסיכומם של דברים נשארו איפוא דברי ר' חייא במקומם, בלא הוכחה מכרעת כנגדם.","ומביאים מעשה שהיה בבית הדין: \u0003ההוא רעיא דהוו מסרי ליה כל יומא חיותא בסהדי\u0004 \u0005[רועה אחד שהיו מוסרים לו\u0006 ב\u0005כל יום בהמות בעדים].\u0006 \u0003יומא חד\u0004 \u0005[יום אחד]\u0006 \u0003מסרו ליה\u0004 \u0005[לו]\u0006 בהמות לשמור \u0003בלא\u0004 שיהיו \u0003סהדי\u0004 \u0005[עדים]\u0006 להעיד כמה בהמות מסרו. \u0003לסוף\u0004 \u0005[לבסוף]\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 לבעלי הבהמות: \u0003לא היו דברים מעולם,\u0004 שמעולם לא לקח בהמות אלה, ולא רצה להחזירן. \u0003אתו סהדי אסהידו ביה\u0004 \u0005[באו\u0006 \u0005עדים\u0006 ו\u0005העידו בו]\u0006 ש\u0003אכל תרתי מינייהו\u0004 \u0005[שתיים מהן],\u0006 מאותן הבהמות שהכחיש את לקיחתן. \u0003אמר ר' זירא: אם איתא\u0004 \u0005[יש\u0006 מקום לומר\u0005],\u0006 אם מקבלים אנו את דברי \u0003ר' חייא קמייתא\u0004 \u0005[הראשונים],\u0006 הרי במקרה זה \u0003משתבע אשארא\u0004 \u0005[נשבע\u0006 הרועה \u0005על השאר]\u0006 או ישלם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אם איתא\u0004 \u0005[יש,\u0006 אם מקבלים\u0005]\u0006 את דברי ר' חייא \u0003משתבע\u0004 \u0005[נשבע]\u0006 הרועה\u0005?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003גזלן הוא!\u0004 שהרי הוכיחו העדים בעדותם שהוא גזלן, וכיון שכך, פסול הוא לעדות ואינו נאמן בשבועתו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא: לא התכוונתי שהרועה ישבע, אלא הצד \u0003שכנגדו קאמינא\u0004 \u0005[אמרתי]\u0006 שישבע, ויקבל את המגיע לו.","ומעירים: ו\u0003השתא נמי דליתא\u0004 \u0005[\u0006ו\u0005עכשיו גם כן שאין]\u0006 אנו מקבלים להלכה את דברי \u0003ר' חייא נחייביה\u0004 \u0005[נחייב אותו,\u0006 את הרועה\u0005]\u0006 שבועה \u0003מ\u0004דברי \u0003רב נחמן.\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 האומר לחבירו \u0003\"מנה לי בידך\",\u0004 וענה לו החבר: \u0003\"אין לך בידי\u0004 כלום \u0003\"\u0004— הרי זה \u0003פטור\u0004 מן השבועה. \u0003ואמר רב נחמן:\u0004 אף על פי כן \u0003משביעין אותו שבועת היסת.\u0004 שרב נחמן חידש או ניסח תקנה זו, שגם הכופר בכל חייב להשבע שאין הטענה נכונה. אם כן, יצטרך הרועה להשבע שבועה זו!","ומשיבים: הלכה זו שקבע \u0003רב נחמן\u0004 הלא \u0003תקנתא\u0004 \u0005[תקנה]\u0006 \u0003היא\u0004 ואינה שבועה מדברי תורה, אלא תקנת חכמים."],["\u0003ותקנתא לתקנתא לא עבדינן\u0004 \u0005[ותקנה לתקנה אין אנו עושים].\u0006 שהלכה זו שאם הנתבע חשוד על השבועה, נשבע התובע ונוטל — אף היא תקנת חכמים, ואין מצרפים שתי תקנות חכמים זו עם זו.","ושואלים: ובעיקרו של דבר, מה שאמרנו שהרועה פסול לשבועה משום שהוא גזלן \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 הלכה זו שהוא פסול לעדות משום \u0003דהוה ליה\u0004 \u0005[שהוא]\u0006 \u0003רועה! ואמר רב יהודה: סתם רועה פסול\u0004 לעדות, שמן הסתם גזלן הוא, שהוא רועה את בהמותיו בשדות אחרים וגוזלם.","ודוחים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — כשהוא רועה את הבהמות \u0003דידיה\u0004 \u0005[שלו],\u0006 שאז חושדים אנו בו בגזלנות, \u0003הא\u0004 \u0005[\u0006ו\u0005זה]\u0006 כשהוא רועה בהמות \u0003דעלמא\u0004 \u0005[של העולם,\u0006 אחרים\u0005].\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שרועה שכיר נאמן, אם כן \u0003אנן חיותא\u0004 \u0005[אנו\u0006 את \u0005החיות,\u0006 הבהמות\u0005]\u0006 \u0003לרועה היכי מסרינן\u0004 \u0005[איך אנו מוסרים]?\u0006 \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"\u0004ו\u0003לפני עור לא תתן מכשל\"\u0004 (ויקרא יט, יד), שאסור לסייע לאדם לעבור עבירה, ואם חושדים אנו בו בגזלנות הרי מכשילים אנו אותו בעבירה על ידי שנותנים לו את הבהמות?! \u0003אלא חזקה היא: אין אדם חוטא ולא לו\u0004 (שלא עבור עצמו), ולפיכך אין חוששים שיגזול הרועה עבור בהמות שאינן שלו.","שנינו במשנה: \u0003זה,\u0004 כל אחד מן האוחזים בטלית ואומר \"כולה שלי\" \u0003ישבע שאין לו בה פחות מחציה\u0004 וכן יעשה השני. ושואלים: \u0003על\u0004 החלק \u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003משתבע\u0004 \u0005[\u0006הוא \u0005נשבע]\u0006 שאומר שיש לו בה חציה ומשמעות דבריו שאכן אותו חלק בו הוא מחזיק הוא שלו, \u0003או על\u0004 החלק \u0003דלית ליה משתבע\u0004 \u0005[שאין לו\u0006 הוא \u0005נשבע]\u0006 שאומר שאין לו בה פחות מחציה, שהרי מלשון שלילית זו אין להוכיח שיש לו משהו, שייתכן שכוונת דבריו שפחות מחצייה אין לו ואף פחות מכך אין לו! \u0003אמר רב הונא,\u0004 כך הוא נשבע, \u0003דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]:\u0006 \u0003שבועה שיש לי בה\u0004 חלק מסויים \u0003ואין לי בה פחות מחציה.\u0004","ושואלים: \u0003ונימא\u0004 \u0005[ושיאמר]\u0006 \u0003שבועה שכולה שלי,\u0004 שהרי זוהי טענתו מתחילה ומדוע נשבע רק שיש לו בה חלק. על כך משיבים בדרך שאלה: \u0003ומי יהבינן ליה\u0004 \u0005[והאם נותנים אנו לו]\u0006 את \u0003כולה\u0004 אם ישבע? ואם כן אינו צריך להשבע שכולה שלו.","ושואלים: אם כן \u0003ונימא\u0004 \u0005[ושיאמר]\u0006 רק \u0003שבועה שחציה שלי\u0004 ומדוע צריכים לנוסח מסובך זה של רב הונא? ומשיבים: הריהו על ידי כך \u0003מרע ליה לדיבוריה\u0004 \u0005[פוגם בדבריו],\u0006 בטענתו הקודמת, שהרי טען שכולה שלו.","ומקשים: \u0003השתא נמי מרע ליה לדיבוריה\u0004 \u0005[עכשיו גם כן\u0006 בנוסחו של רב הונא הוא \u0005פוגם בדיבורו],\u0006 שהרי הוא נשבע רק על חציה! ומשיבים: \u0003דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]\u0006 בנוסח זה: \u0003כולה שלי, ולדבריכם\u0004 שאין אתם מאמינים לי בכולה — \u0003שבועה שיש לי בה\u0004 חלק \u0003ואין לי בה פחות מחציה.\u0004","לעיקר הדין שואלים: \u0003וכי מאחר שזה תפוס ועומד\u0004 בחציה \u0003וזה תפוס ועומד\u0004 בחציה, ולבסוף כל אחד מקבל מה שהוא תופס בו, \u0003שבועה זו למה?\u0004 מוטב שיתחלקו כך מתחילה בלא שבועה! \u0003אמר ר' יוחנן: שבועה זו תקנת חכמים היא,\u0004 ועשו אותה כדי \u0003שלא יהא כל אחד ואחד הולך ותוקף\u0004 (מחזיק) סתם \u0003בטליתו של חבירו ואומר: \"שלי הוא\",\u0004 ומכריחו על ידי כך להתחלק עמו, ולכן תקנו שבועה כדי למנוע חטיפה סתם.","ושואלים מצד אחר: \u0003ונימא\u0004 \u0005[ונאמר]\u0006 כי \u0003מיגו דחשיד אממונא חשיד נמי אשבועתא\u0004 \u0005[מתוך\u0006 שאנו אומרים \u0005ש\u0006הוא \u0005חשוד על\u0006 גזילת \u0005ממון, חשוד\u0006 הוא \u0005גם כן על השבועה],\u0006 שהרי מתחילה חושדים אנו בו שגזל דבר שאינו שלו והוא משקר בתביעתו, ומדוע נאמין לו בשבועתו?","ומשיבים: \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 ואיננו מקבלים הנחה זו ש\u0003מיגו דחשיד אממונא חשיד אשבועתא\u0004 \u0005[מתוך שחשוד על\u0006 גזילת \u0005ממון חשוד\u0006 הוא \u0005גם כן\u0006 \u0005על השבועה]\u0006 שאנו סבורים שאף שייתכן שיהא אדם חשוד על ממון מכל מקום חמורה השבועה בעיניו, ולא ישבע לשקר. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 \u0003האי דאמר רחמנא\u0004 \u0005[זה שאמרה התורה]\u0006 ש\u0003מודה מקצת הטענה ישבע,\u0004 הרי אף שם \u0003נימא\u0004 \u0005[נאמר]\u0006 \u0003מיגו דחשיד אממונא חשיד אשבועתא\u0004 \u0005[מתוך שחשוד על\u0006 גזילת \u0005ממון חשוד\u0006 הוא גם כן \u0005על השבועה],\u0006 והרי זו ראיה שאין חוששים לכך.","ודוחים: משם אין ראיה, כי \u0003התם אשתמוטי קא משתמיט ליה\u0004 \u0005[שם משתמט הוא ממנו]\u0006 עד שיכול לשלם, ו\u0003כ\u0004דברי \u0003רבה\u0004 שהזכרנו, שרבה מסביר שהלווה מתכוון באמת לתת הכל, והוא מודה רק במקצת מפני שהוא רוצה להשתמט בינתיים, עד שיוכל לשלם את חובו כולו.","ומוסיפים: \u0003תדע\u0004 שכן הוא, שהרי \u0003אמר רב אידי בר אבין אמר רב חסדא: הכופר במלוה,\u0004 מי שהוכיחו עדים שלוה כסף וכפר בכך שאכן לוה אותו — \u0003כשר לעדות\u0004 ואין אנו אומרים שהוא גנב ונפסל משום כך לכל עדות. ואולם מי שהוכח שהוא כופר \u0003בפיקדון\u0004 — \u0003פסול לעדות.\u0004 וטעמו של דבר — שכיון שכסף הלואה ניתן ללווה להוציאו, מניחים אנו שהוציא את הכסף, וכפירתו היתה רק השתמטות לפי שעה עד שיוכל לשלם. מה שאין כן בפקדון, שהרי אין שומר הפקדון רשאי להשתמש בו, ואם אינו בידו בוודאי גנבו, ולכן דינו כגזלן ופסול לעדות, ולענייננו הרי זו הוכחה שהעובדה שאדם כופר בממון ומשקר בדבריו, איננה ראיה שהוא חשוד גם על השבועה.","ושואלים: \u0003אלא הא דתני\u0004 \u0005[\u0006ברייתא \u0005זו ששנה]\u0006 \u0003רמי בר חמא:\u0004 כדי שיצטרכו \u0003ארבעה שומרים\u0004 להשבע על טענתם, צריכים הם שתהיה בדבריהם \u0003כפירה במקצת והודאה במקצת.\u0004 ואלו הם: \u0003שומר חנם והשואל נושא שכר והשוכר,\u0004 אף ביחס להם \u0003נימא\u0004 \u0005[נאמר]\u0006 \u0003מיגו דחשיד אממונא חשיד אשבועתא\u0004 \u0005[מתוך שחשוד על ממון חשוד\u0006 גם \u0005על שבועה],\u0006 שהרי השומר אין לו סיבה להשתמט, ואם אינו מחזיר את הפקדון יש לחשוש שגנבו, ובכל זאת מאמינים לו בשבועה!","ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 בשומרים, אפשר להעלות על הדעת שהשומר אינו שקרן וגזלן אלא \u0003אשתמוטי קא משתמיט\u0004 \u0005[משתמט הוא]\u0006 מלהחזיר עכשיו, ויחזיר לאחר מכן. כי מן הסתם נגנב או נאבד ממנו הפקדון, ו\u0003סבר\u0004 \u0005[סבור]\u0006 השומר: אם ינתן לי זמן \u0003משכחנא\u0004 \u0005[אמצא]\u0006 את ה\u0003גנב ותפיסנא ליה\u0004 \u0005[ואתפוס אותו]\u0006 ואקח מידו את החפץ ואחזירנו. \u0003אי נמי משכחנא ליה\u0004 \u0005[או גם כן אמצא אותו],\u0006 את הבהמה \u0003באגם ומייתינא ליה\u0004 \u0005[ואביא אותה],\u0006 ואם כן, מתחילה אין חושדים אותו כשקרן אלא כמשתמט בלבד.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה אומר, \u0003הכופר בפקדון אמאי\u0004 \u0005[מדוע]\u0006 \u0003פסול לעדות? נימא\u0004 \u0005[נאמר]\u0006 גם שם: \u0003אשתמוטי\u0004 כי \u0003קא משתמיט\u0004 \u0005[משתמט הוא]\u0006 בינתיים מלהחזיר \u0003סבר\u0004 \u0005[\u0006\u0005ו\u0006\u0005סבור הוא]:\u0006 אשתמט \u0003עד דבחשנא ומשכחנא ליה\u0004 \u0005[שאחפש ואמצא אותו,\u0006 את הפקדון\u0005]!\u0006 ומשיבים: אכן, סתם כופר בפקדון איננו נפסל לעדות.","\u0003כי אמרינן\u0004 \u0005[כאשר אומרים אנו]\u0006 ש\u0003הכופר בפקדון פסול לעדות\u0004 הוא במקרה כגון \u0003דאתו סהדי ואסהידו ביה\u0004 \u0005[שבאו עדים והעידו בו]\u0006 \u0003דההיא שעתא איתיה\u0004 \u0005[שבאותה שעה\u0006 שהכחיש \u0005היה]\u0006 ה\u0003פקדון בביתיה והוה ידע\u0004 \u0005[בביתו והיה יודע]\u0006 שהפקדון שם. \u0003אי נמי דהוה נקיט ליה בידיה\u0004 \u0005[או גם כן שהיה מחזיק אותו,\u0006 את הפקדון, \u0005בידו]\u0006 ואז ברור לנו שאין הוא משתמט אלא גנב גמור.","ושואלים שוב: \u0003אלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב הונא\u0004 לגבי דיני שומרים, ששומר שלא החזיר את הפקדון ואמר שהוא מוכן לשלם את מחירו ובלבד שלא ישביעוהו, מכל מקום \u0003משביעים אותו שבועה שאינה ברשותו\u0004, \u0003נימא\u0004 \u0005[נאמר]\u0006 \u0003מיגו דחשיד אממונא חשיד אשבועתא\u0004 \u0005[מתוך שחשוד על ממון חשוד\u0006 גם \u0005על השבועה],\u0006 שהרי הוא טוען שהחפץ נגנב או נאבד, ואנו חושדים בו ומחייבים אותו להשבע, משמע שאנו מאמינים לשבועתו!","ודוחים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 השומר \u0003מורה\u0004 היתר לעצמו \u0003ואמר\u0004 \u0005[ואומר]:\u0006 \u0003דמי קא יהבנא ליה\u0004 \u0005[כסף נתתי לו]\u0006 עבור החפץ, ואף שלקחתי את הפקדון לעצמי כיון שאני מחזיר את דמיו לא עשיתי כל רע, ולכן יש מקום לחייב אותו שבועה שאין החפץ ברשותו, ואם נשבע הריהו נאמן בשבועתו.","\u0003אמר\u0004 \u0003ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא: והא קא עבר\u0004 \u0005[והרי הוא,\u0006 השומר, \u0005עבר]\u0006 בכך שלא החזיר את הפקדון גם אם שילם בעדו, \u0003על לאו\u0004 (מצות לא תעשה) של \u0003\"לא תחמד\u0004 אשת רעך ועבדו ואמתו ושורו וחמורו וכל אשר לרעך\u0003\"\u0004(שמות כ, יד), שאדם מתחייב בו אם לוקח בכוח או במרמה חפץ מחבירו, אף אם משלם עבורו!","ומשיבים: \u0003\"לא תחמד\" לאינשי\u0004 \u0005[לאנשים]\u0006 \u0003בלא דמי משמע להו\u0004 \u0005[כסף נשמע להם],\u0006 שאף שאכן הנוטל דבר מחבירו גם אם משלם עובר על איסור \"לא תחמוד\", מכל מקום אנשים אינם יודעים שהדבר אסור, והם סבורים שעבירה של \"לא תחמוד\" היא רק כאשר הוא לוקח חפץ של חבירו בלא לשלם, ומשום כך השומר לא חשב שהוא מרשיע לעשות, ולכן הוא נאמן לעדות ולשבועה."],["\u0003ואלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב נחמן\u0004 שמי שתבעו אותו וכפר הכל \u0003משביעין אותו שבועת היסת, נימא\u0004 \u0005[נאמר\u0006 שם\u0005]\u0006 \u0003מיגו דחשיד אממונא חשיד אשבועתא\u0004 \u0005[מתוך שחשוד על\u0006 גזילת \u0005ממון חשוד\u0006 הוא גם \u0005על השבועה].\u0006","\u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003הא דתני\u0004 \u0005[זו ששנה]\u0006 \u0003ר' חייא\u0004 לענין חנווני ופועל, ש\u0003שניהם,\u0004 החנווני והפועלים, \u0003נשבעין ונוטלין מבעל הבית,\u0004 אף שם \u0003נימא\u0004 \u0005[נאמר]\u0006 \u0003מיגו דחשיד אממונא חשיד אשבועתא\u0004 \u0005[מתוך שחשוד על הממון חשוד\u0006 גם \u0005על השבועה].\u0006","\u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב ששת: שלש שבועות משביעים אותו,\u0004 את שומר החינם הטוען שהחפץ שניתן לו לשמירה נגנב מידו: \u0003שבועה שלא פשעתי בה,\u0004 כלומר, שלא התרשלתי בשמירה; \u0003שבועה שלא שלחתי בה יד,\u0004 שלא התחיל הוא עצמו להשתמש בה לצרכו; ו\u0003שבועה שאינה ברשותי\u0004 כעת. וכיון שאנו חושדים בו בכל אלה, \u0003נימא\u0004 \u0005[נאמר]\u0006 \u0003מיגו דחשיד אממונא חשיד אשבועתא\u0004 \u0005[מתוך שחשוד על ממון חשוד\u0006 גם \u0005על השבועה].\u0006","\u0003אלא\u0004 מכל אלה יכולים להסיק כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003מיגו דחשיד אממונא חשיד אשבועתא\u0004 \u0005[מתוך שחשוד על ממון חשוד\u0006 גם \u0005על השבועה].\u0006","\u0003אביי אמר:\u0004 מכל המקומות הללו אין להוכיח שהחשוד על ממון נאמן בשבועה, כי אפשר לומר אחרת: \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא מלוה ישנה יש לו עליו.\u0004 שמא היה התובע (או מוצא האבידה) חייב לנתבע חוב ישן, ועד עכשיו לא יכול היה לקבל ממנו את ממונו, ועתה כיוון שבאה לידו הזדמנות להחזיק בחפץ, הריהו מעכבו כתשלום עבור חובו. ואם כן אין אנו חושדים בו כלל בגזלנות, וממילא נאמן על התביעה.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 שאנו חוששים שמא מלוה ישנה יש לו עליו, מדוע אם כן נשבע? \u0003נשקול\u0004 \u0005[שיקח]\u0006 \u0003בלא שבועה,\u0004 שהרי יתכן שישבע לו באמת שהחפץ שייך לו, משום שהוא תשלום עבור החוב הישן ולא תועיל השבועה לברר את האמת בסכסוך זה שלפנינו!","אלא כך יש לומר: \u0003חיישינן שמא ספק מלוה ישנה יש לו עליו.\u0004 כלומר, אין זה ברור לנתבע שהתובע אכן חייב לו, אלא יש לו ספק בדבר, ובינתיים הוא מעכב את החפץ ברשותו עד לבירור הענין.","ומקשים: \u0003ולא אמרינן תפיס ממונא מספיקא\u0004 \u0005[והאם אין אנו אומרים\u0006 במקרה זה שאותו אדם \u0005תופס ממון\u0006 שאיננו שלו \u0005מספק]\u0006 בלבד? ואם כן ודאי \u0003משתבע נמי\u0004 \u0005[נשבע גם כן]\u0006 על הדברים \u0003מ\u0004תוך אותו \u0003ספק,\u0004 ומדוע נאמין לשבועתו אם הוא חשוד בעינינו על נטילת דברים מספק שלא כדין?","\u0003אמר רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: פרשי אינשי\u0004 \u0005[פורשים אנשים]\u0006 \u0003מ\u0004להשבע \u0003ספק שבועה ולא פרשי\u0004 \u0005[ואינם פורשים]\u0006 \u0003מספק ממונא\u0004 \u0005[ממון]\u0006 שאינו שלהם. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל? — \u0003ממון איתיה\u0004 \u0005[ישנו]\u0006 \u0003בחזרה,\u0004 שהאיש חושב: אם יתברר שהממון אינו שלי — אחזיר אותו, ואילו \u0003שבועה ליתיה\u0004 \u0005[אינה]\u0006 \u0003בחזרה,\u0004 שמכיון שנשבע לשקר שוב אין לו תקנה לזה, ומשום כך נזהר אדם בשבועה יותר מבממון.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא\u0004 את השאלה הבאה: שנים שבאו כשאוחזים שניהם בטלית ו\u0003תקפה\u0004 (תפסה בכח) \u0003אחד\u0004 מהם \u0003בפנינו,\u0004 שבפני בית הדין משך והוציא את כל הטלית מידי חבירו מהו הדין כאן?","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דשתיק\u0004 \u0005[אם\u0006 זה שנחטף מידו \u0005שותק],\u0006 הרי יש לומר שעל ידי כך \u0003אודויי אודי ליה\u0004 \u0005[מודה הוא לו]\u0006 לחבירו, שהוא צודק בטענתו, \u0003ואי דקא צווח\u0004 \u0005[ואם שהוא צווח]\u0006 על גזילה זו, \u0003מאי הוה ליה למעבד\u0004 \u0005[מה היה לו לעשות\u0006 עוד\u0005]?\u0006 ובוודאי העובדה שהשני חזק ממנו איננה משנה מבחינת הדין?","ומסבירים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 לומר אלא למקרה \u0003דשתיק מעיקרא והדר\u0004 \u0005[ששתק מתחילה\u0006 כשחטף ממנו \u0005וחזר\u0006 אחר כך\u0005]\u0006 ו\u0003צווח, מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 וצדדי השאלה: האם נאמר כי \u0003מדאשתיק אודויי אודי ליה\u0004 \u0005[מכיון ששתק\u0006 בתחילה, \u0005הודה לו]\u0006 שהוא צודק, ורק אחר כך התחרט, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דקא צווח השתא\u0004 \u0005[שהוא צווח עכשיו]\u0006 על העוול שנעשה לו בכך \u0003איגלאי מילתא דהאי דשתיק מעיקרא\u0004 \u0005[נתגלה הדבר שמה ששתק מתחילה]\u0006 הוא משום ש\u0003סבר: הא קא חזו ליה רבנן\u0004 \u0005[הרי חכמים רואים אותו,\u0006 את הדבר\u0005]\u0006 ומה לי לצעוק.","\u0003אמר רב נחמן: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו, ממה ששנינו: \u0003במה דברים אמורים\u0004 ששניהם נשבעים ונוטלים — כ\u0003ששניהם אדוקין\u0004 \u0005(מחזיקים)\u0006 \u0003בה,\u0004 בטלית, \u0003אבל\u0004 אם \u0003היתה\u0004 ה\u0003טלית יוצאת מתחת ידו של אחד מהם,\u0004 אין כאן מקום לשבועת שניהם, אלא \u0003המוציא מחבירו עליו הראיה,\u0004 ואם אין ראיה תשאר בחזקת המחזיק בה. ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 \u0003כדקתני\u0004 \u0005[כפי ששנינו],\u0006 אם כן, \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכך הוא, שכל הבא וטוען לזכות על חפץ של חבירו ודאי שצריך להביא ראיה. \u0003אלא\u0004 ודאי מדובר כאן באופן \u0003שתקפה אחד בפנינו,\u0004 וכעין שאלתו של ר' זירא, ואם כן יש מכאן לכאורה פתרון לשאלה.","ודוחים: \u0003לא,\u0004 אפשר לומר כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון דאתו לקמן כדתפיסו לה תרוייהו\u0004 \u0005[שבאו לפנינו כשמחזיקים אותו שניהם]\u0006 \u0003ואמרינן להו\u0004 \u0005[ואמרנו להם]:\u0006 \u0003זילו פלוגו\u0004 \u0005[לכו\u0006 ו\u0005חלוקו],\u0006 \u0003ונפקו, והדר אתו כי תפיס לה חד מינייהו\u0004 \u0005[ויצאו, וחזרו\u0006 ו\u0005באו כאשר תופס אותה אחד מהם],\u0006 \u0003האי\u0004 \u0003אמר\u0004 \u0005[זה,\u0006 המחזיק, \u0005אומר]:\u0006 \u0003אודויי אודי\u0004 \u0005[הודה]\u0006 \u0003לי\u0004 השני בכך שלא רצה להשבע שאני צודק. \u0003והאי אמר\u0004 \u0005[וזה\u0006 שאין הטלית בידו \u0005אומר]:\u0006 \u0003בדמי אגרתי ניהליה\u0004 \u0005[בכסף השכרתי לו]\u0006 את חצי הטלית, ולא ויתרתי על זכותי בה, \u0003דאמרינן ליה\u0004 \u0005[שאומרים אנו לו]\u0006 במקרה כגון זה לטוען כנגד המחזיק: אי אפשר לקבל את טענתך, כי \u0003עד השתא\u0004 \u0005[עכשיו]\u0006 \u0003חשדת ליה\u0004 \u0005[לו,\u0006 בו\u0005]\u0006 כ\u0003גזלן\u0004 וטענת שלקח חפץ שאתה מצאת, \u0003והשתא מוגרת ליה בלא סהדי\u0004 \u0005[ועכשיו אתה משכיר לו\u0006 דבר \u0005בלי עדים],\u0006 ולכן אין טענתך מסתברת והמוציא מחבירו עליו הראיה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שאפשר להבין את הברייתא באופן אחר, \u0003כדקתני\u0004 \u0005[כפי ש\u0006היא \u0005שנויה]\u0006 ובאופן זה: \u0003דאתו לקמן כי תפיס לה חד מינייהו ואידך מסרך בה סרוכי\u0004 \u0005[שבאו לפנינו כאשר תופס בה\u0006 בגופה של הטלית \u0005אחד מהם, והאחר נסרך,\u0006 נמשך ומחזיק בקצה\u0005],\u0006 \u0003ואפילו ל\u0004שיטת \u0003סומכוס\u0004 ש\u0003אמר\u0004 בכלל ש\u0003ממון המוטל בספק חולקין\u0004 אותו הצדדים ביניהם \u0003בלא שבועה,\u0004 במקרה זה \u0003מודה סומכוס דסרכא\u0004 \u0005[שסריכה,\u0006 גרירה\u0005]\u0006 שאדם נגרר ואוחז בדבר \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כלום היא.\u0004","שאלתו של ר' זירא לא נפתרה איפוא, ואולם על בסיס שאלה זו חוזרים ושואלים אחרת: \u0003אם תמצי לומר\u0004 \u0005[\u0006תסכם \u0005ו\u0006\u0005תרצה לומר]\u0006 שאם \u0003תקפה אחד בפנינו מוציאין אותה מידו,\u0004 ממילא אם אחד מן הצדדים \u0003הקדישה\u0004 לכל הטלית — \u0003אינה מקודשת,\u0004 שהרי אינה שלו. ואולם \u0003אם תמצי לומר\u0004 \u0005[\u0006תסכם \u0005ו\u0006\u0005תרצה לומר]\u0006 להיפך ש\u0003תקפה אחד בפנינו אין מוציאים אותה מידו,\u0004 אם \u0003הקדישה בלא תקפה מהו\u0004 הדין בכגון זה? שאמנם לא חטף את הטלית מחבירו, אבל הקדיש את הטלית כולה.","וצדדי השאלה: \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 כלל בדיני העברת קנין: \u0003אמירתו לגבוה כמסירתו להדיוט דמי\u0004 \u0005[נחשב]\u0006, שלגבי הקדש (\"גבוה\") יש לאמירה תוקף של מעשה קנין, כפי שיש תוקף למסירת חפץ בפועל להדיוט (שאינו הקדש). וכאן, האם נאמר איפוא כי הקדיש \u0003כמאן\u0004 ש\u0003תקפה דמי\u0004 \u0005[נחשב],\u0006 שהרי אמירה זו דינה כמסירה בעדים,","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003השתא מיהא הא\u0004 \u0005[עכשיו על כל פנים הרי]\u0006 \u0003לא תקפה\u0004 והטלית עדיין אינה שלו, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ואיש כי יקדש את ביתו קדש\u0004 לה'\u0003\"\u0004 (ויקרא כז, יד), ולמדו מכאן: \u0003מה ביתו ברשותו\u0004 — \u0003אף כל\u0004 דבר שהוא \u0003ברשותו, לאפוקי האי\u0004 \u0005[להוציא\u0006 דבר \u0005זה]\u0006 שהוא \u0003לא ברשותו,\u0004 שהמקדיש דבר שאינו ברשותו, אין הקדשו הקדש.","וכדי לפתור את הבעיה מציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממעשה שהיה, \u0003דההיא\u0004"],["\u0003מסותא דהוו מנצו עלה בי תרי\u0004 \u0005[בית מרחץ אחד שהיו רבים עליו שנים],\u0006 \u0003האי\u0004 \u0005[זה]\u0006 \u0003אמר דידי\u0004 \u0005[שלי]\u0006 \u0003הוא והאי\u0004 \u0005[וזה]\u0006 \u0003אמר דידי\u0004 \u0005[שלי]\u0006 \u0003הוא. קם חד מינייהו אקדשה\u0004 \u0005[עמד אחד מהם\u0006 ו\u0005הקדיש אותו,\u0006 את המרחץ\u0005]\u0006 \u0003פרשי מינה\u0004 \u0005[פרשו ממנו,\u0006 מן המרחץ\u0005]\u0006 מלהשתמש בו \u0003רב חנניה ורב אושעיא וכולהו רבנן\u0004 \u0005[וכל החכמים],\u0006 שלא ידעו אם הקדש זה יש בו תוקף, ובינתיים נמנעו מלרחוץ בו מחשש מעילה בהקדש. \u0003ואמר\u0004 \u0003ליה\u0004 \u0005[לו]\u0006 \u0003רב אושעיא לרבה: כי אזלת קמיה\u0004 \u0005[כאשר הולך אתה\u0006 ללמוד \u0005לפני]\u0006 \u0003רב חסדא ל\u0004עיירה \u0003כפרי, בעי מיניה\u0004 \u0005[שאל אותו]\u0006 מה לעשות בכגון זה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 רבא בדרכו לכפרי \u0003ל\u0004עיר \u0003סורא\u0004 וסיפר את המעשה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב המנונא: מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא,\u0004 שמן המשנה אפשר ללמוד פתרון לבעיה זו. שכך שנינו במשנה: \u0003ספק בכורות\u0004 שלא ברור אם יש קדושה בהם, \u0003אחד בכור אדם\u0004 שלא ברור אם בכור הוא, \u0003ואחד בכור בהמה, בין טהורים\u0004 (כבכורות בקר וצאן), \u0003בין טמאים\u0004 (כבכורי חמורים) הכלל הוא: \u0003המוציא מחבירו עליו הראיה.\u0004 ואם הבכור נמצא בידי ישראל אין הכהן יכול לקחת אותו מידו. \u0003ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה]\u0006 כביאור על משנה זו, שספק בכורות אלה \u0003אסורים בגיזה ובעבודה\u0004 בהם כדרך שאסורים כל המוקדשים.","ומכאן טען רב המנונא: \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003אמר\u0004 שם \u0003תקפו כהן,\u0004 שלקח הכהן את הבכור הזה בכוח — \u0003אין מוציאים אותו מידו,\u0004 \u0003דקתני\u0004 \u0005[ש\u0006הרי \u0005שנה]\u0006 \u0003המוציא מחבירו עליו הראיה,\u0004 וכיון שהבכור בידי הכהן צריך עכשיו הישראלי להביא ראיה כדי שיוכל להוציא ממנו, \u0003וכי\u0004 \u0005[ו\u0006גם \u0005כאשר]\u0006 \u0003לא תקפו\u0004 (לקחו מידו) בכל זאת \u0003אסורין בגיזה ובעבודה.\u0004 משמע, שכל דבר שיכולה לחול עליו קדושה, אם יקחהו הכהן בחזקה — יש בו כבר מעתה צד מסויים של קדושה. וכן הוא לענין המרחץ.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה:\u0004 אין זו הוכחה, שאין הדברים דומים, כי \u0003קדושת בכור קאמרת\u0004 \u0005[אומר אתה]\u0006 — קדושה זו יש בה דין שונה, \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 לענין ספק בכורות אם \u0003תקפו כהן\u0004 — \u0003מוציאין אותו מידו\u0004 ואין תוקף לבעלות הבאה על ידי חטיפה, \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003אסורים\u0004 הם \u0003בגיזה ובעבודה\u0004 קודם לכן כיון ש\u0003קדושה הבאה מאליה שאני\u0004 \u0005[שונה].\u0006 שהרי קדושת הבכור אינה נובעת מתוך פעולה של הקדשה, אלא הבכור מתקדש מעצמו בשעת לידתו, וספק קדושתו איננו תלוי בבעלות עליו, אלא בספק עובדתי, וכל עוד לא יתברר הספק אסור ליהנות ממנו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חנניה לרבה: תניא דמסייע\u0004 \u0005[שנוייה\u0006 ברייתא \u0005המסייעת]\u0006 \u0003לך,\u0004 לדעתך, שספק בכור יש לו דין מיוחד. ששנינו: \u0003הספיקות נכנסין לדיר להתעשר,\u0004 שמכניסים אותם בין שאר הבהמות הצעירות שמהם מפרישים את מעשר בהמה.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי ספק בכור ש\u0003תקפו כהן אין מוציאים אותו מידו,\u0004 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003נכנסין לדיר?\u0004 הלא \u0003נמצא זה\u0004 שמכניסם לדיר \u0003פוטר ממונו בממונו של כהן,\u0004 שהרי, ייתכן שספק זה שייך לכהן, ואם הוא נותן אותו כמעשר, נמצא שפוטר עצמו מחובת מעשר בבהמה שיש לכהן זכות קנין בה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי\u0004 \u0005[אם]\u0006 \u0003משום הא\u0004 \u0005[זה]\u0006 \u0003לא תסייעיה למר\u0004 \u0005[תסייע לאדוני\u0006\u0005],\u0006 לרבה, כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — במקרה מיוחד, \u0003כגון דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003אלא תשעה\u0004 טלאים, \u0003והוא,\u0004 אותו טלה של ספק, שאז \u0003מה נפשך\u0004 \u0005[רצונך],\u0006 כלומר, בכל אופן שתרצה להבין זאת, הדבר מוצדק. כי \u0003אי בר חיובא\u0004 \u0005[אם בן חיוב]\u0006 \u0003הוא,\u0004 שאין בטלה זה קדושת בכור, אם כן \u0003שפיר קא\u0004 \u0005[יפה הוא]\u0006 \u0003מעשר\u0004 אותו. \u0003אי לאו בר חיובא\u0004 \u0005[\u0006ו\u0005אם\u0006 מעיקרו \u0005לא בן חיוב]\u0006 \u0003הוא,\u0004 שיש בו קדושת בכור, אולם אז הרי \u0003תשעה לאו בר עשורי נינהו\u0004 \u0005[לא בני,\u0006 מחוייבי חובת \u0005מעשר הם]\u0006 ואותו אדם לא היה חייב לעשר עליהם. ועשירי זה אף אם נתנו כמעשר, לא הרוויח על ידיו מאומה.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר אביי\u0004 עצמו: \u0003לאו מילתא היא דאמרי דספיקא לאו בר עשורי היא\u0004 \u0005[אין זה דבר\u0006 של ממש \u0005מה שאמרתי שהספק איננו בן חיוב להתעשר],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 אם היה אדם מעשר את צאנו ולא הגיע עד לעשרה ו\u0003קפץ אחד מן המנויין\u0004 כבר \u0003לתוכן,\u0004 לבין אלה שעדיין לא נמנו — \u0003כולן פטורים,\u0004 גם אלה שנמנו כבר, שהרי לגבי כל אחד מאלה שלא נמנו קיים ספק אם כבר נמנו למעשר, ועל כן כולם בספק ופטורים.","\u0003ואי סלקא דעתך ספיקא בעי עשורי\u0004 \u0005[ואם עולה על דעתך\u0006 לומר כי \u0005ספק צריך לעשר]\u0006 אם כן \u0003לעשר\u0004 \u0005[שיעשר]\u0006 באותו אופן \u0003ממה נפשך:\u0004 \u0003דאי בר חיובא\u0004 \u0005[שאם בן חיוב]\u0006 \u0003הוא\u0004 מחזור זה של עשרה היוצא עכשיו — \u0003שפיר\u0004 \u0005[יפה]\u0006 הוא \u0003מעשר,\u0004 \u0003ואי לאו בר חיובא\u0004 \u0005[ואם לא בן חיוב]\u0006 \u0003הוא,\u0004 שבין עשרה אלה יצא גם המנוי כבר, הרי מכל מקום כל אחד מהתשעה האחרים \u0003נפטר\u0004 מן המעשר \u0003במנין הראוי.\u0004","שכן \u0003אמר רבה: מנין הראוי פוטר.\u0004 כלומר, אם מנה טלאים למעשר ובשעת המניה היה מנין זה ראוי, ואירע שלא יכול להפריש מעשר בפועל, כגון שאחד מן הנותרים מת, ושוב אין לו עשרה להפריש מהם, מכל מקום, אלה שהיו במנין הראוי להתעשר כבר — נפטרו מן המעשר, ואין צריך לחזור בשנה הבאה ולעשר עבורם."],["\u0003אלא מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר],\u0006 להסביר מפני מה לא חייבו אדם זה לעשר ממה נפשך — כי \u0003עשירי ודאי אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 שצריך לעשר \u0003ולא עשירי ספק. הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לומר: \u0003עשירי ודאי אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 \u0003ולא עשירי ספק.\u0004","לגופה של אותה ברייתא \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: מאי\u0004 \u0005[מה\u0006 הן\u0005]\u0006 \u0003ספיקות\u0004 אלה שדובר בהם? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר כאן ב\u0003ספק בכורות,\u0004 הלא \"וכל מעשר בקר וצאן כל אשר יעבור תחת השבט העשירי \u0003יהיה\u0004 \u0003קדש\u0004 לה'\u0003\"\u0004 (ויקרא כז, לב) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 \u0003ולא שכבר קדוש\u0004 מטעם אחר,","וזהו כיון שחלה עליו קדושת בכור מספק שוב אין קדושת מעשר חלה עליו. \u0003אלא ספק פדיון פטר חמור,\u0004 שאם נולד אצל אדם חמור, ולא ברור לו אם חמור זה הוא בכור (\"פטר חמור\") ומספק נהג בו כבכור ופדה אותו בשה, הרי שה זה הוא ספק פדיון פטר חמור, \u0003וכ\u0004דברי \u0003רב נחמן,\u0004 ש\u0003אמר רב נחמן אמר רבה בר אבוה: ישראל שיש לו עשרה ספק פטרי חמור בתוך ביתו — מפריש עליהן עשרה שיין\u0004 לפוטרו מן הספק, \u0003ומעשרן,\u0004 מפריש אחד מהם מעשר, \u0003והן\u0004 כולם \u0003שלו,\u0004 שהרי אין הכהן יכול להוכיח שאחד מאלה שייך לו.","ושואלים: \u0003מאי הוי עלה דמסותא\u0004 \u0005[מה היה עליה,\u0006 על בעיה זו של \u0005בית המרחץ]?\u0006 שהרי מן הדיון לא הגענו לידי פתרון. \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ש\u0003אמר רב חייא בר אבין: הוה עובדא בי\u0004 \u0005[היה מעשה בבית]\u0006 \u0003רב חסדא\u0004 כעין זה, \u0003ו\u0004מעשה שהיה ל\u0003רב חסדא\u0004 \u0003בי\u0004 \u0005[בבית]\u0006 \u0003רב הונא, ופשטה מהא\u0004 \u0005[ופתר\u0006 את הבעיה \u0005מזו]\u0006 ש\u0003אמר רב נחמן: כל ממון שאין יכול להוציאו בדיינין\u0004 מיד המחזיק בו, אם \u0003הקדישו\u0004 — \u0003אינו קדוש.\u0004","בעייתנו נפתרה איפוא, אך לגוף דברי רב נחמן שואלים, אם נדייק מכאן, נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יכול להוציאו בדיינים,\u0004 ו\u0003הקדישו\u0004 — \u0003קדוש, אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא אפקיה\u0004 \u0005[הוציאן]\u0006 עדיין, \u0003ו\u0004אולם, \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003ר' יוחנן: גזל\u0004 מחבירו חפץ \u0003ולא נתייאשו הבעלים\u0004 מן הגזילה — \u0003שניהם,\u0004 לא הבעלים ולא הגזלן, \u0003אינם יכולים להקדישו. זה,\u0004 הגזלן — \u0003לפי שאינה שלו, וזה,\u0004 הבעלים — \u0003לפי שאינה ברשותו.\u0004 משמע שאין אדם יכול להקדיש אפילו חפץ שלו, אם אינו ברשותו ממש.","ומשיבים: \u0003מי סברת במסותא\u0004 \u0005[האם סבור אתה שבמרחץ]\u0006 ב\u0003מטלטלין\u0004 שבו \u0003עסקינן\u0004 \u0005[אנו עוסקים]?\u0006 \u0003לא, במסותא מקרקעי עסקינן\u0004 \u0005[במרחץ\u0006 שבגוף \u0005הקרקעות אנו עוסקים]\u0006 \u0003דכי\u0004 \u0005[שכאשר]\u0006 \u0003יכול\u0004 \u0003להוציאה בדיינין,\u0004 אין כאן צורך להוציאה מיד המחזיק בה, ולכן כבר עתה \u0003ברשותיה קיימא\u0004 \u0005[ברשותו\u0006 היא \u0005עומדת].\u0006","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב תחליפא בר מערבא\u0004 \u0005[בן ארץ ישראל]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' אבהו\u0004 ברייתא זו: \u0003שנים אדוקים\u0004 (מחזיקים) \u0003בטלית\u0004 — \u0003זה נוטל עד מקום שידו מגעת, וזה נוטל עד מקום שידו מגעת, והשאר,\u0004 כל מה ששניהם אינם מחזיקים בו, \u0003חולקים בשוה. מחוי ליה\u0004 \u0005[הראה לו]\u0006 \u0003ר' אבהו\u0004 בסימן שהראה בידו, שיש להוסיף שאת השאר חולקים \u0003בשבועה.\u0004","ושואלים: \u0003אלא מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003דקתני דפלגי בהדדי\u0004 \u0005[ששנה\u0006 בה \u0005שחולקים זה עם זה]\u0006 \u0003ולא קתני\u0004 \u0005[שנה]\u0006 \u0003זה נוטל עד מקום שידו מגעת\u0004, \u0003היכי משכחת לה\u0004 \u0005[כיצד אתה מוצא אותה],\u0006 כיצד נתאר מצב זה? \u0003אמר רב פפא:\u0004 ששניהם אינם אוחזים בטלית עצמה, אלא \u0003דתפיסי בכרכשתא\u0004 \u0005[שאוחזים בציציות]\u0006 היוצאות ממנה ולכן צריכים הם להשבע ולחלק את כל הטלית.","\u0003אמר רב משרשיא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 מדברי רב פפא כי \u0003האי סודרא\u0004 \u0005[סודר זה]\u0006 שנותן אדם לחבירו כדי לעשות בו קנין, אינו צריך לתת את הסודר כולו, אלא \u0003כיון דתפיס ביה\u0004 \u0005[שתפס בו]\u0006 שיעור כדי \u0003שלש על שלש\u0004 אצבעות, שבכך יש לו ערך מסויים, \u0003קרינן ביה\u0004 \u0005[קוראים אנו בו]\u0006 כבר \u0003\"ונתן לרעהו\"\u0004 כאמור \"וזאת לפנים בישראל... לקיים כל דבר, שלף איש נעלו ונתן לרעהו, וזאת התעודה בישראל\" (רות ד, ז),","\u0003דכמאן דפסיק דמי\u0004 \u0005[שכאילו היה חתוך\u0006 הוא \u0005נחשב]\u0006 כפי שאמרנו בדיני מציאה, \u0003ו\u0004את אותו חלק שמסר הריהו \u0003קני\u0004 \u0005[קונה],\u0006 עושה קנין בנתינה זו, אף שחלק שבידו מחובר לסודר.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 דין זה \u0003מ\u0004מה שאמר \u0003רב חסדא,\u0004 ש\u0003אמר רב חסדא:\u0004 נתן הבעל את ה\u0003גט בידה\u0004 של האשה \u0003ומשיחה\u0004 (חוט הקשור בגט) \u0003בידו, אם\u0004 הוא במצב ש\u0003יכול לנתקו\u0004 (למושכו) \u0003ולהביאו אצלו\u0004 באמצעות החוט — \u0003אינה מגורשת, ואם לאו\u0004 \u0005[לא],\u0006 שאינו יכול וכגון שהחוט חלש מדי — הרי היא \u0003מגורשת.\u0004 משמע, שכל עוד חלק מן הגט בידו, אינו נחשב כאילו ניתן לה!","ומשיבים: יש לחלק: \u0003התם\u0004 \u0005[שם]\u0006 בגט — גט \u0003כריתות\u0004 \u0003בעינן, וליכא\u0004 \u0005[צריכים אנו\u0006 שיהיה, \u0005ואין כאן],\u0006 שהרי לא ניתק הקשר ביניהם לגמרי, וכל עוד יש לבעל קשר כל שהוא בגט אין כאן כריתות. ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 בקניינים \u0003נתינה בעינן, והא איכא\u0004 \u0005[אנו צריכים, והרי יש].\u0006","\u0003אמר רבא:\u0004 גם \u0003אם היתה\u0004 זו \u0003טלית מוזהבת —\u0004 \u0003חולקין.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 ומדוע יהא דינה אחר? ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דקאי דהבא בי מצעי\u0004 \u0005[שעומד,\u0006 נמצא, \u0005הזהב באמצע],\u0006 לא בידו של זה ולא בידו של זה.","ותוהים שוב: \u0003הא נמי פשיטא\u0004 \u0005[זה גם כן פשוט,\u0006 מובן מאליו\u0005],\u0006 הרי אמרנו שחולקים בשאר! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דמיקרב לגבי דחד\u0004 \u0005[ש\u0006היה הזהב \u0005קרוב\u0006 יותר \u0005אל אחד\u0006 מהם\u0005]\u0006 אף שלא החזיק בו. \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 זה שהזהב קרוב אליו: \u0003פלוג הכי\u0004 \u0005[חתוך כך]\u0006 שנחלק את הטלית בדיוק בקו האמצע בין שנינו, ואז ימצא רוב הזהב בידו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רבא \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 השני: \u0003מאי חזית דפלגת הכי\u0004 \u0005[מה ראית שאתה חותך כך]\u0006 בקו אמצעי זה? \u0003פלוג הכי\u0004 \u0005[חתוך כך]\u0006 בדרך אחרת, כך שהזהב יתחלק בין שנינו בשווה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שנים\u0004 שהיו \u0003אדוקין\u0004 (מחזיקים) \u0003בשטר,\u0004 ה\u0003מלוה אומר: שלי הוא\u0004 השטר, שלא נפרע עדין \u0003ונפל ממני\u0004 וחזרתי \u0003ומצאתיו\u0004, \u0003ולוה אמר:\u0004 השטר אמנם \u0003שלך הוא,\u0004 כלומר, היה שלך, \u0003ו\u0004אולם כבר \u0003פרעתיו לך\u0004 והחזרת אותו לי וממני אבד, בכגון זה — \u0003יתקיים השטר בחותמיו,\u0004 כלומר, יבררו קודם את טיבו של השטר ויבדקו אם העדים שחתמו בו מאשרים אותו, אלו \u0003דברי רבי.\u0004","\u0003רבן שמעון בן גמליאל אומר: יחלוקו\u0004 המלוה והלווה בסכום שבשטר, מפני הספק.","ואם \u0003נפל\u0004 שטר כגון זה \u0003ליד דיין\u0004 ואין שני הצדדים מודים למי מהם שייך השטר — \u0003לא יוציאו\u0004 בעלי הדין \u0003עולמית\u0004 את השטר לגבייה, וימתינו עד שתמצא ראיה. \u0003ר' יוסי אומר: הרי הוא בחזקתו\u0004 ויעשו מה שכתוב בו.","את הברייתא הזו מבררים: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003יתקיים השטר בחותמיו.\u0004 ולכאורה המסקנה למעשה היא: \u0003ו\u0004כאשר אכן יתקיים השטר \u0003גבי ליה\u0004 \u0005[גובה אותו]\u0006 ה\u0003מלוה כוליה\u0004 \u0005[כולו],\u0006 ושואלים: \u0003ו\u0004כי \u0003לית ליה מתניתין\u0004 \u0005[אין לו,\u0006 איננו מקבל, את \u0005הדין ששנינו ב\u0006\u0005משנתנו]\u0006 ב\u0003שנים אוחזין\u0004 בטלית? ואם כן, כמו שבטלית יש לכל אחד מהם חצי, אף בשטר נאמר שלכל אחד מהם יש זכות לחצי השטר ולא יותר!","\u0003אמר רבא אמר רב נחמן:\u0004 \u0003ב\u0004שטר \u0003מקוים,\u0004 כשכבר יש עליו אישור בית הדין שבדקו ומצאוהו שהוא נכון, והריהו כממון — \u0003דברי הכל יחלוקו\u0004 בו, \u0003כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חלוקים]\u0006 הרי זה \u0003ב\u0004אופן שהיה זה שטר \u0003שאינו מקוים\u0004 עדיין.","\u0003רבי סבר:\u0004 אפילו הלווה \u0003מודה בשטר שכתבו\u0004 — \u0003צריך\u0004 המלוה \u0003לקיימו\u0004 אם רוצה לגבות בו. \u0003ו\u0004לכן, \u0003אי מקיים ליה פליג\u0004 \u0005[אם יקיימו\u0006 את השטר \u0005הזה\u0006 בבית דין \u0005יחלוק]\u0006 המלוה עם הלווה, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא מקיים ליה\u0004 \u0005[יקיים אותו]\u0006 המלוה \u0003לא פליג\u0004 \u0005[יחלוק].\u0006 שאם למשל לא יוכל לאמת את חתימת העדים, לא יקבל מאומה אף שהלווה מודה שאכן לווה בשטר זה.","\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של רבי? — לדעתו שטר בלתי מקוים \u0003חספא בעלמא\u0004 \u0005[חרס בלבד]\u0006 \u0003הוא,\u0004 שאין לו ערך כל עוד לא נתקיים, \u0003מאן קא משוי ליה להאי שטרא\u0004 \u0005[מי הוא\u0006 זה ש\u0005עושה אותו,\u0006 את הנייר \u0005הזה לשטר\u0006 שיש בו ממש\u0005]\u0006 — ה\u0003לוה,\u0004 ואולם כיון שתוקפו של השטר תלוי רק בדברי הלוה \u0003הא קאמר דפריע\u0004 \u0005[הרי הוא\u0006 עצמו \u0005אומר ש\u0006השטר \u0005פרוע],\u0006 ולכן אין ערך לשטר זה, ולפיכך אין לדון בו עד שיתקיים.","\u0003ו\u0004אילו \u0003ר' שמעון בן גמליאל סבר: מודה בשטר שכתבו אין צריך לקיימו,\u0004 והשטר חזקתו שהוא אמיתי, \u0003ואף על גב דלא מקיים ליה\u0004 \u0005[ואף על פי שאיננו מקיים אותו]\u0006 — \u0003יחלוקו.\u0004","שנינו בברייתא שאם \u0003נפל\u0004 השטר \u0003ליד דיין לא יוציאו\u0004 אותו בעלי הדין מידיו \u0003עולמית,\u0004"],["\u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 שנפל השטר \u0003ליד דיין\u0004 מאשר אם נפל לידו של אחר? \u0003אמר רבא: הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003ואחר,\u0004 כל אדם, \u0003שמצא שטר שנפל\u0004 כבר \u0003ליד דיין, והיכי דמי\u0004 \u0005[וכיצד הוא]\u0006 דבר זה — ש\u0003כתב ביה\u0004 \u0005[שכתוב בו,\u0006 בשטר] \u0003הנפק\u0004 (קיום), ושטר זה \u0003לא יוציאו עולמית.\u0004","ותוהים: \u0003ו\u0004שטר כזה, \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 בשטר ש\u0003לא כתב ביה\u0004 \u0005[כתוב בו]\u0006 \u0003הנפק?\u0004 והרי זה שאין בו הנפק, מסופק יותר, משום \u0003דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]\u0006 שהלווה אמנם כתב \u0003ללות ולא לוה\u0004 בו כלל, ומדוע יחזיר המוצא את השטר? \u0003אלא\u0004 יש להבין: \u0003אפילו כתב ביה\u0004 \u0005[בו]\u0006 \u0003הנפק,\u0004 ששטר זה \u0003מקוים, לא יחזיר\u0004 אותו למלוה משום \u0003דחיישינן\u0004 \u0005[שאנו חוששים]\u0006 \u0003לפירעון,\u0004 שמא פרע הלוה את השטר וממנו אבד.","\u0003ור' יוסי אומר: הרי הוא בחזקתו ולא חיישינן\u0004 \u0005[ואין אנו חוששים]\u0006 \u0003לפירעון,\u0004 שבודאי אם היה הלווה פורע היה מיד משמיד את השטר, ולא משהה אותו בביתו. ושואלים: \u0003ו\u0004האם \u0003לא חייש\u0004 \u0005[חושש]\u0006 \u0003ר' יוסי לפירעון?\u0004","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מצא שטר כתובה בשוק, בזמן שהבעל מודה\u0004 שעדיין לא שילם את דמי הכתובה לאשתו — \u0003יחזיר לאשה, אין הבעל מודה\u0004 ואומר שפרע כבר את הכתובה — \u0003לא יחזיר לא לזה ולא לזה.\u0004","\u0003ר' יוסי אומר,\u0004 יש לחלק: אם האשה \u0003עודה תחת בעלה\u0004 (עדיין נשואה) — \u0003יחזיר לאשה,\u0004 שמן הסתם לא נתן הבעל את דמי הכתובה לאשתו בעודה נשואה לו. ואם \u0003נתארמלה\u0004 (נתאלמנה) האשה \u0003או נתגרשה\u0004 — \u0003לא יחזיר לא לזה ולא לזה,\u0004 שאז יש לחשוש שמא כבר קיבלה את דמי הכתובה, והשטר נפל מידי הבעל או יורשיו. ומכאן שר' יוסי הוא החושש לפירעון!","ומתרצים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את הגירסה בברייתא שלנו ושנה כך: \u0003נפל ליד דיין לא יוציאו עולמית,\u0004 אלו \u0003דברי ר' יוסי, וחכמים אומרים: הרי הוא בחזקתו.\u0004","ומעירים: \u0003אי הכי קשיא דרבנן אדרבנן\u0004 \u0005[אם כך קשה\u0006 מדברי \u0005חכמים על\u0006 דברי \u0005חכמים],\u0006 שלפי נוסח הברייתא המתוקן החכמים אינם חוששים לפירעון, ואילו בדין שטר כתובה רואים שחכמים חוששים לפרעון!","ומתרצים: כל הברייתא הזו בדין \u0003שטר כתובה, כולה\u0004 כדברי \u0003ר' יוסי\u0004 ואין כאן מחלוקת, \u0003וחסורי מחסרא והכי קתני\u0004 \u0005[וחסרה\u0006 הברייתא \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003אין הבעל מודה\u0004 — \u0003לא יחזיר לא לזה ולא לזה. במה דברים אמורים\u0004 — באופן שנמצא שטר הכתובה לאחר \u0003שנתארמלה או שנתגרשה, אבל\u0004 אם נמצא ב\u0003עודה תחת בעלה\u0004 — \u0003יחזיר לאשה, שר' יוסי אומר: עודה תחת בעלה\u0004 — \u0003יחזיר לאשה, נתארמלה או שנתגרשה\u0004 — \u0003לא יחזיר לא לזה ולא לזה.\u0004","\u0003רב פפא אמר\u0004 שיש דרך אחרת לתרץ את הקושיה: \u0003לעולם לא תיפוך\u0004 \u0005[אל תהפוך]\u0006 את הגירסה והשאר את הנוסח כפי שהוא, אלא הסבר כי \u0003ר' יוסי לדבריהם דרבנן קאמר להו\u0004 \u0005[של חכמים אמר להם]\u0006 לענין שטר כתובה, שהוא טוען להם על בסיס סברתם שלהם, אף שהוא עצמו אינו חושש כלל לפירעון, וכך יש להבין את דבריו:","\u0003לדידי\u0004 \u0005[לי,\u0006 לשיטתי\u0005]\u0006 \u0003אפילו נתארמלה או נתגרשה נמי לא חיישינן\u0004 \u0005[גם כן אין אנו חוששים]\u0006 \u0003לפירעון,\u0004 שלשיטתו יש להחזיר כל שטר למי שהוא שייך לו. ואולם אף \u0003לדידכו\u0004 \u0005[לשיטתכם]\u0006 \u0003אודו\u0004 \u0005[הודו]\u0006 \u0003לי מיהת\u0004 \u0005[על כל פנים]\u0006 \u0003בעודה תחת בעלה\u0004 ש\u0003יחזיר לאשה, דלאו\u0004 \u0005[ש\u0006הרי עדיין \u0005לא]\u0006 \u0003בת פירעון היא\u0004 כתובה זו, שאין מסתבר ששטר כתובה זה נפרע ואבד מידי הבעל.","\u0003ואמרו ליה רבנן\u0004 \u0005[לו חכמים]:\u0006 אף כאן יש מקום לחשוש, \u0003אימור צררי אתפסה\u0004 \u0005[אמור\u0006 ש\u0005צרורות\u0006 כסף \u0005התפיס,\u0006 נתן \u0005לה]\u0006 והיא מחזיקה בכספים, ותמורת זאת החזירה לבעלה את הכתובה. ואם יחזירו לה את השטר ייצא שתגבה פעמיים.","\u0003רבינא אמר: לעולם איפוך קמייתא\u0004 \u0005[הפוך את\u0006 הברייתא \u0005הראשונה]\u0006 בדין שטר שנפל לדיין, \u0003ו\u0004את הסתירה שהיתה בדברי חכמים תרץ כך: \u0003טעמא דרבנן הכא\u0004 \u0005[טעמם של חכמים כאן\u0006 בכתובה\u0005],\u0006 \u0003משום דחיישינן\u0004 \u0005[שאנו חוששים]\u0006 שמא כתב \u0003שתי כתובות,\u0004 שאבדה הכתובה הראשונה והוצרך הבעל לכתוב שניה. \u0003ור' יוסי לשתי כתובות לא חייש\u0004 \u0005[חושש],\u0006 שלדעתו אין הדבר מצוי ואין לחשוש לדבר בלתי רגיל.","\u0003אמר ר' אלעזר: מחלוקת,\u0004 כלומר, דין זה שאמר רבן שמעון בן גמליאל בענין שנים אדוקים בשטר שיחלקו ביניהם את השטר, הרי זה דווקא \u0003בששניהם אדוקים\u0004 (מחזיקים) \u0003בטופס\u0004 של השטר, כלומר, בחלק השטר שיש בו נוסח קבוע של שטרות, או \u0003שניהם\u0004 אדוקים \u0003בתורף,\u0004 בחלק השטר המיוחד שכתובים בו שמות הלווה והמלוה והסכום. \u0003אבל\u0004 אם היה \u0003אחד אדוק בטופס ואחד אדוק בתורף\u0004 — מחלקים לפי מה ששניהם מחזיקים בו, \u0003זה נוטל טופס וזה נוטל תורף. ור' יוחנן אמר: לעולם חולקין\u0004 הכל,","\u0003ואפילו אחד אדוק בטופס ואחד בתורף.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שהבאנו קודם: \u0003זה נוטל עד מקום שידו מגעת\u0004 וזה נוטל עד מקום שידו מגעת! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו שקבע ר' יוחנן אלא במקרה \u0003דקאי\u0004 \u0005[שעומד,\u0006 נמצא\u0005]\u0006 ה\u0003תורף בי מצעי\u0004 \u0005[באמצע],\u0006 במקום ששניהם אינם מחזיקים בו.","ושואלים: \u0003אי הכי מאי למימרא\u0004 \u0005[אם כך מה\u0006 יש \u0005לומר]?\u0006 ומה חידוש בקביעה זו? ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 לומר אלא לאופן \u0003דמקרב לגבי דחד\u0004 \u0005[ש\u0006התורף \u0005קרוב\u0006 יותר \u0005לאחד\u0006 מהם\u0005].\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הקרוב לתורף: \u0003פלוג הכי\u0004 \u0005[חלוק\u0006 לי את השטר \u0005כך]\u0006 בדיוק בקו הממוצע בינינו, שהתורף יהיה בצד שלי, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ר' יוחנן \u0003דאמר ליה\u0004 \u0005[שאומר לו\u0006 האחד\u0005]:\u0006 \u0003מאי חזית דפלגת הכי\u0004 \u0005[מה ראית שאתה חולק כך]\u0006 בכיוון אחד שיהיה התורף בצדך? \u0003פלוג הכי\u0004 \u0005[חלוק כך],\u0006 בכיוון אחר, ויהא התורף באמצע.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא:\u0004 \u0003ל\u0004שיטת \u0003ר' אלעזר\u0004 ש\u0003אמר זה נוטל טופס וזה נוטל תורף,\u0004 זה שנטל את הטופס \u0003למה ליה\u0004 \u0005[לו]?\u0006 \u0003וכי לצור על פי צלוחיתו הוא צריך\u0004 את השטר? שהרי בתורף השטר אי אפשר לגבות ואינו ראוי אלא להשתמש בו כנייר, ולעטוף בו פי צלוחית!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: אין הכוונה שחולקים ונוטלים מגוף השטר עצמו ומקבל נייר בלבד אלא \u0003לדמי\u0004 \u0005[לדמים],\u0006 לשווי, שמעריכים כמה שווה חלק זה של השטר ביחס לחלק האחר.","\u0003דאמר הכי\u0004 \u0005[ש\u0006הוא \u0005אומר כך]:\u0006 \u0003שטרא דאית ביה\u0004 \u0005[שטר שיש בו],\u0006 שכתוב בו \u0003זמן,\u0004 תאריך, שהוא המצוי בתורף \u0003כמה שוי\u0004 \u0005[\u0006הוא \u0005שווה]?\u0006 \u0003ודלית ביה\u0004 \u0005[ו\u0006שטר \u0005שאין בו]\u0006 \u0003זמן כמה שוי\u0004 \u0005[\u0006הוא \u0005שווה]?\u0006 ומה ההבדל? — \u0003בשטרא דאית ביה\u0004 \u0005[בשטר שיש בו]\u0006 \u0003זמן,\u0004 שנכתב בו תאריך — \u0003גבי ממשעבדי\u0004 \u0005[\u0006יכול \u0005לגבות\u0006 את החוב גם \u0005מ\u0006קרקעות \u0005משועבדות]\u0006 שמכרם הלווה לאדם אחר לאחר זמן ההלוואה, שמזמן ההלוואה יש שעבוד מוקדם למלוה. \u0003ואידך\u0004 \u0005[האחר]\u0006 שאין בו זמן \u0003לא גבי ממשעבדי\u0004 \u0005[אינו גובה\u0006 בו \u0005ממשועבדים]\u0006 אלא רק מקרקעות הנמצאות ברשותו של הלווה. \u0003יהיב ליה היאך דביני ביני\u0004 \u0005[יתן לו האחד\u0006 את \u0005שבינתיים],\u0006 את סכום ההבדל.","\u0003ו\u0004בדרך כלל \u0003\"יחלוקו\" נמי דאמרן\u0004 \u0005[גם כן שאמרנו]\u0006 בשאר מקרים — גם שם הכוונה \u0003לדמי\u0004 \u0005[לכסף],\u0006 לענין שווי נאמר, ולא לחלוקת החפץ ממש. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שהכוונה היא שיתחלקו במחיר, אם כן \u0003שנים אוחזין בטלית הכי נמי דפלגי\u0004 \u0005[כך גם כן\u0006 תאמר \u0005ש\u0006הם \u0005חולקים],\u0006 חותכים את הטלית לשני חלקים? \u0003הא אפסדוה\u0004 \u0005[הרי\u0006 בכך \u0005הפסידוה,\u0006 קלקלו אותה\u0005]!\u0006 ודוחים: \u0003הא לא קשיא\u0004 \u0005[זה איננו קשה],\u0006 שאפשר לפרש שבאמת חותכים את הטלית לשניים, וששאלת מה יעשו בחצי טלית?"],["\u0003דחזיא\u0004 \u0005[ש\u0006היא \u0005ראויה]\u0006 \u0003ל\u0004ילדים \u0003קטנים,\u0004 ולכן אפשר לחלק אותה ולכל אחד יש ערך מסויים.","ומקשים: \u0003והא\u0004 \u0005[וזו]\u0006 ש\u0003אמר רבא: אם היתה טלית מוזהבת\u0004 — \u0003חולקים, הכי נמי דפלגי לה\u0004 \u0005[כך גם כן\u0006 תאמר \u0005ש\u0006הם \u0005חולקים אותה\u0006 ממש\u0005]\u0006 \u0003הא אפסדוה\u0004 \u0005[הרי\u0006 בכך הם \u0005מפסידים אותה]!\u0006 ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זו איננה קשה],\u0006 \u0003דחזיא\u0004 \u0005[שראויה]\u0006 טלית זו כשהיא חצויה \u0003לבני מלכים\u0004 ועשירים הקטנים ואינה נפסדת איפוא עם חלוקתה לשניים.","ושואלים: \u0003והא דתנן\u0004 \u0005[וזו ששנינו\u0006 במשנה\u0005]\u0006 \u0003היו שנים רוכבים על גבי בהמה,\u0004 זה אומר \"כולה שלי\", וזה אומר \u0003\"כולה שלי\",\u0004 ששנינו שחולקים את הבהמה, \u0003הכי נמי דפלגי לה\u0004 \u0005[\u0006תפרש \u0005כך גם כן שחולקים אותה\u0006 ממש לשניים\u0005]?\u0006 \u0003הא אפסדוה\u0004 \u0005[הרי\u0006 בכך \u0005הפסידו אותה]!\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 אם היתה זו בהמה \u0003טהורה\u0004 יכול אתה לפרש כי \u0003חזיא\u0004 \u0005[ראויה]\u0006 היא \u0003לבשר,\u0004 שכל אחד מקבל חצי בשרה. \u0003אלא\u0004 אם היתה זו בהמה \u0003טמאה הא אפסדוה\u0004 \u0005[הרי הפסידו\u0006 את כל ערכה\u0005]!\u0006 \u0003אלא\u0004 על כרחך הכוונה \u0003לדמי\u0004 \u0005[למחיר],\u0006 \u0003הכא נמי לדמי\u0004 \u0005[כאן גם כן,\u0006 בשאר ענייני חלוקה הכוונה היא \u0005למחיר]\u0006 ולא לחלוקת גוף החפץ.","\u0003אמר רמי בר חמא: זאת אומרת,\u0004 כלומר, מתוך דברי המשנה ניתן להוציא את הכלל הבא: \u0003המגביה מציאה לחבירו\u0004 (עבור חבירו) — \u0003קנה חבירו\u0004 זכות קנין במציאה. שכך יש להבין את ההלכה בשניים שמצאו טלית, ויש לומר שכל אחד ממוצאי הטלית לא רק זכה בה (בחציה) עבור עצמו, אלא גם זכה בחציה האחר עבור חבירו.","\u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003לא קנה חבירו,\u0004 אם כן אין כלל בעלים לטלית זו, שהרי כל אחד מהם כופר בבעלותו של האחר, ו\u0003תיעשה זו\u0004 (חלק זה בטלית) \u0003כמי שמונחת\u0004 שוב \u0003על גבי קרקע, וזו כמי שמונחת על גבי קרקע, ולא יקנה לא זה ולא זה,\u0004 וכל אדם יוכל לחטוף אותה מהם. \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003המגביה מציאה לחבירו\u0004 — \u0003קנה חבירו.\u0004","\u0003אמר רבא:\u0004 אין זו הוכחה, ו\u0003לעולם אימא\u0004 \u0005[\u0006יכול \u0005אני לומר]\u0006 \u0003לך\u0004 כי \u0003המגביה מציאה לחבירו\u0004 — \u0003לא קנה חבירו. והכא היינו טעמא\u0004 \u0005[וכאן זהו הטעם]:\u0006 \u0003מגו דזכי לנפשיה זכי נמי לחבריה\u0004 \u0005[מתוך ש\u0006הוא \u0005זוכה עבור עצמו\u0006 הוא \u0005זוכה גם כן עבור חבירו].\u0006","ומוסיף רבא: \u0003תדע\u0004 שכן הוא, \u0003שאילו אמר\u0004 אדם \u0003לשלוחו: \"צא וגנוב לי\" וגנב\u0004 השליח — \u0003פטור\u0004 המשלח, לפי הכלל: אין שליח לדבר עבירה. \u0003ושותפין שגנבו\u0004 מדעת שניהם, גם אם רק אחד מהם עשה את מעשה הפעולה עצמו, אלא שגנב גם לדעת חבירו — שניהם \u0003חייבין.\u0004 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל? — \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 \u0003מגו דזכי לנפשיה זכי נמי לחבריה\u0004 \u0005[מתוך ש\u0006הוא \u0005זוכה לעצמו\u0006 הוא \u0005זוכה גם כן עבור חבירו]\u0006 ולכן הגניבה נחשבת כשייכת לשני השותפים — ושניהם אחראים לגניבה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אמר רבא\u0004 בהמשך לדבריו הקודמים: \u0003השתא דאמרת\u0004 \u0005[עכשיו שאומר אתה]\u0006 כי \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 בכגון זה \u0003מגו,\u0004 שמתוך שלגבי הלכה אחת יש זכות קנין לאדם, אומרים כי זכות זו קיימת גם בתחום אחר, אפשר איפוא ללמוד מכאן דין חדש: \u0003חרש ופקח\u0004 (מי שאינו חרש) \u0003שהגביהו\u0004 שניהם יחד \u0003מציאה, מתוך שקנה\u0004 ה\u0003חרש\u0004 את חלקו במציאה \u0003קנה\u0004 גם ה\u0003פקח.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 כי \u0003חרש קנה\u0004 את חלקו במציאה — משום \u0003דקא מגבה ליה\u0004 \u0005[שמגביה לו,\u0006 עבורו\u0005]\u0006 \u0003בן דעת,\u0004 וכפי שאמרנו, מתוך שהפקח זוכה בחלקו הוא מזכה גם לחבירו. \u0003אלא פקח במאי\u0004 \u0005[במה]\u0006 \u0003קנה\u0004 את חלקו? הרי זכותו לחלקו שתפס מפוקפקת כי יש כנגדה טענה, והחרש אין בכוחו להקנות!","\u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003חרש\u0004 — \u0003קנה, פקח\u0004 — \u0003לא קנה.\u0004 ושואלים: \u0003ומאי\u0004 \u0005[ומהו]\u0006 \u0003מגו\u0004 זה שרבא מסתמך עליו כאן בדיון של חרש ופקח? ומשיבים: \u0003מגו\u0004 \u0005[מתוך]\u0006 שאם היו \u0003שני חרשים בעלמא\u0004 \u0005[סתם]\u0006 שהגביהו מציאה ששניהם \u0003קנו,\u0004 אם כן, \u0003האי נמי קני\u0004 \u0005[זה גם כן קנה]\u0006 את החפץ.","על כך תוהים: \u0003האי מאי\u0004 \u0005[זו מהי]?\u0006 כלומר, מה טיבה של הוכחה זו? \u0003אם תמצא לומר\u0004 כי \u0003המגביה מציאה לחבירו קנה חבירו,\u0004 כפי שאמר רמי בר חמא, ואולם \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא \u0003היכא דקא מגבה ליה אדעתא דחבריה\u0004 \u0005[שמגביה אותה,\u0006 את המציאה \u0005על דעת\u0006 שיקנה בה \u0005חבירו],\u0006 ואולם אפילו אז, \u0003האי\u0004 \u0005[זה]\u0006 המוצא הפקח \u0003אדעתא דידיה קא מגבה ליה\u0004 \u0005[על דעת עצמו\u0006 שיקנה הוא עצמו \u0005הוא מגביה אותה],\u0006 שהרי אינו מתכוון במיוחד שיזכה חבירו, ואולם אם \u0003איהו לא קני\u0004 \u0005[הוא\u0006 עצמו \u0005אינו קונה]\u0006 כפי שאמרנו שאין הפיקח קונה בחפץ, האם \u0003לאחריני מקני\u0004 \u0005[לאחרים\u0006 יכול הוא \u0005להקנות]?!\u0006","\u0003אלא\u0004 נחזור בנו ממה שאמרנו ו\u0003אימא\u0004 \u0005[אמור]\u0006 כך: \u0003מתוך שלא קנה\u0004 ה\u0003פקח\u0004 כל חלק במציאה — \u0003לא קנה\u0004 גם ה\u0003חרש.\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 דבר זה \u0003מ\u0004מציאה שמצאו \u0003שני חרשים\u0004 \u0003דעלמא\u0004 \u0005[סתם]\u0006 ששנינו שזכו בה משהגביהוה — יש לומר כי \u0003התם תקינו להו רבנן\u0004 \u0005[שם תקנו להם חכמים]\u0006 שיקנו שניהם כדי ש\u0003לא אתי לאנצויי\u0004 \u0005[יבואו להתקוטט]\u0006 עם אנשים אחרים שמצאו את המציאה וירצו לקחתה לעצמם, בהעדר זכות חוקית של החרשים, ולכן תקנו חכמים ואמרו ששניהם קונים. ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003מימר אמר\u0004 \u0005[אומר]\u0006 החרש בליבו: אף ה\u0003פקח לא קני\u0004 \u0005[אינו קונה],\u0006 \u0003אנא אקני\u0004 \u0005[\u0006ו\u0005אני אקנה]?\u0006 ולכן אם לוקחים אחרים את המציאה מידיהם אין הוא מתקוטט. עד כאן דנו בשאלה מה אפשר להסיק ממשנתנו לדיני זכיה במציאה בכללותם. ומעתה מנסים להעמיק יותר בשיטות אלה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אדא לרב אשי: דיוקיה\u0004 \u0005[דיוקו]\u0006 של \u0003רמי בר חמא מהיכא\u0004 \u0005[מהיכן]\u0006 בעצם הסיק הוא אותו? \u0003אי נימא מרישא\u0004 \u0005[אם נאמר מראשה]\u0006 של המשנה בדין \u0003\"שנים אוחזים בטלית\",\u0004 הלא \u0003התם\u0004 \u0005[שם]\u0006 \u0003האי קאמר\u0004 \u0005[זה אומר]\u0006 \u0003\"כולה שלי, ואנא אגבהתה\u0004 \u0005[ואני הגבהתי]\u0006 את \u0003כולה\", והאי אמר\u0004 \u0005[וזה אומר] \"\u0006\u0003כולה שלי ואנא אגבהתה\u0004 \u0005[ואני הגבהתי]\u0006 את \u0003כולה\",\u0004 ומהיכן למד מכאן לענין זכיה לאחר?","\u0003אלא\u0004 לא מקטע זה, כי אם \u0003מהא דקתני\u0004 \u0005[מזו ששנינו]\u0006 אחר כך \u0003\"זה אומר כולה שלי וזה אומר כולה שלי\" הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי,\u0004 שהרי אפשר להסתפק בטענה הראשונה \"זה אומר אני מצאתיה\". \u0003אלא ממשנה יתירה\u0004 ומכפל הלשון \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003המגביה מציאה לחבירו\u0004 — \u0003קנה חבירו,\u0004 שכל אחד מהם אומר \"כולה שלי\" — לענין זה שלאחרים ודאי אין זכות בה.","ומקשים: אולם משנה זו איננה יתירה, \u0003והא אוקימנא\u0004 \u0005[והרי\u0006 כבר \u0005העמדנו,\u0006 הסברנו\u0005]\u0006 ש\u0003רישא\u0004 \u0005[\u0006בקטע \u0005הראשון]\u0006 מדובר בסכסוך \u0003ב\u0004ענין \u0003מציאה, וסיפא\u0004 \u0005[\u0006והקטע \u0005בסוף]\u0006 מדבר בסכסוך \u0003ב\u0004ענין \u0003מקח וממכר!\u0004","\u0003אלא\u0004 לא מכאן יש לדייק, ואת דיוקו לומד הוא \u0003מסיפא\u0004 \u0005[מסופה\u0006 של המשנה\u0005],\u0006 ששנינו: \u0003\"זה אומר כולה שלי וזה אומר חציה שלי\" הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי?\u0004 מה חידוש הלכה מוסיף קטע זה על הקטעים הקודמים? \u0003אלא ממשנה יתירה\u0004 זו \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003המגביה מציאה לחבירו\u0004 — \u0003קנה חבירו.\u0004","ומקשים: \u0003וממאי\u0004 \u0005[וממה]\u0006 לומד אתה שקטע יתר זה עוסק \u0003במציאה? דלמא\u0004 \u0005[שמא]\u0006 הוא עוסק \u0003ב\u0004ריב לענין \u0003מקח וממכר?\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר כאן \u0003ב\u0004סכסוך לענין \u0003מקח וממכר מאי למימרא\u0004 \u0005[מה יש\u0006 פה \u0005לומר]\u0006 שאף בזה אין חידוש, ואולם בכל זאת \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 להודיענו מקרה נוסף זה מפני שיש בו חידוש. שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003האי דקאמר\u0004 \u0005[זה שאומר]\u0006 \u0003\"חציה שלי\" להוי\u0004 \u0005[שיהא,\u0006 ייחשב\u0005]\u0006 \u0003כמשיב אבידה,\u0004 שהרי היה יכול לטעון שכולה שלו, ומאחר שהוא מודה ואומר שרק חציה שלו, הרי הוא כנותן חציה לחבירו, וייחשב איפוא כמשיב אבידה \u0003וליפטר\u0004 \u0005[ושייפטר]\u0006 משבועה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין אנו אומרים כך, אלא חוששים \u0003דהאי איערומי קא מערים\u0004 \u0005[זה מערים]\u0006 הוא. \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003אי אמינא\u0004 \u0005[אם אומר אני]\u0006 \u0003\"כולה שלי\",\u0004 הלא \u0003בעינא אשתבועי\u0004 \u0005[אצטרך להשבע],\u0006 \u0003אימא הכי, דאהוי\u0004 \u0005[אומר\u0006 איפוא \u0005כך\u0006 שחציה שלי כדי \u0005שאהיה,\u0006 אחשב\u0005]\u0006 \u0003כמשיב אבידה ואיפטר\u0004 \u0005[ואפטר]\u0006 מן השבועה! וכיון שכך הרי יש בזה חידוש הלכה, ואין זה ייתור לשון ללמוד ממנו דבר אחר.","\u0003אלא מהא\u0004 \u0005[מ\u0006דבר \u0005זה]\u0006 למד רמי בר חמא, ששנינו במשנה: \u0003היו שנים רוכבים על גבי בהמה\u0004 וכו', ויש לשאול: \u0003הא תו\u0004 \u0005[זה עוד]\u0006 \u0003למה לי?\u0004 שאין בכך כל חידוש הלכתי, \u0003אלא ממשנה יתירה\u0004 ששנינו \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 הלכה ש\u0003המגביה מציאה לחבירו\u0004 — \u0003קנה חבירו.\u0004","ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 לא דבר זה, אלא \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 שה\u0003רוכב נמי קני\u0004 \u0005[גם כן קונה]\u0006 בבהמה אף שאין זו דרך רגילה של קנין!","\u0003אלא\u0004 נדייק את הדבר \u0003מסיפא\u0004 \u0005[מן הסוף],\u0006 מהקטע האחרון ממש: \u0003בזמן שהן מודים\u0004 זה לזה בטענה \u0003או שיש להן עדים\u0004 כל אחד לטענתו — \u0003חולקין בלא שבועה.\u0004 ונברר: \u0003במאי\u0004 \u0005[במה]\u0006 מדובר כאן? \u0003אי\u0004 \u0005[אם]\u0006 \u0003במקח וממכר,\u0004 וכי \u0003צריכא למימר\u0004 \u0005[צריכה להיאמר]\u0006 שחולקים?\u0005!\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן דווקא \u0003במציאה, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003המגביה מציאה לחבירו\u0004 — \u0003קנה חבירו,\u0004 שבעצם העובדה שהוא מודה שחלקה השני של המציאה שייך לחבירו, מקנה הוא בכך זכות קנין לחבירו.","ומעירים: \u0003ורבא אמר\u0004 \u0005[\u0006יכול \u0005לומר]\u0006 \u0003לך\u0004 כפי שאמר מקודם כי מכאן אין ראיה למסקנה זו, שאפשר גם להסביר את ההלכה על פי הכלל: \u0003מגו דזכי לנפשיה זכי נמי לחבריה\u0004 \u0005[מתוך ש\u0006הוא \u0005זוכה\u0006 בדבר \u0005לעצמו,\u0006 \u0005זוכה גם כן עבור חבירו].\u0006","שנינו במשנה את הדין בענין \u0003היו שנים רוכבין\u0004 על גבי בהמה, או אחד רוכב ואחד מנהיג וכל אחד טוען לבעלות עליה. \u0003אמר רב יוסף, אמר לי רב יהודה:\u0004"],["\u0003שמעית מיניה\u0004 \u0005[שמעתי ממנו]\u0006 מ\u0003מר שמואל תרתי\u0004 \u0005[שתים],\u0006 שתי הלכות בענין \u0003רכוב ומנהיג\u0004 בהמה, \u0003חד\u0004 \u0005[\u0006ב\u0005אחד\u0006 מהם\u0005]\u0006 שמעתי כי \u0003קני\u0004 \u0005[קונה]\u0006 על ידי כך \u0003וחד\u0004 \u0005[ואחד]\u0006 שמעתי ש\u0003לא\u0004 \u0003קני\u0004 \u0005[קונה]\u0006 \u0003ולא ידענא הי מנייהו\u0004 \u0005ואיני יודע איזה מהם]\u0006 אמר לי.","ומבררים תחילה \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הדבר]\u0006 \u0003אילמא\u0004 \u0005[אם תאמר]\u0006 שמדובר ב\u0003רכוב לחודיה\u0004 \u0005[לעצמו],\u0006 לבדו \u0005בלי שותף\u0006 \u0003ומנהיג לחודיה\u0004 \u0005[לעצמו]\u0006 — \u0003מנהיג\u0004 בהמה \u0003לחודיה מי איכא מאן דאמר לא קני\u0004 \u0005[האם יש מי שאומר שאינו קונה]\u0006? והרי דרך קניה מעולה היא זו! \u0003אלא אי איכא למימר דלא קני\u0004 \u0005[אם יש מקום לומר\u0006 על אחד \u0005שאינו קונה]\u0006 \u0003רכוב הוא דאיכא למימר\u0004 \u0005[שיש לומר]\u0006 שלא יקנה על ידי רכיבה בלבד, ואם כן אין כאן מקום לספיקו של רב יהודה.","\u0003אלא\u0004 בענין \u0003רכוב במקום\u0004 שיש אחר \u0003מנהיג אבעיא ליה\u0004 \u0005[נסתפק לו]\u0006 מי מהם קונה. \u0003מאי\u0004 \u0005[מה]\u0006 נאמר? האם נאמר כי \u0003רכוב עדיף דהא תפיס\u0004 \u0005[שהרי תופס]\u0006 ומחזיק \u0003בה,\u0004 בבהמה, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003מנהיג עדיף\u0004 משום \u0003דאזלא מחמתיה\u0004 \u0005[ש\u0006היא \u0005הולכת בגללו]?\u0006","\u0003אמר רב יוסף, אמר לי רב יהודה:\u0004 אמנם אינני זוכר מה אמר לי שמואל, אבל \u0003נחזי אנן\u0004 \u0005[נראה אנחנו]\u0006 ונדון בנושא ונפתור אותו ממה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 אם היה קרון שהיו רתומות לו שתי בהמות כלאיים, כגון שור וחמור, \u0003המנהיג\u0004 את הבהמות \u0003הללו\u0004 \u0003סופג\u0004 (לוקה) \u0003את הארבעים\u0004 מלקות משום שעבר על מצות \"לא תעשה\" שבתורה (\"לא תחרוש בשור ובחמור יחדיו\". דברים כב, י) \u0003ו\u0004כן \u0003היושב בקרון\u0004 \u0003סופג את הארבעים,\u0004 ואילו \u0003ר' מאיר פוטר את היושב בקרון,\u0004 כיון שלדעתו אינו עושה כל מעשה.","\u0003ומדאפיך\u0004 \u0005[ו\u0006מכיון \u0005שהפך]\u0006 \u0003שמואל\u0004 את גירסת משנה זו \u0003ותני\u0004 \u0005[ושנה]\u0006 בה: \u0003וחכמים פוטרין את היושב בקרון,\u0004 נשמע שלדעתו פסק ההלכה הוא שהיושב בקרון אינו כעושה מעשה. \u0003שמע מינה\u0004 \u0005[למד\u0006 מכאן] ש\u0003רכוב לחודיה\u0004 \u0005[לעצמו,\u0006 לבדו\u0005]\u0006 \u0003לא קני\u0004 \u0005[אינו קונה],\u0006 שעצם הרכיבה אינה קרוייה מעשה חשוב כדי שיכול לקנות בו, \u0003וכל שכן רכוב במקום\u0004 שיש אחר \u0003מנהיג.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: הא זמנין סגיאין\u0004 \u0005[הרי פעמים רבות]\u0006 \u0003אמרת לן\u0004 \u0005[לנו]\u0006 בענין הלכה זו: \u0003נחזי אנן\u0004 \u0005[נראה אנחנו]\u0006 \u0003ולא אמרת לן\u0004 \u0005[לנו]\u0006 שהדבר \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יהודה,\u0004 וכיון שחלה רב יוסף ושכח את תלמודו כדיוקו, שמא טעה, וייחס לרב יהודה מה שלא אמר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003אברא\u0004 \u0005[באמת]\u0006 כך אמר ר' יהודה וסימן לדבר כי \u0003ודכרנן נמי דאמרי ליה\u0004 \u0005[וזוכר אני גם כן שאמרתי לו]\u0006 בשעה שאמר לי זאת: \u0003היכי פשיט מר\u0004 \u0005[כיצד פותר אדוני]\u0006 דין \u0003רכוב מ\u0004דין של \u0003יושב?\u0004 הרי \u0003יושב לא תפיס\u0004 \u0005[אינו תופס,\u0006 מחזיק\u0005]\u0006 \u0003במוסירה\u0004 של הבהמה, ואילו \u0003רכוב תפיס\u0004 \u0005[תופס]\u0006 \u0003במוסירה! ואמר לי רב יהודה\u0004 על כך: \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 שהמחזיק ב\u0003מוסירה\u0004 עצמו \u0003לא קני\u0004 \u0005[אינו קונה]\u0006 לכל דבר. ולכן אין הבדל בין רוכב ויושב בקרון.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שחילופי הדברים בין אביי ורב יוסף היו בנוסח אחר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף\u0004 עצמו: \u0003היכי פשיט מר\u0004 \u0005[איך פותר אדוני]\u0006 \u0003רכוב מיושב?\u0004 הרי \u0003יושב לא תפיס\u0004 \u0005[אינו תופס]\u0006 \u0003במוסירה,\u0004 ואילו \u0003רכוב תפיס\u0004 \u0005[תופס]\u0006 \u0003במוסירה! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי תנא\u0004 \u0005[כך שנה]\u0006 החכם \u0003אידי\u0004 בברייתא: החזקת ה\u0003מוסירה לא קני\u0004 \u0005[אינה קונה].\u0006","\u0003אתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 בדומה לזה, ש\u0003אמר ר' חלבו אמר רב הונא:\u0004 החזקת \u0003ה\u0004\u0003מוסירה\u0004 לענין קנין, אם היה זה בקבלת קנין כאשר קיבל את הבהמה \u0003מחבירו\u0004 \u0005—\u0006 \u0003קנה.\u0004 ואולם \u0003במציאה ובנכסי הגר\u0004 שמת ללא יורשים, ונכסיו מופקרים לכל, ורוצה לקנות לעצמו בהמה מאלה \u0005—\u0006 \u0003לא קני\u0004 \u0005[אינו קונה בכך].\u0006","ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003לשון מוסירה? אמר רבא:\u0004 החכם \u0003אידי אסברא\u0004 \u0005[הסביר אותה]\u0006 \u0003לי: כאדם המוסר דבר לחבירו.\u0004 ומשום כך, \u0003בשלמא\u0004 \u0005[נניח]\u0006 כי המחזיק במוסירה שניתנה לו \u0003מחבירו קני\u0004 \u0005[קונה]\u0006 כיון \u0003דקא מסר ליה חבריה\u0004 \u0005[שמוסר לו חבירו]\u0006 את הבהמה, \u0003אלא במציאה ובנכסי הגר מאן קא מסר ליה דליקני\u0004 \u0005[מי מוסר לו שיקנה]?\u0006 ובעצם ההחזקה במוסירה לא קנה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו במשנתנו: \u0003היו שנים רוכבים על גבי בהמה\u0004 או שהיה אחד רוכב ואחד מנהיג \u0003וכו'.\u0004 ונברר: \u0003מני\u0004 \u0005[\u0006כדעת \u0005מי היא]\u0006 משנה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי שיטת \u0003ר' מאיר\u0004 היא \u0005—\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי לדעתו אפילו \u0003יושב קני\u0004 \u0005[קונה]\u0006 שהרי היושב בקרון כלאיים חייב, \u0003רכוב מיבעי\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שקונה?! \u0003אלא לאו רבנן\u0004 \u0005[\u0006האם \u0005לא\u0006 כדעת \u0005חכמים\u0006 היא\u0005]\u0006 \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003רכוב קני\u0004 \u0005[קונה],\u0006 שהרי זכה בחלקו בבהמה, ודוחים:","\u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003במנהיג\u0004 את הבהמה \u0003ברגליו,\u0004 שלא רק רכב עליה, אלא שהוא מוליך אותה על ידי לחץ או בעיטה ברגליו. ושואלים: \u0003אי הכי היינו\u0004 \u0005[אם כך זהו]\u0006 איפוא \u0003מנהיג,\u0004 שהרי אף זה מנהיג את הבהמה לפי דרכו! ומשיבים: אכן כן הוא, שאף הוא בכלל מנהיג, אלא ש\u0003תרי גווני\u0004 \u0005[שני גוונים,\u0006 סוגים\u0005]\u0006 של \u0003מנהיג\u0004 שנה, וטעם הדבר — \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003רכוב עדיף דהא\u0004 \u0005[שהרי]\u0006 הוא גם \u0003מנהיג ותפיס\u0004 \u0005[ו\u0006גם \u0005תופס\u0006 בה\u0005],\u0006 ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין לו עדיפות על מנהיג סתם.","\u0003תא שמע\u0004 \u0005[בו\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ששנינו בברייתא: \u0003שנים שהיו מושכים\u0004 יחד \u0003בגמל,\u0004 או \u0003מנהיגים\u0004 יחד \u0003בחמור, או שהיה אחד מושך ואחד מנהיג,\u0004"],["\u0003במדה זאת,\u0004 כלומר, באופן זה \u0005—\u0006 \u0003קנו. ר' יהודה אומר: לעולם לא קנה עד שתהא משיכה\u0004 דווקא \u0003בגמל והנהגה בחמור,\u0004 שזו היא הדרך בה הם מובלים כדרכם.","\u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 במשנה: \u0003או שהיה אחד מושך ואחד מנהיג,\u0004 ומכאן נוכל לדייק: \u0003מושך ומנהיג\u0004 \u0005—\u0006 \u0003אין\u0004 \u0005[כן]\u0006 קנו. \u0003אבל רכוב\u0004 \u0005—\u0006 \u0003לא\u0004 קנה!","ודוחים: אין הכרח לומר כן, ו\u0003הוא הדין\u0004 ש\u0003אפילו רכוב\u0004 קנה \u0003והא דקתני\u0004 \u0005[וזו ששנה]\u0006 \u0003מושך ומנהיג\u0004 — לא בא הדבר אלא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 שאין קנין בבהמה אלא \u0003עד שתהא משיכה בגמל והנהגה בחמור, ו\u0004על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 התנא הראשון ש\u0003אפילו איפכא נמי קני\u0004 \u0005[להיפך גם כן קנה],\u0006","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 היתה הכוונה, אם כן \u0003ליערבינהו ולתנינהו\u0004 \u0005[שיערבם וישנה אותם\u0006 יחד\u0005]\u0006 באופן זה: \u0003שנים שהיו מושכין ומנהיגין בין בגמל בין בחמור,\u0004 ומאחר ולא שנה כך, משמע שבכל זאת בא הדבר למעט!","ומשיבים: אכן בא הדבר למעט, כי \u0003איכא חד צד\u0004 \u0005[יש צד אחד],\u0006 אפשרות אחת מבין אלה שבה \u0003לא קני\u0004 \u0005[קנה]\u0006 ולא היה ברור מה הוא; \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 \u0003משיכה בחמור,\u0004 לפי שאין דרכו של חמור ללכת במשיכה כלל, \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 \u0003הנהגה בגמל\u0004 שאינה כדרכו. זו היתה נוסחה אחת, ויש גם נוסחה אחרת לכל אותו נושא.","\u0003ואית דמותיב מסיפא\u0004 \u0005[ויש שמקשה\u0006 קושיה זו \u0005מסופה]\u0006 של המשנה. ששנינו שם: \u0003\"במדה זו קנה\",\u0004 ונדייק: \u0003\"במדה זו\"\u0004 שאמרו \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 הוא בא? \u0003לאו למעוטי\u0004 \u0005[האם לא\u0006 בא \u0005למעט]\u0006 \u0003רכוב?!\u0004 ודוחים: \u0003לא, למעוטי איפכא\u0004 \u0005[למעט\u0006 את \u0005ההיפך]\u0006 שהמנהיג בגמל ומושך בחמור לא קנה.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003היינו\u0004 \u0005[\u0006הרי \u0005זוהי]\u0006 בדיוק שיטת \u0003ר' יהודה,\u0004 ואין איפוא כל מחלוקת ביניהם! ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה לגבי \u0003צד אחד\u0004 ש\u0003לא קנה,\u0004 שחכמים סבורים שרק באחד מן המקרים לא קנה; \u0003אית דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003משיכה בחמור\u0004 לא קנה בה, \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 כי \u0003הנהגה בגמל\u0004 לא קנה, אבל במקרה האחר קנה, ובזה חלוקים הם עם ר' יהודה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא: \u0003אחד רכוב\u0004 על גבי ה\u0003חמור ואחד תפוס\u0004 \u0005[מחזיק]\u0006 \u0003במוסירה\u0004 — \u0003זה,\u0004 הרכוב, קנה את ה\u0003חמור, וזה,\u0004 המחזיק במוסירה, \u0003קנה\u0004 את ה\u0003מוסירה.\u0004 ו\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003רכוב קני\u0004 \u0005[קנה]!\u0006","ודוחים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר לא ברכוב סתם, אלא \u0003במנהיג ברגליו.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שהרכוב קונה קנין מעולה, אם כן \u0003נקני נמי\u0004 \u0005[שיקנה גם כן]\u0006 ה\u0003רכוב\u0004 זכות \u0003במוסירה,\u0004 ואם לא קנה כל זכות במוסירה משמע שלא קנה אף את החמור כקנין גמור! ודוחים: אכן, \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 \u0003זה קנה חמור וחצי מוסירה, וזה קנה חצי מוסירה.\u0004","ושואלים שוב: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003רכוב קני\u0004 \u0005[קונה]\u0006 חצי מוסירה משום \u0003דקמגבה ליה\u0004 \u0005[שמגביה לו,\u0006 עבורו\u0005]\u0006 \u0003בן דעת,\u0004 שהרי מחזיק המוסירה מגביה אותה ומקנה גם לרכוב, \u0003אלא תפוס במוסירה במאי קני\u0004 \u0005[במה\u0006 הוא \u0005קונה]?\u0006 — הלא חלקה האחר של המוסרה תלוי בחמור, וכיוון שאת החמור עצמו אינו קונה, במה קנה מחזיק המוסירה?","ומתקנים: \u0003אימא\u0004 \u0005[אמור]\u0006 כך: \u0003זה,\u0004 הרכוב \u0003קנה חמור וכוליה\u0004 \u0005[וכל]\u0006 או את רוב ה\u0003מוסירה,\u0004 \u0003וזה,\u0004 מחזיק המוסירה, \u0003קני מה שתפוס בידו\u0004 ממש.","ומקשים: \u0003האי מאי\u0004 \u0005[זה מהו]?!\u0006 כלומר, מה מקום להסבר זה? \u0003אם תימצי לומר\u0004 \u0005[תמצא\u0006 מקום \u0005לומר]\u0006 כי \u0003המגביה מציאה לחבירו קנה חבירו\u0004 — \u0003הני מילי היכא דקא מגבה ליה אדעתא דחבריה\u0004 \u0005[דברים אלה\u0006 אמורים דווקא באופן \u0005שמגביה אותה על דעת חבירו]\u0006 שחבירו יקנה, ואולם \u0003האי\u0004 \u0005[זה]\u0006 את המוסירה \u0003אדעתא דידיה קא מגבה ליה\u0004 \u0005[על דעת עצמו הוא מגביה אותה]\u0006 ואם \u0003איהו\u0004 \u0005[הוא]\u0006 עצמו \u0003לא קני\u0004 \u0005[קונה]\u0006 אותה, האם \u0003לאחריני מקני\u0004 \u0005[לאחרים\u0006 הוא יכול \u0005להקנות\u0006 אותה\u0005]?!\u0006","\u0003אמר רב אשי:\u0004 כך צריך לומר, \u0003זה,\u0004 הרכוב והמנהיג, \u0003קנה חמור ובית פגיה\u0004 (החלק הקשור בראשו של החמור ממש), \u0003וזה,\u0004 המחזיק במוסירה, \u0003קנה מה שתפוס בידו\u0004 ממש, \u0003והשאר,\u0004 מה שבין זה וזה — \u0003לא קנה לא זה ולא זה,\u0004 לפי ששניהם לא עשו כל מעשה של זכייה.","\u0003ר' אבהו אמר: לעולם\u0004 תאמר \u0003כדקתני\u0004 \u0005[כפי ששנינו]\u0006 ובלא תיקונים, והטעם מדוע זכה במוסירה — \u0003הואיל ויכול לנתקה\u0004 (למושכה) \u0003ולהביאה אצלו,\u0004 וכיון שיכול למשכה אליו, אף שלא הגביהה הרי היא כשלו.","ומעירים: \u0003והא\u0004 \u0005[וזו]\u0006 שאמר \u0003ר' אבהו ברותא\u0004 \u0005[חיצונית]\u0006 \u0003היא,\u0004 כלומר, אינה סברה מבוססת ואינה ראויה להכנס לדיון בבית המדרש. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 לדחות את ר' אבהו, אם כן \u0003טלית שהיא מונחת חציה על גבי קרקע וחציה על גבי עמוד, ובא אחד והגביה\u0004 את \u0003חציה מעל גבי קרקע ובא אחר והגביה\u0004 את \u0003חציה\u0004 האחר \u0003מעל גבי עמוד, הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר \u0003דקמא קני ובתרא\u0004 \u0005[שהראשון קנה\u0006 את הטלית לרשותו, \u0005והשני]\u0006 \u0003לא קני\u0004 \u0005[קנה]\u0006 \u0003הואיל ויכול\u0004 היה הראשון \u0003לנתק\u0004 אותה מעל העמוד \u0003ולהביא\u0004 את כולה \u0003אצלו?!\u0004 הלא אין הדבר כן! אלא יש לומר כי \u0003הא\u0004 \u0005[זו]\u0006 של \u0003ר' אבהו ברותא\u0004 \u0005[חיצונית]\u0006 \u0003היא\u0004 ואין להתחשב בה. ואם כן, עדיין לא נפתרה שאלתנו ביחס לרכוב.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בברייתא אחרת ש\u0003ר' אליעזר אומר: רכוב בשדה ומנהיג בעיר\u0004 — \u0003קנה,\u0004 ומשמע אם כן שרכוב קנה! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר שהיה הרכוב \u0003מנהיג\u0004 את הבהמה \u0003ברגליו.\u0004 ואומרים: \u0003אי הכי היינו\u0004 \u0005[אם כך\u0006 הוא, אם כן \u0005זהו]\u0006 \u0003מנהיג!\u0004 ודוחים, אין זו קושיה, כי ב\u0003תרי גווני\u0004 \u0005[\u0006\u0005שני גוונים,\u0006 סוגים\u0005]\u0006 של \u0003מנהיג\u0004 מדובר.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הדבר שהוא רוכב ובאותו זמן גם מנהיג, אם כן \u0003רכוב בעיר מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא קני\u0004 \u0005[קונה]?!\u0006 \u0003אמר רב כהנא: לפי שאין דרכם של בני אדם לרכוב בעיר,\u0004 שהמקום צפוף ואין אנשים רגילים לרכב, ודרך אדם להנהיג בלבד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא: אלא מעתה,\u0004 אם אתה אומר שדבר שאינו דרכם של בני אדם לקנות אין נעשה בו קנין, אם \u0003הגביה\u0004 בעצמו \u0003ארנקי\u0004 \u0005[ארנק,\u0006 כיס של מעות\u0005],\u0006 של מציאה \u0003בשבת, ש\u0004הרי \u0003אין דרכם של בני אדם להגביה ארנקי\u0004 \u0005[ארנק]\u0006 \u0003בשבת\u0004 מחמת איסור מוקצה, \u0003הכי נמי דלא קני\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שאינו קונה]\u0006 את הארנק לרשותו? \u0003אלא מאי\u0004 \u0005[מה]\u0006 אומר אתה — \u0003מאי דעבד\u0004 \u0005[מה שעשה]\u0006 — \u0003עבד וקני\u0004 \u0005[עשה, וקנה],\u0006 \u0003הכא נמי, מאי דעבד\u0004 \u0005[כאן גם כן מה שעשה]\u0006 — \u0003עבד וקני\u0004 \u0005[עשה, וקנה].\u0006","\u0003אלא,\u0004 יש לומר כי כאן אין מדברים במציאה, שאותה אפשר לקנות באופנים שונים, אלא \u0003במקח וממכר עסקינן\u0004 \u0005[עוסקים אנו]\u0006 וכגון ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 המוכר: \u0003קני\u0004 \u0005[קנה]\u0006 \u0003כדרך שבני אדם קונין,\u0004 והשאלה היא מהי דרך הקנין הראויה לכל דבר ודבר."],["\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003רשות הרבים הוא\u0004 — \u0003קני\u0004 \u0005[קנה]\u0006 הרוכב, שדרכו של אדם לרכב שם בעיר, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אדם חשוב הוא\u0004 שדרכו להיות תמיד רכוב ואין דרכו להנהיג — \u0003קני\u0004 \u0005[קנה]\u0006 אפילו בסימטא \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אשה היא\u0004 שאין דרכה להלך אחרי החמור — \u0003קניא\u0004 \u0005[קנתה],\u0006 \u0003ואי איניש זילא\u0004 \u0005[ואם אדם בזוי]\u0006 \u0003הוא\u0004 הרוכב, שדרכו לרכב אף במקומות שאין אנשים רוכבים בהם — אף הוא \u0003קני\u0004 \u0005[קנה].\u0006","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אלעזר: האומר לחבירו \"משוך בהמה זו\u0004 על מנת \u0003לקנות\u0004 את ה\u0003כלים שעליה\",\u0004 שאותם הוא מוכר כעת, \u0003מהו\u0004 הדין?","ותוהים על הלשון \u0003\"לקנות\", מי\u0004 \u0005[האם]\u0006 \u0003אמר ליה \"קני\u0004 \u0005[לו קנה]\u0006 את הכלים \u0003\"?\u0004 ואם לא פירש לו שיקנה כלים אלא אמר בלשון לא ברורה \"לקנות כלים\" לא אמר כלום. \u0003אלא\u0004 יש לתקן ולומר שהשאלה היתה אם אמר לו: \u0003\"משוך בהמה זו וקנה\u0004 על ידי כך \u0003כלים שעליה\" מהו?\u0004 והבעיה העקרונית היא: \u0003מי מהניא\u0004 \u0005[האם הועילה]\u0006 ה\u0003משיכה\u0004 של ה\u0003בהמה לאקנויי\u0004 \u0005[להקנות]\u0006 את ה\u0003כלים\u0004 שעליה, \u0003או לא?\u0004","\u0003אמר רבא: אי\u0004 \u0005[אם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"קני\u0004 \u0005[קנה]\u0006 \u0003בהמה וקני\u0004 \u0005[וקנה]\u0006 \u0003כלים\u0004 שעליה\" — \u0003מי קני\u0004 \u0005[האם קונה\u0006 הוא\u0005]\u0006 את ה\u0003כלים?\u0004 והרי אף אם קנה את הבהמה, והבהמה היא רשותו כחצר, ואולם גם אז את הכלים על גבי בהמתו לא קנה כיון ש\u0003חצר מהלכת היא, וחצר מהלכת לא קנה.\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שמדובר באופן \u0003כש\u0004אחר שעקרה רגליה והלכה (ובכך קנה אותה) \u0003עמדה\u0004 ואז נעשה מעשה הקנין לגבי הכלים, \u0003והא\u0004 \u0005[והרי]\u0006 כלל הוא: \u0003כל שאילו\u0004 היה \u0003מהלך לא קנה\u0004 — אף אם היה \u0003עומד ויושב לא קנה!\u0004","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא שיש דרך שיכול לקנות כלים על גבי בהמה — אם היתה הבהמה \u0003כפותה,\u0004 וכיון שקנה את הבהמה הרי היא כחצרו ויכול לקנות אגב הבהמה גם את הכלים שעליה.","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרבא: אלא מעתה,\u0004 לפי פסק זה, אם \u0003היה\u0004 אדם \u0003מהלך בספינה\u0004 שלו \u0003וקפצו דגים ונפלו לתוך הספינה הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003חצר מהלכת היא ולא קני\u0004 \u0005[ואינו קונה]\u0006 את הדגים שיהיו ברשותו?! \u0003אמר ליה\u0004 \u0005[לו,\u0006 להם\u0005]:\u0006 ספינה אינה חצר מהלכת, כי ה\u0003ספינה\u0004 עצמה \u0003מינח נייחא\u0004 \u0005[נחה\u0006 היא\u0005],\u0006 \u0003ומיא\u0004 \u0005[והמים]\u0006 \u0003הוא דקא ממטו לה\u0004 \u0005[שמביאים אותה]\u0006 ולכן אין דינה כחצר המהלכת.","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: אלא מעתה\u0004 שחצר המהלכת אינה קונה, אם כן, אם \u0003היתה\u0004 אשה \u0003מהלכת ברשות הרבים וזרק לה\u0004 בעלה \u0003גט לתוך חיקה או לתוך קלתה\u0004 (הסל שעל ראשה) \u0003הכא נמי דלא מגרשה\u0004 \u0005[כאן גם כן תאמר שאינה מתגרשת\u0006 בכך\u0005]\u0006 כיון שהיא מהלכת?! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003קלתה מינח נייחא\u0004 \u0005[הסל שלה נח]\u0006 \u0003ואיהי דקא מסגיא מתותה\u0004 \u0005[והיא שמהלכת מתחתיו]\u0006 \u0003,\u0004 ולכן הסל נחשב כחצר קבועה, וכל מה שנופל בו נקנה לבעליו.","\u0003היה\u0004 אדם \u0003רוכב על גבי בהמה וראה את המציאה ואמר לחבירו\u0004 שהיה מהלך לידו \u0003\"תנה לי\". נטלה\u0004 החבר \u0003ואמר: \"אני זכיתי בה\"\u0004 — \u0003זכה בה\u0004 על ידי הרמתה, אף שלא ראה אותה ראשונה. ו\u0003אם משנתנה לו\u0004 לחבירו הרוכב, \u0003אמר\u0004 המהלך \u0003\"אני זכיתי בה תחילה\"\u0004 — \u0003לא אמר כלום.\u0004 שאמירה בלבד אינה יוצרת זכות קניין, וכיון שנראה מדבריו שלא התכוון לקנות את המציאה בשעת הגבהה — שוב אינו יכול לקנותה.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 בהלכות פאה: \u0003מי שליקט את הפאה\u0004 שמשאירים בשולי השדה עבור העניים, \u0003ואמר: \"הרי זו,\u0004 מה שלקטתי, שייך \u0003לפלוני עני\"\u0004 — \u0003ר' אליעזר אומר: זכה לו\u0004 על ידי כך, ושייך הנלקט לעני. \u0003וחכמים אומרים:\u0004 לא זכה לו, אלא \u0003יתננה לעני הנמצא ראשון,\u0004 שכל עני שיקבל ממנו פאה זו — שלו היא.","\u0003אמר עולא אמר ר' יהושע בן לוי: מחלוקת\u0004 זו היא \u0003מעשיר לעני,\u0004 שלוקח הפאה הוא עצמו עשיר שאינו זכאי ללקוט פאה, ורוצה לזכות בה עבור העני, ש","\u0003ר' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003מגו דאי בעי מפקר נכסיה והוי\u0004 \u0005[מתוך שאילו\u0006 היה \u0005רוצה\u0006 היה \u0005מפקיר\u0006 את \u0005נכסיו והיה\u0006 נעשה\u0005]\u0006 \u0003עני וחזי ליה\u0004 \u0005[וראוייה לו]\u0006 הפאה — \u0003השתא נמי חזי ליה\u0004 \u0005[עכשיו גם כן ראוייה לו]\u0006 בעודו עשיר. \u0003ומגו דזכי לנפשיה, זכי נמי לחבריה\u0004 \u0005[ומתוך שזוכה לעצמו, זוכה גם כן לחברו].\u0006 \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 ש\u0003חד מגו\u0004 \u0005[\"מתוך\" אחד]\u0006 — \u0003אמרינן\u0004 \u0005[אומרים אנו],\u0006 ואולם \u0003תרי מגו\u0004 \u0005[שני \"מתוך\"]\u0006 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים].\u0006","\u0003אבל מעני לעני,\u0004 אם המלקט היה בעצמו עני \u0003דברי הכל זכה לו\u0004 לחבירו, \u0003דמגו דזכי לנפשיה זכי נמי לחבריה\u0004 \u0005[שמתוך שזוכה\u0006 \u0005לעצמו זוכה גם כן עבור חבירו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לעולא: ולימא מר\u0004 \u0005[ושיאמר אדוני]:\u0006 לא כך, אלא אף \u0003מעני לעני מחלוקת,\u0004 וראיה לדבר: \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003מציאה הכל\u0004 נחשבים כ\u0003עניים אצלה,\u0004 כלומר, הכל יש להם זכות לקנות במציאה, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003היה רוכב על גבי בהמה וראה את המציאה ואמר לחבירו \"תנה לי\", נטלה ואמר \"אני זכיתי בה\"\u0004 — \u0003זכה בה.\u0004","ומעתה \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי \u0003מעני לעני מחלוקת\u0004"],["\u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כדעת \u0005מי\u0006 היא\u0005]\u0006 — כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 שאין אדם זוכה לחבירו באופן כזה. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שדווקא \u0003בעשיר ועני מחלוקת, אבל מעני לעני דברי הכל זכה לו, הא מני\u0004 \u0005[\u0006משנתנו \u0005זו\u0006 כדעת \u0005מי\u0006 \u0005היא\u0006\u0005]?\u0006 \u0003לא\u0004 שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003ולא\u0004 שיטת \u0003ר' אליעזר\u0004 היא!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 יש לפרשה כגון \u0003דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]\u0006 \u0003\"תחילה\".\u0004 כלומר, המגביה אומר: אני לא התכוונתי כלל להגביה את המציאה עבורך, אלא מתחילה עבור עצמי נתכוונתי ולכן זכה לעצמו ולא לחבירו.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר לעצם פירוש המשנה, \u0003דקתני סיפא\u0004 \u0005[ששנה בסופה]\u0006 \u0003אם משנתנה לו אמר אני זכיתי בה תחילה\u0004 — \u0003לא אמר כלום. \"תחילה\"\u0004 שאמר \u0003בסיפא\u0004 \u0005[בסוף]\u0006 \u0003למה לי?\u0004 \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 כי \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא אמר \"תחילה\"\u0004 במפורש, ברור כי \u0003\"תחילה\" קאמר\u0004 \u0005[אמר],\u0006 שהתכוון לומר שעוד קודם לכן הוא זוכה בה. \u0003אלא לאו הא קא משמע לן\u0004 \u0005[האם לא\u0006 דבר \u0005זה השמיע לנו],\u0006 כי \u0003רישא\u0004 \u0005[בתחילת\u0006 המשנה\u0005]\u0006 כוונתו ש\u0003אמר\u0004 \u0003\"\u0004אני זכיתי בה \u0003תחילה\".\u0004","ומעירים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 רב נחמן, סבור כי \u0003תנא סיפא לגלויי רישא\u0004 \u0005[שנה בסוף\u0006 המשנה \u0005לגלות,\u0006 לפרש את טעמו של הדבר \u0005בראשה],\u0006 ויש לומר כי \u0003סיפא\u0004 \u0005[בסוף]\u0006 מדובר באופן ש\u0003אמר \"תחילה\",\u0004 ו\u0003רישא\u0004 \u0005[בראש,\u0006 בהתחלה \u0005]\u0006 מדובר באופן ש\u0003לא אמר \"תחילה\",\u0004 שזוכה במציאה אפילו בלא לומר \"תחילה\". שלשיטת רב נחמן יש לומר שלא זכה החבר הרוכב כלל.","זה היה אופן אחר של הסבר, ואילו \u0003רב נחמן ורב חסדא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 והסכימו להלכה אחת: \u0003המגביה מציאה לחבירו\u0004 — \u0003לא קנה חבירו.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — משום שאפשר לדמות זאת לבעיה הלכתית אחרת ולומר כי המוצא \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003תופס\u0004 דבר עבור \u0003בעל חוב\u0004 אחד, \u0003במקום\u0004 שהחייב הזה \u0003חב\u0004 \u0005[חייב]\u0006 גם \u0003לאחרים, והתופס לבעל חוב במקום שחב\u0004 \u0005[שחייב]\u0006 \u0003לאחרים\u0004 — \u0003לא קנה.\u0004 שאילו היה בעל החוב עצמו תופס כדי חובו — יש לו קניין בדבר, אבל אחר שאינו שליח המלוה, אינו יכול לעשות פעולה שהיא אמנם זכות לאחד, אבל חובה עבור אחרים. וכיון שמציאה הכל זכאים בה — אין אחד יכול לקפח את זכותם של כל האחרים עבור מי שלא שלחו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו: \u0003מציאת פועל\u0004 — שייכת \u0003לעצמו\u0004 ולא לבעל הבית שהוא עובד עבורו באותו זמן.","\u0003במה דברים אמורים\u0004 — \u0003בזמן שאמר לו בעל הבית\u0004 לעשות מלאכה מסויימת, וכגון שאמר לו \u0003\"נכש עמי היום\",\u0004 או שאמר לו \u0003\"עדור\u0004 \u0003עמי היום\",\u0004 ואז מציאת פועל לעצמו, כיון שפירט לו את מהות המלאכה שהוא מצפה ממנו לעשות עבורו, ואין בכלל אלו זכייה עבורו במציאה. \u0003אבל\u0004 אם \u0003אמר לו \"עשה עמי מלאכה היום\"\u0004 בלא לפרט את מהות המלאכה — \u0003מציאתו של בעל הבית הוא,\u0004 שהרי אף זה בתוך המלאכה הכללית שעושה. ומכל מקום למדנו מכאן שיכול אדם (פועל) לזכות במציאה לאחר (לבעל הבית)!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: מכאן אין להקשות, כי \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003פועל\u0004 ש\u0003ידו כיד בעל הבית הוא,\u0004 שכיון שהוא עובד בשכירות עבור בעל הבית הרי בתוך זמן העבודה הוא נחשב כשליחו של בעל הבית.","ומקשים, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: פועל יכול לחזור בו\u0004 מהתחייבותו לעבוד \u0003אפילו בחצי היום\u0004, והרי שאף תוך כדי עבודה אינו נחשב כידו של בעל הבית!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כל כמה\u0004 (כל עוד) ש\u0003לא הדר ביה\u0004 \u0005[חזר בו]\u0006 מהיותו פועל, ידו \u0003כיד בעל הבית הוא. כי הדר ביה\u0004 \u0005[כאשר חוזר\u0006 הוא \u0005בו]\u0006 \u0003טעמא אחרינא\u0004 \u0005[מטעם אחר]\u0006 \u0003הוא,\u0004 לא משום שאין לו כל קשר התחייבות לבעל הבית, אלא משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"כי לי בני ישראל עבדים\u0004 עבדי הם אשר הוצאתי אותם מארץ מצרים\u0003\"\u0004 (ויקרא כה, נה), ומדייקים: \u0003\"עבדי הם\"\u0004 — \u0003ולא עבדים לעבדים.\u0004 שאין תוקף לחוזה שאדם מישראל נעשה בו משועבד כעבד ואינו יכול להתירו, ולכן יכול הוא לחזור בו מתי שרוצה. אבל לגבי דיני שליחות כל עוד הוא פועל הרי הוא כשליח בעל הבית.","שיטה אחרת \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: המגביה מציאה לחבירו\u0004 — \u0003קנה חבירו. ואם תאמר משנתינו\u0004 שלכאורה נשמע ממנה אחרת — שם מדובר באופן ש\u0003אמר\u0004 הרוכב \u0003\"תנה לי\", ולא אמר \"זכה לי\",\u0004 שכיון שאמר \"תן לי\" לא זכה אלא כאשר מגיעה המציאה לידו, אבל אם אמר לו \"זכה לי\" — זכה לו מיד כשהרים אותה.","\u0003ראה\u0004 אדם \u0003את המציאה ונפל עליה,\u0004 שהתכוון לזכות בה, אלא שלא עשה בה דרך מדרכי הקנין \u0003ובא אחר והחזיק בה\u0004 — \u0003זה שהחזיק בה זכה בה,\u0004 לפי שהוא קנה אותה כדינה.","\u0003אמר ריש לקיש משום\u0004 (בשם) \u0003אבא כהן ברדלא: ארבע אמות של אדם קונות לו בכל מקום.\u0004 ששטח של ארבע אמות מסביב לו נחשב כעין חצר שלו וכל דבר הפקר הנמצא שם נקנה לו. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003תקינו רבנן\u0004 \u0005[התקינו חכמים]\u0006 ש\u0003לא אתי לאנצויי\u0004 \u0005[יבואו\u0006 אנשים \u0005להתקוטט]\u0006 על כך. \u0003אמר אביי: מותיב\u0004 \u0005[מקשה]\u0006 היה על כך \u0003ר' חייא בר יוסף\u0004 מדין \u0003פיאה. אמר רבא: מותיב\u0004 \u0005[מקשה]\u0006 היה על כך \u0003ר' יעקב בר אידי\u0004 מדיני \u0003נזיקין.\u0004","ומפרטים, \u0003אמר אביי: מותיב\u0004 \u0005[מקשה]\u0006 היה על כך \u0003ר' חייא בר יוסף\u0004 מדין \u0003פיאה,\u0004 ששנינו: \u0003נטל\u0004 אדם \u0003מקצת פיאה וזרק על השאר\u0004 על מנת לקנות בכך את שאר הפאה — \u0003אין לו בה כלום.\u0004 וכן אם \u0003נפל לו עליה,\u0004 על הפיאה, או \u0003פרס טליתו עליה\u0004 — \u0003מעבירים אותו הימנה\u0004 (ממנה) כיון שלא קנה בדרך מדרכי הקנין. \u0003וכן בעומר\u0004 ה\u0003שכחה\u0004 אינו זוכה באופן זה.","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003ארבע אמות של אדם קונות לו בכל מקום,\u0004 אם כן \u0003נקנו ליה\u0004 \u0005[שיקנו לו]\u0006 \u0003ארבע אמות דידיה\u0004 \u0005[שלו]\u0006 והרי כאן רואים שלא קנה!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — באופן ש\u0003לא אמר \"אקני\"\u0004 \u0005[אקנה]\u0006 על ידי כך, אלא עשה מעשה בלי לגלות את כוונתו.","ושואלים: \u0003ואי תקון רבנן\u0004 \u0005[ואם\u0006 היו \u0005מתקנים חכמים]\u0006 שארבע אמות קונות \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא אמר מאי הוי\u0004 \u0005[מה היה]?\u0006 הלא צריך היה לקנות לפי תקנת חכמים אף בלא שיביע דעתו שזה רצונו!","ומשיבים: כאן הדבר שונה כי \u0003כיון\u0004 ש\u0003נפל\u0004 עליה ולא הסתפק באמירה, בכך \u0003גלי דעתיה\u0004 \u0005[גילה\u0006 את \u0005דעתו]\u0006 ש\u0003בנפילה ניחא ליה דנקני\u0004 \u0005[נוח לו לקנות]\u0006 ו\u0003בארבע אמות לא ניחא ליה דנקני\u0004 \u0005[נוח לו לקנות],\u0006 וכיון שויתר על כוח הקניה מצד התקנה, ואילו הנפילה עצמה אינה מקנה לו זכות כלשהי — על כן אין לו קנין כלל."],["\u0003רב פפא אמר\u0004 הסבר אחר: \u0003כי תקינו ליה רבנן\u0004 \u0005[כאשר תקנו לו חכמים]\u0006 שיקנו לו \u0003ארבע אמות\u0004 — הרי זה \u0003בעלמא\u0004 \u0005[בכלל],\u0006 במקום הפקר, ואלו \u0003בשדה\u0004 של \u0003בעל הבית — לא תקינו ליה רבנן\u0004 \u0005[תקנו לו חכמים].\u0006 \u0003ואף על גב דזכה ליה רחמנא בגוה\u0004 \u0005[שאף על פי שזיכתה לו התורה\u0006 זכות מסויימת \u0005בה],\u0006 בשדה בעל הבית בזמן חלוקת פאה, מכל מקום \u0003כי זכה ליה רחמנא\u0004 \u0005[כאשר זיכתה לו התורה]\u0006 הרי זה דווקא \u0003להלוכי בה ולנקוטי\u0004 \u0005[ללכת בה ולקחת]\u0006 את ה\u0003פיאה,\u0004 ואולם \u0003למיהוי\u0004 \u0005[שתהא]\u0006 \u0003חצירו\u0004 — \u0003לא זכה ליה רחמנא\u0004 \u0005[זכתה לו התורה],\u0006 ואין אפוא קושיה לדברי ריש לקיש מדין פיאה.","כבר אמרנו ש\u0003אמר רבא\u0004 ש\u0003מותיב\u0004 \u0005[מקשה]\u0006 היה \u0003ר' יעקב בר אידי\u0004 על הלכה זו מדיני \u0003נזיקין,\u0004 מהמשנה שלנו, ששנינו: \u0003ראה את המציאה ונפל לו עליה ובא אחר והחזיק בה\u0004 — \u0003זה שהחזיק בה זכה בה. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003ארבע אמות של אדם קונות לו בכל מקום\u0004 — אם כן \u0003נקנו ליה\u0004 \u0005[שיקנו לו]\u0006 \u0003ארבע אמות דידיה\u0004 \u0005[שלו]!\u0006","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים\u0006 — כגון באופן ש\u0003לא אמר \"אקני\"\u0004 \u0005[\"אקנה\"].\u0006 ומקשים: \u0003ואי תקון רבנן\u0004 \u0005[ואם תקנו חכמים]\u0006 שאדם זוכה בתוך ארבע אמות \u0003כי\u0004 \u0003לא אמר מאי הוי\u0004 \u0005[כאשר אינו אומר, מה היה]\u0006 והרי סוף סוף שלו הן! ומשיבים: \u0003כיון\u0004 ש\u0003נפל עליה\u0004 בכך \u0003גלי דעתיה\u0004 \u0005[גילה\u0006 את \u0005דעתו]\u0006 ש\u0003בנפילה ניחא ליה דנקני\u0004 \u0005[נוח לו לקנות]\u0006 ואילו \u0003בארבע אמות לא ניחא ליה דנקני\u0004 \u0005[נוח לו לקנות],\u0006 ומשום כך לא קנה כלל.","\u0003רב ששת אמר\u0004 הבדל אחר: \u0003כי תקינו רבנן\u0004 \u0005[כאשר תקנו חכמים]\u0006 תקנה זו של ארבע אמות הרי זו \u0003ב\u0004מקום כגון \u0003סמטא\u0004 (רחוב צר) ש\u0003לא דחקי\u0004 \u0005[דוחקים]\u0006 בה \u0003רבים\u0004 ואפשר לומר שארבע אמותיו הן לפי שעה כשלו וקונות לו, אבל \u0003ברשות הרבים דקא דחקי\u0004 \u0005[שדוחקים]\u0006 בה \u0003רבים לא תקינו רבנן\u0004 \u0005[תקנו חכמים],\u0006 כדי שלא להביא לבלבול.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 לשון ההלכה אינה כך, כי \u0003\"בכל מקום\" קאמר\u0004 \u0005[אמר],\u0006 ומשמע אפילו ברשות הרבים!","ומשיבים: \u0003כל מקום\u0004 איננו ממש כל מקום, אלא \u0003לאתויי\u0004 \u0005[להביא]\u0006 אפילו \u0003צידי רשות הרבים,\u0004 שאף שסמוכים לרשות הרבים, כיון שאין הרבים דוחקים בהם כל כך — ארבע אמותיו קונות לו בהן.","ועוד הלכה \u0003אמר ריש לקיש משום\u0004 \u0005[בשם]\u0006 \u0003אבא כהן ברדלא: קטנה אין לה חצר,\u0004 כלומר, דבר הנמצא בחצר שלה איננו נקנה לה \u0003ואין לה\u0004 דין \u0003ארבע אמות\u0004 שתקנה בהן. \u0003ו\u0004אילו \u0003ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' ינאי אמר: יש לה חצר ויש לה\u0004 דין \u0003ארבע אמות.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005נחלקו]?\u0006 ומסבירים: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' ינאי, \u0005סבור]\u0006 כי כח הקנין של \u0003חצר משום\u0004 כח \u0003ידה איתרבאי\u0004 \u0005[התרבה],\u0006 ואם כן \u0003כי היכי דאית\u0004 \u0005[כמו שיש]\u0006 \u0003לה יד\u0004 הן במובן הממשי והן במובן המשפטי, הרי אף דין \u0003חצר נמי אית\u0004 \u0005[גם כן יש]\u0006 \u0003לה,\u0004 שהיא כהמשך של ידה. \u0003ומר סבר\u0004 \u0005[חכם זה,\u0006 אבא כהן, \u0005סבור]\u0006 כי \u0003חצר משום שליחות איתרבאי\u0004 \u0005[התרבתה]\u0006 \u0003ו\u0004\u0003כי היכי\u0004 \u0005[וכמו]\u0006 ש\u0003שליחות לית\u0004 \u0005[אין]\u0006 \u0003לה,\u0004 שקטן אינו יכול למנות שליח, \u0003חצר נמי לית\u0004 \u0005[גם כן אין]\u0006 \u0003לה,\u0004 ותוהים:","\u0003מי איכא מאן דאמר\u0004 \u0005[האם יש מי שאומר]\u0006 כי \u0003חצר משום שליחות איתרבאי\u0004 \u0005[התרבתה]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 בענין זה: ממה שנאמר בכתוב \"אם המצא תמצא \u0003בידו\u0004 הגניבה משור עד חמור עד שה חיים שניים ישלם\" (שמות כב, ג) \u0003אין לי\u0004 ללמוד \u0003אלא ידו\u0004 ממש, ואולם אם נכנסה הבהמה ל\u0003גגו,\u0004 או \u0003חצירו\u0004 או \u0003קרפיפו\u0004 (חצר אחורית) ונעל בפניה בכוונה לגונבה \u0003מנין\u0004 שאף בהם הדין כן — \u0003תלמוד לומר: \"המצא תמצא\" מכל מקום.\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003חצר משום שליחות איתרבאי\u0004 \u0005[התרבתה],\u0006 \u0003אם כן מצינו\u0004 (מצאנו) שיש \u0003שליח לדבר עבירה\u0004 \u0003ו\u0004הרי \u0003קיימא לן\u0004 \u0005[מוחזק בידינו]\u0006 כי \u0003אין שליח לדבר עבירה,\u0004 שכשנשלח מישהו לעשות דבר עבירה, פוקע קשר השליחות מעצמו!","\u0003אמר רבינא:\u0004 מכאן אין להקשות, שכן \u0003היכא אמרינן\u0004 \u0005[היכן אומרים אנו]\u0006 ש\u0003אין שליח לדבר עבירה\u0004 — \u0003היכא\u0004 \u0005[היכן]\u0006 שה\u0003שליח\u0004 עצמו \u0003בר חיובא\u0004 \u0005[בן חיוב]\u0006 \u0003הוא,\u0004 ולכן החיוב נופל על השליח ולא על המשלח, \u0003אבל בחצר דלאו בר חיובא הוא\u0004 \u0005[שלא בת־חיוב היא]\u0006 — \u0003מיחייב שולחו.\u0004","ומקשים על רבינא: \u0003אלא מעתה, האומר לאשה ועבד: \"צאו גנבו לי\"\u0004 (עבורי) \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003בני חיובא נינהו\u0004 \u0005[חיוב הם],\u0006 שהרי אין להם רכוש משלהם שאפשר לגבות ממנו, \u0003הכי נמי דמיחייב\u0004 \u0005[כך גם כן תאמר שמתחייב]\u0006 \u0003שולחן\u0004 ולא הם?!","ודוחים: \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 \u0003אשה ועבד\u0004 הלא אלה \u0003בני חיובא נינהו\u0004 \u0005[חיוב הם]\u0006 מצד אישיותם המשפטית, \u0003ו\u0004אולם \u0003השתא מיהא לית להו לשלומי\u0004 \u0005[עכשיו בכל אופן אין להם לשלם],\u0006 ואם כן, אף שאמנם אי אפשר לגבות מהם מכל מקום בעצם מוטל חיוב משפטי עליהם. וראיה לדבר — ממה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003נתגרשה האשה\u0004 וחזר ממונה לידה, או ש\u0003נשתחרר העבד\u0004 — \u0003חייבים לשלם\u0004 על מה שגנבו או הזיקו בעודם תחת הבעל או האדון.","\u0003רב סמא אמר\u0004 חילוק אחר: \u0003היכא אמרינן\u0004 \u0005[היכן אנו אומרים]\u0006 ש\u0003אין שליח לדבר עבירה\u0004 — הרי זה דווקא \u0003היכא דאי בעי עביד ואי בעי לא עביד\u0004 \u0005[אם\u0006 השליח \u0005רוצה\u0006 לעשות \u0005עושה ואם אינו רוצה אינו עושה],\u0006 \u0003אבל חצר\u0004 ש\u0003בעל כרחיה מותיב\u0004 \u0005[כרחו מעמיד]\u0006 הוא \u0003בה\u0004 דברים והחצר איננה בעלת רצון, הרי אז \u0003מיחייב\u0004 \u0005[מתחייב]\u0006 \u0003שולחו,\u0004 כלומר בעליה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 הלכה למעשה\u0005]\u0006 לענין טעם ההלכה ש\"אין שליח לדבר עבירה\"? ואומרים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל מעשי\u0005]\u0006 כגון ב\u0003כהן\u0004 ש\u0003אמר ליה לישראל: צא וקדש לי\u0004 (עבורי) \u0003אשה גרושה,\u0004 שהכהן אסור לשאת גרושה וישראל מותר בה, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003איש\u0004 ש\u0003אמר לה לאשה אקפי\u0004 \u0005[הקיפי]\u0006 \u0003לי,\u0004 עבורי, בשליחותי, את פאת ראשו של \u0003קטן,\u0004 שהקפת הראש, גזיזת פיאות הראש, אסורה מן התורה (\"לא תקיפו פאת ראשכם\". ויקרא יט, כז) ואסורה היא רק לגברים ולא לנשים.","ומעתה \u0003להך לישנא\u0004 \u0005[לאותה לשון]\u0006 ש\u0003אמר\u0004 \u0003כל היכא דאי בעי עביד, אי בעי לא עביד\u0004 \u0005[מקום שאם רוצה עושה ואם רוצה אינו עושה]\u0006 — \u0003לא מיחייב\u0004 \u0005[מתחייב]\u0006 \u0003שולחו,\u0004 אלא השליח, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003אי בעי עביד, אי בעי לא עביד\u0004 \u0005[אם רוצה\u0006 השליח \u0005עושה,\u0006 ו\u0005אם אינו רוצה אינו עושה]\u0006 ולכן \u0003לא מיחייב\u0004 \u0005[מתחייב]\u0006 \u0003שולחן.\u0004 ואולם \u0003להך לישנא\u0004 \u0005[לאותה לשון]\u0006 ש\u0003אמרת\u0004 כי \u0003כל היכא\u0004 \u0005[מקום]\u0006 שה\u0003שליח לאו בר חיובא\u0004 \u0005[בן חיוב]\u0006 \u0003מיחייב שולחו\u0004 \u0005[מתחייב שולחו],\u0006 \u0003הני נמי\u0004 \u0005[אלה גם כן]\u0006 \u0003כיון דלאו\u0004 \u0005[שלא]\u0006 \u0003בני חיובא נינהו\u0004 \u0005[חיוב הם]\u0006 \u0003מיחייב\u0004 \u0005[מתחייב]\u0006 \u0003שולחן.\u0004","ועוד מקשים לגוף בעייתנו: \u0003ומי איכא למאן דאמר\u0004 \u0005[והאם יש מי שאומר]\u0006 ש\u0003חצר לאו\u0004 \u0005[לא]\u0006 \u0003משום ידה איתרבאי\u0004 \u0005[התרבתה]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת: ממה שנאמר \u0003\"\u0004וכתב לה ספר כריתות ונתן ב\u0003ידה\"\u0004 (דברים כד, א) \u0003אין לי\u0004 ללמוד \u0003אלא ידה\u0004 ממש, ואולם אם נתן בתוך \u0003גגה חצירה וקרפיפה מנין\u0004 שכן הוא הדין? — \u0003תלמוד לומר: \"ונתן\"\u0004 — מכל מקום, משמע שחצר משום יד הוא!","ומשיבים: אכן, \u0003לענין גט כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 ש\u0003חצר משום ידה איתרבאי\u0004 \u0005[התרבתה]\u0006 מטעם אחר, ואולם \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003לענין\u0004 קנין \u0003מציאה\u0004 של החצר. \u0003מר סבר\u0004 \u0005[חכם זה סבור]\u0006"],["\u0003ילפינן\u0004 \u0005[למדים אנו]\u0006 \u0003מציאה מגט, ומר סבר\u0004 \u0005[וחכם זה סבור]:\u0006 ש\u0003לא ילפינן\u0004 \u0005[לומדים אנו]\u0006 \u0003מציאה מגט,\u0004 ובכל מקרה יש לחצר דין לעצמו.","\u0003ואיבעית אימא:\u0004 \u0005[ואם תרצה אמור]\u0006 כך: \u0003בקטנה כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 \u0003דילפינן\u0004 \u0005[שלומדים אנו]\u0006 \u0003מציאה מגט,\u0004 וכיון שחצירה משום ידה לענין גט, כן היא גם לענין מציאה וקנין. \u0003והכא\u0004 \u0005[ו\u0006אולם \u0005כאן]\u0006 \u0003ב\u0004דינו של \u0003קטן קא מיפלגי\u0004 \u0005[נחלקו],\u0006","\u0003מר סבר\u0004 \u0005[חכם זה סבור]\u0006 כי \u0003ילפינן\u0004 \u0005[לומדים אנו]\u0006 \u0003קטן מקטנה,\u0004 שלכאורה אין כל הבדל ביניהם בהלכה. \u0003ומר סבר\u0004 \u0005[וחכם זה סבור]\u0006 ש\u0003לא ילפינן\u0004 \u0005[לומדים אנו]\u0006 \u0003קטן מקטנה,\u0004 אלא קטנה שנתרבה בה דין חצר בגט — יש לה דין חצר למציאה, ואילו בקטן לא.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שמעיקר הדבר אין כאן מחלוקת, אלא \u0003מר\u0004 \u0005[חכם זה],\u0006 אחד מהם \u0003אמר חדא\u0004 \u0005[\u0006הלכה \u0005אחת]\u0006 שיש חצר לענין גט לקטנה, \u0003ומר\u0004 \u0005[וחכם זה],\u0006 האחר, \u0003אמר חדא\u0004 \u0005[\u0006דבר \u0005אחד,\u0006 אחר\u0005]\u0006 לענין מציאה \u0003ולא פליגי\u0004 \u0005[ואינם חלוקים]\u0006 כלל.","עמד בעל שדה ו\u0003ראה אותם\u0004 אנשים \u0003רצין אחר מציאה,\u0004 כגון שרודפים \u0003אחר צבי שבור\u0004 (שרגלו שבורה) שאינו יכול לרוץ היטב, או \u0003אחר גוזלות שלא פרחו\u0004 עדיין וניתנים להיתפס בנקל, \u0003ואמר: \"זכתה לי שדי\u0004 במציאה זו \u0003\"\u0004— \u0003זכתה לו,\u0004 אם כי אנשים אחרים הם שהיו רודפים אחרי הצבי או הגוזלות. ואולם אם \u0003היה צבי רץ כדרכו, או שהיו גוזלות מפריחין\u0004 (מתעופפים), \u0003ואמר \"זכתה לי\u0004 בהם \u0003שדי\"\u0004 — \u0003לא אמר כלום,\u0004 שאין חצירו יכולה לקנות לו דבר שאינו נשאר בה מעצמו.","\u0003אמר רב יהודה אמר שמואל:\u0004 זכות קנין זו שאמרנו במשנה \u0003הוא\u0004 דווקא באופן \u0003שעומד\u0004 באותה שעה \u0003בצד שדהו,\u0004 ומכיון שכן הרי זו חצר המשתמרת.","ומקשים: \u0003ותקני ליה\u0004 \u0005[ושתקנה לו]\u0006 \u0003שדהו\u0004 עצמה אף בלא שיאמר במפורש, שהרי \u0003אמר ר' יוסי בר' חנינא: חצרו של אדם קונה לו שלא מדעתו!\u0004","ומסבירים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003בחצר המשתמרת,\u0004 שהדברים הנמצאים בה משתמרים בעצמם שם, אבל ב\u0003חצר שאינה משתמרת, אי\u0004 \u0005[אם]\u0006 \u0003עומד\u0004 הזוכה \u0003בצד שדהו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 קנה, \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 \u0003לא\u0004 — \u0003לא\u0004 קנה.","ומוסיפים: \u0003ומנא תימרא\u0004 \u0005[ומניין תאמר]\u0006 ש\u0003חצר שאינה משתמרת, אי\u0004 \u0005[אם]\u0006 \u0003עומד בצד שדהו\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 קנה, \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 \u0003לא\u0004 עומד בצידה — \u0003לא\u0004 קנה?","— \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003היה\u0004 בעל הבית \u0003עומד בעיר ואומר: \"יודע אני שעומר שיש לי בשדה\u0004 אחר שאני הנחתיו שם מתוך כוונה שהפועלים יביאוהו וה\u0003פועלים\u0004 הם ש\u0003שכחוהו\u0004 ואולם אני זוכר אותו ו\u0003לא יהא שכחה,\u0004 ולא יהא שייך לעניים,\u0003 יכול לא יהא\u0004 בו דין \u0003שכחה\u0004 — \u0003תלמוד לומר:\u0004 \"כי תקצור קצירך בשדך \u0003ושכחת עמר בשדה\u0004 לא תשוב לקחתו לגר ליתום ולאלמנה יהיה\" (דברים כד, יט), וכך יש לדייק מן הכתוב: \u0003בשדה ושכחת\u0004 — \u0003ולא בעיר.\u0004","מתחילה מבררים את לשון הברייתא הזו לגופה, שהרי \u0003הא גופא קשיא\u0004 \u0005[זו עצמה קשה]:\u0006 שכן \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 \u0003יכול לא יהא שכחה\u0004 — \u0003אלמא\u0004 \u0005[מכאן]\u0006 שהתנא רוצה להוכיח כי בכל זאת \u0003הוי\u0004 \u0005[הריהי]\u0006 \u0003שכחה, ונסיב לה תלמודא\u0004 \u0005[ומביא את הלימוד]\u0006 \u0003\"בשדה ושכחת\" ולא בעיר, אלמא\u0004 \u0005[מכאן]\u0006 כי \u0003לא הוי\u0004 \u0005[אין זה]\u0006 \u0003שכחה,\u0004 בניגוד להנחה הראשונה!","\u0003אלא לאו הכי קאמר\u0004 \u0005[האם לא כך אמר],\u0006 שכך יש להבחין: אם היה הדבר \u0003בשדה\u0004 — \u0003שכוח מעיקרו הוי\u0004 \u0005[הריהו]\u0006 \u0003שכחה,\u0004 אבל \u0003זכור ולבסוף שכוח, אין\u0004 קרוי \u0003שכחה, מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — ש\u0003כיון דקאי גבה\u0004 \u0005[שעומד לידה]\u0006 \u0003הויא ליה\u0004 \u0005[הרי זו]\u0006 \u0003חצרו וזכתה ליה\u0004 \u0005[לו]\u0006 בעומר שזכר.","\u0003אבל בעיר, אפילו זכור ולבסוף שכוח\u0004 — \u0003הויא\u0004 \u0005[הרי זו]\u0006 \u0003שכחה.\u0004 ומסתבר, כי \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003דליתיה גביה דלזכי ליה\u0004 \u0005[שאינו שם כדי שתזכה לו\u0006 חצרו\u0005].\u0006","ומקשים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מניין יודע אתה שזהו הטעם?] \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003גזירת הכתוב היא,\u0004 ש\u0003בשדה נהוי\u0004 \u0005[תהא]\u0006 זו \u0003שכחה ובעיר לא נהוי\u0004 \u0005[תהיה]\u0006 זו \u0003שכחה\u0004 ולא מחמת דיני הקניינים?!","ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לא תשוב לקחתו\"\u0004 (דברים כד, יט), \u0003לרבות שכחת העיר.\u0004 הרי שגם שכחת העיר קרויה שכחה, ואם כן טעם החלוקה הנזכר בהיותו בעיר אינו משום ההבדל בין עיר ושדה, אלא משום אפשרות הקנין.","ודוחים: \u0003האי מיבעי ליה\u0004 \u0005[\u0006כתוב \u0005זה נצרך לו]\u0006 \u0003ללאו,\u0004 ללמד שאם לקח את העומר אחר ששכחו עבר על מצוות לא תעשה!","ומשיבים: אם בא הכתוב רק לצורך זה, \u0003אם כן נימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"לא תקחנו\", מאי\u0004 \u0005[מה\u0006 לשון\u0005]\u0006 \u0003\"לא תשוב\"\u0004 — \u0003לרבות שכחת העיר.\u0004","ומעירים: \u0003ואכתי מיבעי ליה\u0004 \u0005[ועדיין צריך לו]\u0006 לכתוב זה בלשון \"לא תשוב\" \u0003לכדתנן\u0004 \u0005[לכפי ששנינו\u0006 במשנה\u0005]:\u0006 כל עומר בשדה \u0003ש\u0004עומד עדיין \u0003לפניו,\u0004 ושהוא עתיד לבוא לצד זה של השדה תוך כדי העבודה — \u0003אין\u0004 בו \u0003שכחה\u0004 גם אם שכחו. וכל עומר \u0003ש\u0004נמצא כבר \u0003לאחריו\u0004 — \u0003יש בו שכחה, שהוא ב\"בל תשוב\".\u0004","ו\u0003זה הכלל: כל שהוא ב\"בל תשוב\",\u0004 כלומר שצריך לחזור במיוחד כדי לקחתו — הרי זו \u0003שכחה,\u0004 ו\u0003כל שאינו ב\"בל תשוב\"\u0004 אלא מגיע לשם מעצמו לצורך עבודתו — \u0003אינו שכחה.\u0004 ואם כן לענין זה נצרכה הלשון \"תשוב\"!","\u0003אמר רב אשי: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"יהיה\"\u0004 (שם) ומשם למדנו \u0003לרבות שכחת העיר.\u0004 וכיון שלמדנו שכחת העיר, ודאי החילוק בהלכה הוא משום שדה קונה ואינו קונה.","\u0003וכן אמר עולא\u0004 בביאור משנתנו: \u0003והוא שעומד בצד שדהו. וכן אמר רבה בר בר חנה: והוא שעומד בצד שדהו.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' אבא לעולא\u0004 ממה ששנינו: \u0003מעשה ברבן גמליאל וזקנים שהיו באים\u0004 (נוסעים) \u0003בספינה.\u0004 ולאחר שנזכר שלא עישר \u0003פירותיו\u0004 \u0003אמר רבן גמליאל: \"עישור\u0004 (מעשר) \u0003שאני עתיד למוד\u0004 (למדוד, להפריש מתוך שדותי) \u0003נתון ליהושע\u0004 בן חנניה שהוא לוי ומגיע לו מעשר,"],["\u0003ומקומו\u0004 של המעשר שהוא מצוי בו כעת \u0003מושכר לו\u0004 בזה, וקיבל ממנו שם שכר המקום. וכאשר יתן ר' יהושע דמי שכירות כל שהם, יוכל לקנות על ידי כך את המעשר, שהרי מטלטלין אינם נקנים אלא או על ידי משיכתם בפועל, או אגב קרקע, \u0003ועשור\u0004 (מעשר) \u0003אחר שאני עתיד למוד,\u0004 שהוא מעשר עני, \u0003נתון לעקיבא בן יוסף\u0004 שהיה גבאי צדקה, \u0003כדי שיזכה בו לעניים\u0004 \u0003ומקומו מושכר לו.\u0004","ומעתה יש לשאול: \u0003וכי ר' יהושע ור' עקיבא בצד שדהו של רבן גמליאל היו עומדין\u0004 אז? הלא היו כולם בספינה. ומכאן שיכול אדם לקנות דבר בשדה אפילו אם אינו עומד בצד שדהו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא: \u0003דמי האי מרבנן כדלא גמרי אינשי שמעתא\u0004 \u0005[דומה זה מן החכמים כמי שלא למד דבר הלכה].\u0006 שלא התייחס עולא כלל לשאלה, שסבר שאין בה ממש.","ומסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 ר' אבא \u0003לסורא אמר להו\u0004 \u0005[להם]\u0006 לחכמי המקום: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר עולא והכי אותביתיה\u0004 \u0005[וכך הקשתי לו].\u0006 \u0003אמר ליה ההוא מרבנן\u0004 \u0005[לו אחד החכמים]:\u0006 \u0003רבן גמליאל מטלטלי אגב מקרקעי הקנה להם\u0004, שלא קנו את המעשר מדין חצר, אלא מכוח קנין־אגב, שאגב הקרקעות שהקנה להם נקנו להם גם מטלטלין, ואין הדבר שייך כלל להלכות של קנין חצר, ויש בכך דין אחר. ומעירים: \u0003ר' זירא קבלה\u0004 את ההבחנה הזו ואילו \u0003ר' אבא לא\u0004 \u0003קבלה.\u0004","\u0003אמר רבא: שפיר עביד\u0004 \u0005[יפה עשה]\u0006 ש\u0003לא קבלה\u0004 את ההבחנה הזו והתירוץ הזה, כי אילו רצה רבן גמליאל לתת להם ממש את המעשר \u0003וכי לא היה להם סודר לקנות ממנו בחליפין?\u0004 שהרי היו יכולים לקנות את המעשר המיטלטל לא אגב קרקע אלא בקנין חליפין, שהם נותנים לו סודר וקונים זה מזה את המטלטלין. \u0003אלא\u0004 על כרחך אתה חייב לומר שלא היה כאן דבר למכור אותו ממש, כי \u0003טובת הנאה אינה ממון,\u0004 שהרי המעשרות בעצם אינם רכושו של רבן גמליאל, שהרי בעל כרחו חייב הוא לתת אותם, ואין לו בהם אלא טובת הנאה, שיש לו זכות לתיתם למי שירצה, וטובת הנאה אינה ממון \u0003לקנות ממנו ב\u0004קנין \u0003חליפין.\u0004 ואם כן \u0003הכא נמי טובת הנאה אינה ממון לקנות על גבי קרקע,\u0004 ולכן לא היה רבן גמליאל יכול להקנות להם את המעשרות בקנין מטלטלין אגב מקרקעין. וחייבים לומר כר' אבא, שהקנה להם חצר, וחצרם קנתה את המעשר.","ודוחים: \u0003ולא היא,\u0004 הסברה שהעלה רבא אינה נכונה, שכן \u0003מתנות כהונה,\u0004 לוויה, ומעשר עני לשון \u0003\"נתינה\" כתיבא בהו\u0004 \u0005[נאמרה בהן]\u0006 (\"ונתתה ללוי לגר ליתום ולאלמנה\". דברים כו, יב), שהתורה מחשיבה את נתינתם כנתינה של ממש, ולא כהעברה של טובת הנאה בלבד. וכיון שכך \u0003חליפין\u0004 הרי \u0003דרך מקח וממכר הוא\u0004 ואינו שייך במעשרות, ואילו נתינת \u0003מטלטלין אגב מקרקע\u0004 \u0003נתינה אלימתא\u0004 \u0005[חזקה,\u0006 תקיפה\u0005]\u0006 \u0003היא,\u0004 ולכן השתמש בדרך זו, וממילא אין להקשות מכאן על עולא.","\u0003רב פפא אמר\u0004 גם אם נאמר שרבן גמליאל נתן להם בתורת חצר אין משם קושיה לדברי עולא, כי יש להבחין בין הדברים, שכן \u0003דעת אחרת מקנה אותן שאני\u0004 \u0005[שונה].\u0006 שיש הבדל בהלכה אם אדם אחר מקנה את הדברים מדעתו, לזכות קנין בחצר שקונה מעצמה בלא דעת מקנה.","\u0003ומנא תימרא\u0004 \u0005[ומנין תאמר]\u0006 שיש לחלק כך — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ראה אותן רצים אחר המציאה כו'\u0004 ואנו יודעים כי \u0003ר' ירמיה אמר\u0004 בשם \u0003ר' יוחנן: והוא שרץ אחריהן ומגיען,\u0004 שיכול לרוץ אחריהן ולתפוס, שאז הוא קונה. \u0003ובעי\u0004 \u0005[ושאל]\u0006 \u0003ר' ירמיה\u0004 בהמשך למסורת זו שקבל, \u0003במתנה היאך\u0004 \u0005[איך]?\u0006 מה הדין אם במצב כגון זה נתנו לו אותם אנשים את הדבר במתנה? ו\u0003קבלה מיניה\u0004 \u0005[קיבל ממנו]\u0006 \u0003ר' אבא בר כהנא\u0004 מר' ירמיה, שבמתנה כגון זו קונה \u0003אף על פי שרץ אחריהן ואין מגיען.\u0004 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 ההבדל\u0005]\u0006 — \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003דעת אחרת מקנה אותן שאני\u0004 \u0005[שונה]?!\u0006 ואם כן הרי זו ראיה לשיטת רב פפא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שימי לרב פפא:\u0004 ו\u0003הרי גט\u0004 אשה, ש\u0003דעת אחרת,\u0004 זו של הבעל, \u0003מקנה אותה, ו\u0004בכל זאת \u0003אמר עולא\u0004 שאם זרק גט בחצרה של אשה אינה נחשבת כמגורשת, אלא בדרך זו — \u0003והוא\u0004 כ\u0003שעומדת בצד ביתה או בצד חצרה.\u0004 השיב לו רב פפא: אינו דומה, שכן \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003גט דאיתיה\u0004 \u0005[שישנו]\u0006 גם \u0003בעל כרחה,\u0004 שאינו צריך להיות כלל מדעתה.","על תירוץ זה \u0003מתקיף\u0004 \u0005[מקשה]\u0006 \u0003רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: ולאו\u0004 \u0005[וכי לא]\u0006 \u0003קל וחומר הוא — ומה גט דאיתיה\u0004 \u0005[שישנו]\u0006 \u0003בעל כרחה\u0004 ונתינתו נחשבת אפילו שלא מדעתה, ובכל זאת \u0003אי\u0004 \u0005[אם]\u0006 \u0003עומדת בצד ביתה\u0004 או \u0003בצד חצרה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 הגט נקנה לה, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא.\u0004 \u0003מתנה\u0004 שאין אדם מקבל אלא \u0003מדעתיה\u0004 \u0005[מדעתו]\u0006 \u0003לא כל שכן\u0004 שאף כשיש דעת מקנה — חייב הקונה להיות בצד החצר!","\u0003אלא אמר רב אשי,\u0004 כך יש להסביר:"],["\u0003חצר איתרבאי\u0004 \u0005[התרבתה]\u0006 \u0003משום יד ו\u0004אולם היא \u0003לא גרעה\u0004 \u0005[גרועה,\u0006 פחותה\u0005]\u0006 \u0003מ\u0004דין \u0003שליחות.\u0004 וכך יש לחלק: \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003גט\u0004 ש\u0003חוב הוא לה,\u0004 שקבלת הגט היא לחובתה של האשה הרי כלל הוא: \u0003אין חבין לאדם אלא בפניו,\u0004 ולכן החצר אינה יכולה לקנות לה גט שלא בפניה. ואולם \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003מתנה\u0004 ש\u0003זכות הוא לו\u0004 לאדם המקבל אותה — \u0003זכין לאדם שלא בפניו,\u0004 ולכן זוכה לו חצרו אף שלא מדעתו.","כיון שהוזכרה דרך אגב הלכה זו, דנים בה \u0003גופא\u0004 \u0005[לגופה].\u0006 שנינו במשנה שאם \u0003ראה אותן רצים אחר המציאה\u0004 ואמר \"זכתה לי שדי בה\" — זכתה לו. ועל כך \u0003אמר ר' ירמיה אמר ר' יוחנן: והוא שרץ אחריהן ומגיען,\u0004 ואם לא — אינו קונה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 \u0003במתנה\u0004 בכגון זו \u0003היאך\u0004 \u0005[איך]\u0006 יהיה הדין? \u0003קבלה מיניה\u0004 \u0005[ממנו]\u0006 \u0003ר' אבא בר כהנא\u0004 שבמתנה הדין כן \u0003אף על פי שרץ אחריהן ואין מגיען.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 ממה ששנינו: \u0003זרק ארנקי\u0004 (ארנק) \u0003בפתח זה\u0004 של בית \u0003ויצא בפתח אחר מהו\u0004 הדין? האם נקנה הארנק לבעל הבית תוך כדי מעופו? והשאלה היא: דבר המצוי ב\u0003אויר\u0004 (חלל) \u0003שאין סופו לנוח,\u0004 האם \u0003כמונח דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 \u0003או לא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אדא בר מתנה לרבא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רבינא לרבא: לאו היינו מתניתין\u0004 \u0005[וכי אין זו משנתנו]\u0006 ששנינו בה: \u0003ראה אותן רצין אחר המציאה וכו' ואמר ר' ירמיה אמר ר' יוחנן: והוא שרץ אחריהן ומגיען, ובעי\u0004 \u0005[ושאל]\u0006 \u0003ר' ירמיה: במתנה היאך\u0004 \u0005[איך]\u0006 \u0003וקבלה מיניה\u0004 \u0005[ממנו],\u0006\u0003רבי אבא בר כהנא\u0004 הגיע למסקנה כי \u0003במתנה אף על פי שרץ אחריהן ואין מגיען.\u0004 הרי שדבר העובר בתחומו של אדם, גם אם אינו נשאר שם, דינו כשלו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מתגלגל קאמרת\u0004","\u0005[אתה אומר]?\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003מתגלגל\u0004 ש\u0003כמונח דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 שהרי בכל רגע של גלגול הוא מונח במקום, אלא שהוא זז ממקום למקום בשטח, מה שאין כן בדבר שנזרק בחלל הבית ואינו נשאר מונח שם כלל, ואם כן אין לפטור משם את הבעיה.","\u0003מציאת בנו ובתו הקטנים\u0004 של אדם, או \u0003מציאת עבדו ושפחתו הכנענים,\u0004 או \u0003מציאת אשתו\u0004 — \u0003הרי אלו שלו.\u0004 ואילו \u0003מציאת בנו ובתו הגדולים,\u0004 וכן \u0003מציאת עבדו ושפחתו העברים,\u0004 או \u0003מציאת אשתו שגירשה, אף על פי שלא נתן\u0004 לה עדיין את פרעון ה\u0003כתובה\u0004 כפי שהתחייב — \u0003הרי אלו שלהן.\u0004","\u0003אמר שמואל: מפני מה אמרו\u0004 ש\u0003מציאת קטן לאביו\u0004 — משום \u0003ש\u0004הקטן אינו מתכוון לקנות לעצמו, אלא \u0003בשעה שמוצאה\u0004 הריהו \u0003מריצה אצל אביו ואינו מאחר בידו.\u0004","ושואלים: \u0003למימרא דסבר\u0004 \u0005[האם נאמר שסבור]\u0006 \u0003שמואל\u0004 כי \u0003קטן לית ליה\u0004 \u0005[אין לו]\u0006 \u0003זכייה לנפשיה מדאורייתא\u0004 \u0005[לעצמו מן התורה]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003השוכר את הפועל\u0004 לקצור את שדהו — \u0003ילקט בנו אחריו,\u0004 שיכול בנו של הפועל ללקט שיבלים כשאר עניים הזוכים בלקט בשדה. שכר את הפועל \u0003למחצה, לשליש\u0004 או \u0003לרביע\u0004 (רבע), שאינו שכיר יום, אלא הוא אריס בשדה ומקבל חלק מן היבול — \u0003לא ילקט בנו אחריו,\u0004 כיון שהוא נחשב בעצמו כבעל שדה ובנו הוא כבן בעל הבית, ולפיכך אינו רשאי ללקוט. \u0003ר' יוסי אומר: בין כך ובין כך ילקט בנו ואשתו אחריו. ואמר שמואל: הלכה כר' יוסי.\u0004","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005נניח אם אומר אתה]\u0006 כי \u0003קטן אית ליה\u0004 \u0005[יש לו]\u0006 \u0003זכייה לנפשיה\u0004 \u0005[לעצמו]\u0006 אפשר להבין את שיטת שמואל שכן \u0003כי קא\u0004 \u0005[כאשר הוא]\u0006 \u0003מלקט\u0004 — \u0003לנפשיה קא\u0004 \u0005[לעצמו הוא]\u0006 \u0003מלקט\u0004 וזוכה בו, שהרי הקטן הזה עצמו אין לו רכוש, ודינו כעני ומותר לו ללקט, \u0003ואבוה מיניה קא זכי\u0004 \u0005[ואביו\u0006 שאחר כך מקבל \u0005ממנו הוא זוכה],\u0006 שהקטן נותן לו במתנה מה שלקט. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003קטן לית ליה\u0004 \u0005[אין לו]\u0006 \u0003זכייה לנפשיה\u0004 \u0005[לעצמו],\u0006 אם כן \u0003כי קא\u0004 \u0005[כאשר הוא]\u0006 \u0003מלקט\u0004 — \u0003לאביו קא\u0004 \u0005[הוא]\u0006 ש\u0003מלקט, אבוה\u0004 \u0005[\u0006ו\u0005אביו]\u0006 הלא \u0003עשיר הוא,\u0004 שכיון שיש לו חלק בשדה יצא מכלל העניים הזכאים בלקט, ואם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אשתו ובנו מלקט אחריו?\u0004","ומשיבים: אכן, \u0003שמואל\u0004 עצמו סבור שקטן זוכה לעצמו, אלא בהסברו למשנתנו שמואל \u0003טעמא\u0004 \u0005[\u0006את \u0005הטעם]\u0006 של ה\u0003תנא דידן קאמר\u0004 \u0005[שלנו אמר],\u0006 \u0003וליה לא סבירא ליה\u0004 \u0005[ו\u0006אולם \u0005הוא\u0006 עצמו \u0005אינו סבור כן].\u0006","ושואלים: \u0003וסבר\u0004 \u0005[ו\u0006כי \u0005סבור]\u0006 \u0003ר' יוסי\u0004 ש\u0003קטן אית ליה\u0004 \u0005[יש לו]\u0006 \u0003זכייה מדאורייתא\u0004 \u0005[מן התורה]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003מציאת חרש, שוטה וקטן יש בהן משום גזל\u0004 אם לוקחים אותה מהם \u0003מפני דרכי שלום.\u0004 \u0003ר' יוסי אומר:\u0004 לא מפני דרכי שלום לבד אסור, אלא \u0003גזל גמור\u0004 הוא.","\u0003ואמר רב חסדא:\u0004 ר' יוסי התכוון לומר שהוא \u0003גזל גמור מדבריהן,\u0004 מדברי חכמים, שחכמים הם שקבעו שמציאתו של אלו תיחשב כשלהם, והלוקח מהם דינו כגזלן. ומעירים: \u0003נפקא מינה\u0004 \u0005[יוצא מזה הבדל]\u0006 אם הוא משום דרכי שלום או גזל גמור מדבריהם לענין \u0003להוציאה בדיינין,\u0004 שאם הוא גזל גמור (אפילו מדברי חכמים) אפשר לתבוע את הגזלן לדין ולקבל ממנו את המציאה. על כל פנים מכאן לומדים שגם ר' יוסי אינו סבור שקטן זוכה בעצמו מדין התורה.","\u0003אלא אמר אביי\u0004 יש לדחות את מה שהסברנו בדין הבן המלקט והטעם שהבן יכול ללקט הוא משום ש\u0003עשאוה,\u0004 החשיבו את השדה \u0003כמי שהלכו בה נמושות,\u0004 כמו שדה שכבר עברו בו אחרוני המלקטים, שבשדה כזה אפילו עשירים מותר להם לקחת מן הלקט משום שהעניים כבר התייאשו מהנותר. ואף כאן, ה\u0003עניים גופייהו\u0004 \u0005[עצמם]\u0006 \u0003מסחי דעתייהו\u0004 \u0005[מסיחים דעתם]\u0006 מללקוט בשדה זה. שכן \u0003סברי\u0004 \u0005[סבורים\u0006 הם\u0005]:\u0006 \u0003בריה דהיאך מלקטי ליה\u0004 \u0005[בניו של זה מלקטים לו],\u0006 וכיון ששאר העניים מבינים שאין להם מה ללקוט שם, לכן יכול הבן ללקט.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר מתנה לאביי:\u0004 אם כן, הרי מפני שיודעים שבניו של אדם נמצאים שם נמנעים שאר העניים מלקחת את חלקם הראוי להם, \u0003וכי מותר לאדם להרביץ\u0004 (להושיב) \u0003ארי\u0004 (אריה) \u0003בתוך שדהו כדי שיראו העניים ויברחו?\u0004 שהרי גם כאן, כאשר מביא הפועל את בניו מסתלקים שאר העניים ואולם אינם עושים כך לפי הדין ואין להתיר לכתחילה לעשות זאת!","אלא \u0003אמר רבא:\u0004 יש לדחות טעם זה, ולומר"],["\u0003עשו,\u0004 תקנו חכמים תקנה שגם זה \u0003שאינו זוכה\u0004 (בנו של האריס) ייחשב \u0003כזוכה,\u0004 ו\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 בתקנה זו — \u0003עניים גופייהו ניחא להו\u0004 \u0005[עצמם נוח להם]\u0006 בתקנה זו שעושים לכולם, \u0003כי היכי דכי אגרו לדידהו נלקוט בנייהו בתרייהו\u0004 \u0005[שכאשר ישכרו אותם\u0006 כפועלים \u0005ילקטו בניהם אחריהם].\u0006","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוק]\u0006 שמואל על דברי \u0003ר' חייא בר אבא.\u0004 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן:\u0004 כוונת משנתנו היא \u0003לא גדול\u0004 — \u0003גדול ממש,\u0004 שהגיע לבגרות, \u0003ולא קטן\u0004 — \u0003קטן ממש, אלא\u0004 הכוונה היא זו: שאפילו הוא \u0003גדול ו\u0004אולם הוא \u0003סמוך על שלחן אביו\u0004 — \u0003זהו קטן.\u0004 שכיון שהוא סמוך על שולחן אביו מן הסתם מה שהוא מוצא ראוי שימסור לאביו. ואפילו הוא \u0003קטן ו\u0004אולם \u0003אינו סמוך על שלחן אביו\u0004 — \u0003זהו גדול\u0004 ומציאתו לעצמו.","שנינו במשנה כי \u0003מציאת עבדו ושפחתו העברים הרי הוא של עצמן.\u0004 ותוהים: \u0003אמאי\u0004 \u0005[מדוע]?!\u0006 \u0003לא יהא\u0004 העבד \u0003אלא\u0004 כ\u0003פועל. ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003מציאת פועל לעצמו. במה דברים אמורים\u0004 — \u0003בזמן שאמר לו\u0004 בעל הבית: \u0003\"נכש עמי היום,\u0004 או שאמר לו \u0003\"עדור\u0004 \u0003עמי היום\",\u0004 ואז מציאת פועל לעצמו, כיון שפירט לו את מהות המלאכה שהוא מצפה ממנו לעשות עבורו, ואין בכלל אלו זכייה עבורו במציאה.","\u0003אבל\u0004 אם \u0003אמר לו \"עשה עמי מלאכה היום\"\u0004 בלא לפרט את מהות המלאכה — \u0003מציאתו לבעל הבית,\u0004 שהרי אף זה בתוך המלאכה הכללית שעושה.","והרי העבד מושכר לבעליו לכל מלאכה, ומדוע לא יזכה אדוניו במציאתו? \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הכא\u0004 \u0005[כאן]\u0006 \u0003בעבד נוקב מרגליות עסקינן\u0004 \u0005[עוסקים אנו]\u0006 \u0003שאין רבו רוצה לשנותו למלאכה אחרת,\u0004 לפי שהוא מרוויח הרבה מאוד במלאכתו, ולכן דינו כפועל שנשכר לעבודה מסויימת בלבד.","\u0003רבא אמר: במגביה מציאה עם מלאכתו עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שאינו בטל כלל ממלאכתו שעושה, ואין אדוניו מפסיד מאומה ממה שמגביה באותה שעה מציאה, ויכול משום כך לקחתה לעצמו.","\u0003רב פפא אמר:\u0004 מה שאמרו בפועל שמציאתו לבעל הבית הרי זה ב\u0003כגון ששכרו\u0004 במיוחד \u0003ללקט מציאות.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד היה זה בדיוק]\u0006 שישכרו אדם למציאת מציאות? ומשיבים: כגון \u0003דאקפי אגמא בכוורי\u0004 \u0005[שהציף האגם\u0006 את השדה \u0005בדגים]\u0006 ואחר כך חזרו המים, ונשארו הדגים בשדה, ושוכר פועלים ללקט את הדגים הללו.","שנינו כי מציאת שפחתו העברית לעצמה, ושואלים: בעצם \u0003האי שפחה היכי דמי\u0004 \u0005[שפחה זו איך בדיוק היא]?\u0006 \u0003אי דאייתי\u0004 \u0005[אם שהביאה]\u0006 \u0003שתי שערות\u0004 שהם סימני בגרות, \u0003מאי בעיא גביה\u0004 \u0005[מה\u0006 אם כן \u0005היא\u0006 צריכה \u0005לעשות\u0006 אצלו], שהרי שפחה עבריה עם הגיעה לבגרות הריהי משתחררת.","\u0003ואי\u0004 \u0005[ואם]\u0006 ש\u0003לא אייתי\u0004 \u0005[הביאה]\u0006 \u0003שתי שערות\u0004 ועדיין קטנה היא, \u0003אי איתיה\u0004 \u0005[אם\u0006 עדיין \u0005ישנו]\u0006 \u0003לאב\u0004 בחיים — הרי המציאה \u0003דאבוה הויא\u0004 \u0005[של אביה היא]!\u0006 \u0003ואי דליתיה\u0004 \u0005[ואם שאין]\u0006 \u0003לאב,\u0004 שכבר מת — \u0003תיפוק\u0004 \u0005[תצא\u0006 לחופשי\u0005]\u0006 \u0003במיתת האב.\u0004","שהרי \u0003אמר ריש לקיש: אמה העבריה קנה\u0004 את \u0003עצמה במיתת האב מרשות האדון מקל וחומר.\u0004 שכן אם בגרות שאינה מוציאתה מרשות האב הריהי מוציאתה מרשות האדון, מיתת האב שמוציאתה מרשות אביה, כל שכן שמוציאתה מרשות אדוניה, ואם כן מה עושה היא אצלו? ושואלים: \u0003ולאו איתותב\u0004 \u0005[ו\u0006כי \u0005לא הושבו\u0006 ונדחו\u0005]\u0006 דברי \u0003ריש לקיש\u0004 אלה ממקומות אחרים? והרי כבר הוכחנו שאין הדין כן!","ואומרים: על כל פנים \u0003נימא מהאי נמי תיהוי תיובתא\u0004 \u0005[נאמר\u0006 כי \u0005מכאן גם כן תהא\u0006 זו \u0005קושיה\u0006 עליו\u0005]!\u0006","ודוחים: \u0003לא,\u0004 אם תדייק בדברים לא תוכיח מכאן, ו\u0003לעולם\u0004 תפרש \u0003דאיתיה לאב\u0004 \u0005[שהאב ישנו],\u0006 \u0003ומאי\u0004 \u0005[ומה פירוש]\u0006 \u0003\"הרי הן שלהן\"\u0004 — \u0003לאפוקי דרבה\u0004 \u0005[להוציא\u0006 ולומר שאינו \u0005של בעליה],\u0006 כלומר, המציאה שייכת באמת לא לשפחה הילדה כי אם לאביה, ומה שאמר במשנה \"הרי הן שלהן\", כוונתו שאינו שייך לאדון, אלא השפחה זוכה, וממנה זוכה אביה.","שנינו במשנה ש\u0003מציאת אשתו\u0004 שגירשה הרי היא לעצמה. ותוהים: \u0003גירשה פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי לאחר שגירשה אין לה עוד כל קשר עם בעלה!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003ב\u0004מקרה שהיתה \u0003מגורשת ואינה מגורשת,\u0004 וכגון שהיה ספק בכשרות הגט, או במסירתו המוחלטת לה, ועדיין לא נגמרו הגירושין. ש\u0003אמר ר' זירא אמר שמואל: כל מקום שאמרו חכמים\u0004 על אשה שהיא \u0003בגדר\u0004 \u0003\"מגורשת ואינה מגורשת\"\u0004 — \u0003בעלה\u0004 עדיין \u0003חייב במזונותיה.\u0004 ואף על פי שאמרו חכמים כי מציאת אשה שייכת לבעלה וזכות זו מקבילה להתחייבותו שלו לספק לה את מזונותיה.","אולם \u0003טעמא מאי אמור רבנן\u0004 \u0005[מה טעם אמרו חכמים]\u0006 כי \u0003מציאת אשה לבעלה, כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא תיהוי\u0004 \u0005[תהיה]\u0006 \u0003לה איבה\u0004 מבעלה, שיאמר שהוא מפרנסה משלו וכעת כשמצאה דבר היא לוקחת אותו לעצמה, ולכן תקנו תקנה זו. \u0003הכא אית\u0004 \u0005[כאן יש]\u0006 \u0003לה איבה ואיבה,\u0004 שהרי מעוניינים אנו שיתן לה גט גמור ואין חוששים לריבוי איבה ביניהם ולכן דין הוא שתשאר מציאתה לעצמה.","\u0003מצא שטרי חוב, אם יש בהן,\u0004 בשטרות \u0003אחריות נכסים,\u0004 שכתוב בשטר שהוא משעבד את הנכסים שיש לו לפרעון חוב זה — \u0003לא יחזיר.\u0004 ומדוע — מפני \u0003שבית דין נפרעים מהן,\u0004 משטרות אלה וגובים את הנכסים גם אם נמכרו בינתיים לאחרים. ואם \u0003אין בהם אחריות נכסים\u0004 — \u0003יחזיר,\u0004 לפי \u0003שאין בית דין נפרעים מהן,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: בין כך ובין כך לא יחזיר מפני שבית דין נפרעים מהן\u0004 בכל מקרה.","שואלים: \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו],\u0006 כלומר, מה היה המקרה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003כש\u0004ה\u0003חייב מודה\u0004 שאכן כתב שטר זה והשטר לא נפרע, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003יש בהן אחריות נכסים אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא יחזיר? הא\u0004 \u0005[הרי]\u0006 הוא \u0003מודה!\u0004 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003כשאין\u0004 ה\u0003חייב מודה\u0004 וטוען שהשטר נפל ממנו לאחר שפרעו \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אין בהן אחריות נכסים\u0004 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003יחזיר?\u0004 שהרי \u0003נהי דלא גבי ממשעבדי\u0004 \u0005[שאם אמנם אינו גובה מ\u0006נכסים \u0005משועבדים]\u0006 שנמכרו כבר — אבל \u0003מבני חרי מגבא גבי\u0004 \u0005[מ\u0006נכסים \u0005בני חורין גובה\u0006 הוא\u0005]\u0006 בשטר זה, והרי הלווה טוען שאינו חייב עוד מאומה!","ומשיבים: \u0003לעולם\u0004 יש לפרש \u0003כש\u0004ה\u0003חייב מודה, והכא היינו טעמא\u0004 \u0005[וכאן זהו הטעם]:\u0006 \u0003דחיישינן\u0004 \u0005[שחוששים אנו]\u0006 \u0003שמא כתב ללות בניסן\u0004 שהוא התאריך שבשטר \u0003ולא לוה\u0004 בפועל \u0003עד תשרי\u0004 ובינתיים מניסן עד תשרי מכר קרקעות, והרי באמת אין כל שעבוד קודם חל על קרקעות אלה, לפי שלא נשתעבד הלווה לשלם עד שלווה בפועל, \u0003ואתי למטרף\u0004 \u0005[ויבוא לטרוף,\u0006 לקחת\u0005]\u0006 את השדות המכורים מן ה\u0003לקוחות שלא כדין.\u0004","ותוהים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שחוששים שמא תאריך השטר מוקדם להלוואה, אם כן \u0003כל שטרי דאתו לקמן ניחוש להו הכי\u0004 \u0005[השטרות הבאים לפנינו\u0006 לבית דין להפרע \u0005נחשוש להם כך]\u0006 שמא הקדימו את זמנם!","ודוחים: \u0003כל שטרי\u0004 \u0005[השטרות]\u0006 \u0003לא ריעי\u0004 \u0005[הורעה\u0006 חזקתן\u0005],\u0006 שהרי נשארו כראוי אצל המלוה ולא היה בהם שום פקפוק, \u0003הני ריעי\u0004 \u0005[אלה הורעה\u0006 חזקתן\u0005]\u0006 כאן שאבדו, וכיוון שיש בהם מקום לפקפוק חוששים אנו.","וממשיכים להקשות: \u0003אלא הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כותבים שטר ללוה אף על פי שאין\u0004 ה\u0003מלוה עמו,\u0004 שהרי הלווה הוא שמתחייב על ידי שטר זה. ואולם יש לתהות: מ\u0003לכתחילה היכי כתבינהו\u0004 \u0005[איך כתבו\u0006 שטר \u0005זה]?\u0006 \u0003ניחוש\u0004 \u0005[נחשוש]\u0006 \u0003שמא כתב ללות בניסן ו\u0004בסופו של דבר \u0003לא לוה עד תשרי, ואתי למטרף\u0004 \u0005[ויבוא לטרוף]\u0006 מן ה\u0003לקוחות שלא כדין!\u0004","\u0003אמר רב אסי:\u0004"],["\u0003בשטרי הקנאה.\u0004 כלומר, שטר שכתוב בו שהלווה משעבד למלווה נכסיו מתאריך כתיבת שטר זה בין אם ילווה בין אם לא, \u0003דהא שעביד נפשיה\u0004 \u0005[שהרי שעבד\u0006 את \u0005עצמו]\u0006 משעת ההקנאה ולא משעת ההלוואה בפועל, ולכן בדין יכול לטרוף מן הלקוחות.","ושואלים: \u0003אי הכי, מתניתין דקתני\u0004 \u0005[אם כך משנתנו ששנה]\u0006 בה: \u0003\"אם יש בהן אחריות נכסים\u0004 — \u0003לא יחזיר\", ואוקימנא\u0004 \u0005[והעמדנו,\u0006 הסברנו\u0005]\u0006 זאת \u0003כש\u0004ה\u0003חייב מודה, ומשום שמא כתב ללות בניסן ולא לוה עד תשרי, ואתי למטרף\u0004 \u0005[\u0006ויבוא \u0005לטרוף]\u0006 מן ה\u0003לקוחות שלא כדין, אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא יחזיר?\u0004","\u0003נחזי\u0004 \u0005[נראה]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 היה זה \u0003בשטר הקנאה\u0004 — \u0003הא שעביד ליה נפשיה\u0004 \u0005[הרי שיעבד לו\u0006 את \u0005עצמו]\u0006 מתאריך כתיבת השטר! \u0003אי\u0004 \u0005[אם]\u0006 היה זה \u0003ב\u0004שטר שהוא \u0003לא\u0004 שטר \u0003הקנאה\u0004 — \u0003ליכא למיחש\u0004 \u0005[אין לחשוש]\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמרת כי ליכא\u0004 \u0005[שכאשר אין]\u0006 \u0003מלוה בהדיה\u0004 \u0005[עמו]\u0006 \u0003לא כתבינן\u0004 \u0005[כותבים אנו]\u0006 ללווה אלא שטר הקנאה.","\u0003אמר\u0004 \u0003לו רב אסי:\u0004 אינו כן, \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 \u0003דשטרי דלאו\u0004 \u0005[ש\u0006אלה \u0005שטרות שאינם]\u0006 שטרי \u0003הקנאה, כי ליכא\u0004 \u0005[כאשר אין]\u0006 ה\u0003מלוה בהדיה\u0004 \u0005[עמו]\u0006 \u0003לא כתבינן\u0004 \u0005[אין אנו כותבים],\u0006 \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 יש להסביר כי \u0003כיון\u0004 ש\u0003נפל אתרע ליה, וחיישינן דלמא אקרי וכתוב\u0004 \u0005[הורע\u0006 תוקפו \u0005ואנו חוששים שמא הזדמן לו וכתב]\u0006 בכל זאת שלא כדין.","\u0003אביי אמר: עדיו בחתומיו זכין לו,\u0004 שכאשר חותמים העדים על השטר הרי הם מזכים את השעבוד עבור המלוה, וחל השעבוד מאותו רגע, \u0003ואפילו\u0004 היו אלה \u0003שטרי דלאו\u0004 \u0005[שטרות שלא]\u0006 עשויים \u0003ל\u0004\u0003הקנאה\u0004 מפורשת זה דינם.","וטעמו של הדבר — \u0003משום דקשיא ליה\u0004 \u0005[שהיה קשה לו]\u0006 \u0003כיון דאמרת בשטרי דלאו\u0004 \u0005[שאתה אומר שבשטרות שאינם]\u0006 שטרי \u0003הקנאה כי ליתיה\u0004 \u0005[כאשר אין]\u0006 ה\u0003מלוה בהדיה\u0004 \u0005[עמו]\u0006 \u0003לא כתבינן\u0004 \u0005[אין אנו כותבים]\u0006 שטרות אלה, גם \u0003ליכא למיחש דאקרי וכתוב\u0004 \u0005[אין לחשוש שהזדמן וכתב],\u0006 אלא יש לומר שעצם חתימת השטרות מחייבת.","ומקשים: \u0003אלא הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מצא גיטי נשים ושחרורי\u0004 (שטרי שחרור) \u0003עבדים, דייתיקי\u0004 (שטרי צוואה), שטרי \u0003מתנה ושוברים\u0004 (קבלות) על תשלומים — \u0003הרי זה לא יחזיר\u0004 לבעליהם, \u0003שמא כתובים היו ונמלך עליהם\u0004 כותבם \u0003שלא ליתנם.\u0004 ומעתה יש לשאול: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003נמלך עליהם מאי הוי\u0004 \u0005[מה היה\u0006 בכך\u0005]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרת\u0004 כי \u0003עדיו בחתומיו זכין לו,\u0004 שמיד עם חתימת השטר זכה בו המקבל, ואם כן מדוע לא יחזיר לו?","ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה ]\u0006 שזכה המקבל על ידי חתימה, אמורים דווקא \u0003היכא דקא מטו לידיה\u0004 \u0005[היכן ש\u0006השטרות \u0005הגיעו לידו],\u0006 שאכן נגמרה העיסקה. \u0003אבל היכא\u0004 \u0005[היכן,\u0006 כאשר\u0005]\u0006 \u0003לא מטו לידיה\u0004 \u0005[הגיעו לידו]\u0006 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים].\u0006","ושואלים: \u0003אלא מתניתין דקתני\u0004 \u0005[משנתנו ששנה\u0006 בה\u0005]\u0006 \u0003מצא שטרי חוב, אם יש בהם אחריות נכסים\u0004 — \u0003לא יחזיר. ואוקימנא\u0004 \u0005[והעמדנו,\u0006 הסברנו\u0005]\u0006 זאת דווקא \u0003כשחייב מודה, ומשום\u0004 החשש \u0003שמא כתב ללות בניסן ולא לוה עד תשרי.\u0004","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב אסי\u0004 ש\u0003אמר\u0004 שכותבים שטר ללווה רק \u0003בשטרי אקנייתא\u0004 \u0005[בשטרות הקנאה]\u0006 — \u0003מוקי לה בשטרי דלאו אקנייתא, וכדאמרינן\u0004 \u0005[מעמיד,\u0006 מסביר הוא, \u0005אותה,\u0006 את המשנה, \u0005בשטרות שאינם\u0006 שטרות \u0005הקנאה, וכפי שאמרנו],\u0006 \u0003אלא ל\u0004שיטת \u0003אביי,\u0004 ש\u0003אמר: עדיו בחתומיו זכין לו, מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 מדוע לא יחזיר שטרות גם אם יש בהם אחריות?","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך אביי\u0004 כי \u0003מתניתין היינו טעמא\u0004 \u0005[במשנתנו זה הטעם]:\u0006 \u0003דחייש\u0004 \u0005[שחושש\u0006 הוא\u0005]\u0006 \u0003לפרעון ולקנוניא.\u0004 שאף שהלווה מודה, אנו חוששים שמא עשו ביניהם הלווה והמלוה קנוניא (הסכם של מרמה) שלאחר שהלווה החזיר את הכסף, יטען המלוה שלא קבל מאומה, ויטרוף קרקעות שמכר הלווה במשך הזמן, וכסף זה יחלקו הלווה והמלוה ביניהם.","ושואלים: \u0003ול\u0004דעת \u0003שמואל,\u0004 ש\u0003אמר\u0004 ש\u0003לא חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לפרעון ולקנוניא, מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 כיצד נפרש את משנתנו? \u0003הניחא אי סבר לה\u0004 \u0005[זה נוח אם סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003רב אסי\u0004 ש\u0003אמר\u0004 שרק \u0003בשטרי הקנאה\u0004 כותבים שטר ללווה בלא המלוה — \u0003מוקי מתניתין בשטרי דלאו\u0004 \u0005[יעמיד את משנתנו בשטרות שאינם]\u0006 שטרות \u0003הקנאה.\u0004 \u0003אלא אי סבר\u0004 \u0005[אם סבור\u0006 הוא\u0005]\u0006 \u0003כ\u0004שיטת \u0003אביי\u0004 ש\u0003אמר עדיו בחתומיו זכין לו, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומשיבים: \u0003שמואל מוקי למתניתין\u0004 \u0005[מעמיד,\u0006 מסביר \u0005את משנתנו]\u0006 \u0003כשאין\u0004 ה\u0003חייב מודה,\u0004 ולכן אינו מחזיר.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאין החייב מודה, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אין בהן אחריות נכסים אמאי\u0004 \u0005[מדוע]\u0006 \u0003יחזיר? נהי דלא גבי מן משעבדי\u0004 \u0005[אם אמנם שאינו גובה מ\u0006נכסים \u0005משועבדים],\u0006 ואולם \u0003מבני חרי\u0004 \u0005[חורין]\u0006 הלא \u0003מגבי גבי\u0004 \u0005[\u0006הוא \u0005גובה]\u0006 שנוטל מנכסי הלווה, כאשר טוען הוא שכבר שילם!","ודוחים: \u0003שמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר שמואל, אומר היה ר' מאיר: שטר חוב שאין בו אחריות נכסים\u0004 — \u0003אין גובה\u0004 בו \u0003לא ממשעבדי\u0004 \u0005[מ\u0006נכסים \u0005משועבדים]\u0006 \u0003ולא מבני חרי\u0004 \u0005[חורין],\u0006 ולכן יכול להחזיר אותו.","ושואלים: \u0003וכי מאחר שאינו גובה אמאי\u0004 \u0005[מדוע]\u0006 \u0003יחזיר?\u0004 מה תועלת בשטר כזה? \u0003אמר ר' נתן בר אושעיא:\u0004 יחזיר את השטר \u0003לצור על פי צלוחיתו של מלוה,\u0004 שיוכל המלוה להשתמש בו כנייר בלבד.","ושואלים: \u0003ונהדריה להו\u0004 \u0005[ונחזיר אותו]\u0006 \u0003ללוה לצור על פי צלוחיתו של לוה!\u0004 שאם ערכו רק כנייר בלבד מדוע לא נחזירנו ללווה! ומשיבים: \u0003לוה הוא\u0004"],["\u0003אמר לא היו דברים מעולם\u0004 והשטר מזוייף, וכיון שכך, ודאי שאף נייר השטר אינו שייך לו.","\u0003אמר ר' אלעזר: מחלוקת\u0004 שבמשנתנו היא \u0003בשאין\u0004 ה\u0003חייב מודה,\u0004 ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003שטר שאין בו אחריות נכסים\u0004 — \u0003אינו גובה\u0004 בו \u0003לא ממשעבדי\u0004 \u0005[מ\u0006נכסים \u0005משועבדים]\u0006 \u0003ולא מ\u0004נכסים \u0003בני חרי\u0004 \u0005[חורין],\u0006 \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003ממשעבדי\u0004 \u0005[מ\u0006נכסים \u0005משועבדים]\u0006 \u0003הוא דלא גבי\u0004 \u0005[שאינו גובה],\u0006 ואולם \u0003מבני חרי\u0004 \u0005[חורין]\u0006 שלא שועבדו — \u0003מגבא גבי\u0004 \u0005[\u0006הריהו \u0005גובה].\u0006 \u0003אבל כשחייב מודה\u0004 — \u0003דברי הכל יחזיר, ולא חיישינן\u0004 \u0005[ואין אנו חוששים]\u0006 \u0003לפרעון,\u0004 שכבר נפרע השטר \u0003ו\u0004היתה זו רק \u0003קנוניא\u0004 בין המלוה והלווה על חשבון הלקוחות.","\u0003ו\u0004אילו \u0003ר' יוחנן אמר: מחלוקת\u0004 זו היא דווקא \u0003כשחייב מודה,\u0004 ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003שטר שאין בו אחריות נכסים, ממשעבדי\u0004 \u0005[ממשועבדים]\u0006 \u0003הוא דלא גבי\u0004 \u0005[שאינו גובה]\u0006 \u0003אבל מבני חרי\u0004 \u0005[חורין]\u0006 — \u0003מגבא גבי\u0004 \u0005[\u0006הריהו \u0005גובה].\u0006 \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 כי \u0003ממשעבדי נמי גבי\u0004 \u0005[ממשועבדים גם כן גובה].\u0006 \u0003אבל כשאין\u0004 ה\u0003חייב מודה\u0004 — \u0003דברי הכל לא יחזיר,\u0004 משום \u0003דחיישינן\u0004 \u0005[שאנו חוששים]\u0006 \u0003לפרעון.\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנוייה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן\u0004 \u0003ו\u0004ממנה תהא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לדברי \u0003ר' אלעזר בחדא\u0004 \u0005[ב\u0006דבר \u0005אחד],\u0006 \u0003ותיובתא\u0004 \u0005[וקושיה חמורה]\u0006 לדברי \u0003שמואל בתרתי\u0004 \u0005[בשני\u0006 דברים\u0005].\u0006","וזו הברייתא: \u0003מצא שטרי חוב ויש בהם אחריות נכסים, אף על פי ששניהם,\u0004 הלווה והמלוה, \u0003מודים\u0004 — \u0003לא יחזיר\u0004 את השטר \u0003לא לזה ולא לזה.\u0004 ואולם אם \u0003אין בהן אחריות נכסים, בזמן שהלוה מודה\u0004 — \u0003יחזיר למלוה,\u0004 ואם \u0003אין הלוה מודה, לא יחזיר לא לזה ולא לזה,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003שהיה ר' מאיר אומר: שטרי\u0004 \u0005[שטרות]\u0006 \u0003שיש\u0004 \u0003בהן אחריות נכסים, גובה\u0004 בהם \u0003מנכסים משועבדים, ושאין בהם אחריות נכסים\u0004 אינו \u0003גובה\u0004 בהם אלא \u0003מנכסים בני חורין. וחכמים אומרים: אחד זה ואחד זה גובה מנכסים משועבדים.\u0004","ואם כן מכאן תהא \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לדברי \u0003ר' אלעזר בחדא\u0004 \u0005[ב\u0006דבר \u0005אחד],\u0006 שהרי ר' אלעזר \u0003אמר\u0004 ש\u0003ל\u0004דעת \u0003ר' מאיר שטר שאין בו אחריות נכסים\u0004 — \u0003אינו גובה\u0004 בו \u0003מנכסים משועבדים ולא מנכסים בני חורין. וקאמר\u0004 \u0005[ו\u0006עוד \u0005אמר]\u0006 ר' אלעזר ש\u0003בין ל\u0004שיטת \u0003ר' מאיר\u0004 ו\u0003בין לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 \u0003לא חיישינן לקנוניא\u0004 \u0005[אין אנו חוששים לקנוניה]\u0006 בין הלווה בין המלוה.","\u0003ו\u0004אילו ה\u0003ברייתא קתני\u0004 \u0005[שונה]\u0006 ש\u0003שטר שאין בו אחריות נכסים\u0004 — \u0003ממשעבדי\u0004 \u0005[ממשועבדים]\u0006 \u0003הוא דלא גבי\u0004 \u0005[שאינו גובה],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 מכאן ש\u0003מבני חורין מגבא גבי\u0004 \u0005[\u0006הריהו \u0005גובה].\u0006 \u0003וקתני\u0004 \u0005[שנה\u0006 שם\u0005]\u0006 \u0003בין ל\u0004שיטת \u0003ר' מאיר בין לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לקנוניא. דקתני\u0004 \u0005[ש\u0006הרי \u0005שנינו]\u0006 ששטרות שיש בהם אחריות נכסים \u0003אף על פי ששניהם מודים\u0004 — \u0003לא יחזיר לא לזה ולא לזה.\u0004 \u0003אלמא\u0004 \u0005[מכאן]\u0006 כי \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לקנוניא.\u0004 זו הפירכה לדברי ר' אלעזר מן הברייתא.","ואולם שואלים על לשון התלמוד עצמו \u0003והא הני תרתי הוא\u0004 \u0005[והרי אלה שתי\u0006 קושיות \u0005הן]\u0006 ומדוע אמרת שיש מכאן קושיה לר' אלעזר רק בדבר אחד?"]]};
